# ── Live deliverability audit cache (background runner) ──────────────────────
# The audit backend's POST /api/run does a full live Smartlead sweep and takes
# ~4 minutes — far too long to hold a browser->proxy request open. So we run it
# server-side in a daemon thread and cache the result: the tab reads the cached
# blob instantly via GET /api/deliverability/_audit and asks for a refresh via
# POST /api/deliverability/_audit/refresh only when it's stale/missing. All other
# /api/deliverability/* calls (inboxes, domain-health, actions…) still stream
# through the plain _proxy_deliverability() forwarder.
_DELIV_AUDIT = {"blob": None, "ts": 0.0, "running": False, "error": None, "restore_tried": False}
_DELIV_AUDIT_LOCK = threading.Lock()
_DELIV_AUDIT_TTL_S = 7200  # 2h refresh cadence (owner spec 2026-07-11); hourly cron tick no-ops while fresh


def _deliv_fix_batch_stats(blob):
    """Replace batchStats' sent/reply/bounce with sweep-delta truth.

    The audit backend derives per-batch Sent(7d)/Reply%/Bounce% from its
    domain-health row set, which is hard-capped at ~59 domains — verified live
    2026-07-10: batch sends summed to 18,765 while the fleet sent 85,292 in the
    same window (78% unattributed), and the navreo maildoso pool showed "—"
    while actually sending ~600/day across 38 small domains that never crack
    the top-59. Mailbox/warmup/blacklist columns are accurate; only the
    performance columns lie.

    Correction: per-mailbox deltas between the two most recent daily sweeps
    within the last 8 days (mailbox_stats_daily.sent_30d/replies_30d/
    bounces_30d are trailing-30d counters, so newest-minus-oldest ≈ sends in
    that gap; sends aging out of the 30d window can only UNDER-count, never
    invent). Pools are keyed person+provider, matched to the backend's batch
    names, which embed the same person slug + provider suffix. Skips silently
    (backend numbers kept) when fewer than 2 sweeps exist or Supabase is down.
    Stamps blob["batchWindowDays"] so the UI can label the real window."""
    try:
        from datetime import date, timedelta
        if not isinstance(blob, dict) or not isinstance(blob.get("batchStats"), list):
            return
        cutoff = (date.today() - timedelta(days=8)).isoformat()
        dates = sb("GET", f"mailbox_stats_daily?select=stat_date&stat_date=gte.{cutoff}"
                          "&order=stat_date.desc&limit=1", prefer="return=representation")
        if not dates:
            return
        newest = dates[0]["stat_date"]
        older = sb("GET", f"mailbox_stats_daily?select=stat_date&stat_date=gte.{cutoff}"
                          f"&stat_date=lt.{newest}&order=stat_date.asc&limit=1",
                   prefer="return=representation")
        if not older:
            return  # only one sweep so far — no delta window yet
        base = older[0]["stat_date"]
        stats = sb_get_all("mailbox_stats_daily?select=smartlead_id,stat_date,sent_30d,replies_30d,bounces_30d"
                           f"&stat_date=in.({base},{newest})")
        boxes = sb_get_all("mailboxes?select=smartlead_id,from_name,smtp_host,tags")
        if not stats or not boxes:
            return
        def pool_of(m):
            person = (m.get("from_name") or "?").strip().lower().replace(" ", "-")
            blobtags = str(m.get("tags") or "").lower()
            host = (m.get("smtp_host") or "").lower()
            if "maildoso" in host or "maildoso" in blobtags:
                prov = "maildoso"
            elif "boomerang" in blobtags:
                prov = "boomerang"
            else:
                prov = ""
            return person, prov
        pools = {m["smartlead_id"]: pool_of(m) for m in boxes}
        per_box = {}
        for s in stats:
            row = per_box.setdefault(s["smartlead_id"], {})
            row[s["stat_date"]] = s
        agg = {}
        for sid, by_date in per_box.items():
            a, b = by_date.get(base), by_date.get(newest)
            if not a or not b or sid not in pools:
                continue
            key = pools[sid]
            d = agg.setdefault(key, {"sent": 0, "replies": 0, "bounces": 0})
            d["sent"] += max(0, (b.get("sent_30d") or 0) - (a.get("sent_30d") or 0))
            d["replies"] += max(0, (b.get("replies_30d") or 0) - (a.get("replies_30d") or 0))
            d["bounces"] += max(0, (b.get("bounces_30d") or 0) - (a.get("bounces_30d") or 0))
        from datetime import datetime as _dt
        window_days = ( _dt.fromisoformat(newest) - _dt.fromisoformat(base) ).days or 1
        fixed = 0
        for row in blob["batchStats"]:
            name = str(row.get("batch") or "").lower()
            if name == "(no batch)":
                continue
            prov = "maildoso" if name.endswith("maildoso") else ("boomerang" if name.endswith("boomerang") else "")
            match = None
            for (person, p2), vals in agg.items():
                if p2 == prov and person and person in name:
                    match = vals
                    break
            if match is None:
                continue
            row["sent"] = match["sent"]
            row["reply_rate"] = round(100.0 * match["replies"] / match["sent"], 2) if match["sent"] else 0
            row["bounce_rate"] = round(100.0 * match["bounces"] / match["sent"], 2) if match["sent"] else 0
            fixed += 1
        blob["batchWindowDays"] = window_days
        print(f"[deliv] batchStats corrected from sweep deltas ({base}->{newest}, "
              f"{window_days}d window, {fixed} batches)", file=sys.stderr)
    except Exception as e:  # noqa: BLE001 — correction is best-effort, never break the audit
        print(f"[deliv] WARNING batchStats correction failed: {e}", file=sys.stderr)


# Provider pools we always want visible in Performance-by-batch even when the
# external audit engine omits them. That engine lists only pools that are
# ACTIVELY sending on a short (~3-day) window, so a warmed pool sitting between
# campaigns (e.g. sending.ac — 300 boxes that ran through early Aug then went
# idle) silently vanishes from the tab. Each entry is identified by the sender
# DOMAINS provisioned for that provider: the Supabase mirror carries no
# Smartlead tags, and for a bought-infrastructure pool the domains ARE the pool.
# If a provider gains domains, add them here (resolve from the Smartlead tag).
_DELIV_MANUAL_BATCHES = (
    {"label": "navreo-bjion-henry-sending.ac",
     "domains": ("navreomeetingsbooked.com", "navreogtmengine.com", "navreolab.com",
                 "navreobookedcalls.com", "navreogrowthengine.com", "navreodealflow.com")},
)


def _deliv_add_manual_batches(blob):
    """Append batchStats rows for the _DELIV_MANUAL_BATCHES pools the audit
    engine didn't already surface. Computed from the SAME authoritative sources
    as _deliv_fix_batch_stats — Supabase `mailboxes` (fleet/health) +
    `mailbox_stats_daily` (trailing-30d counters). Each row carries
    window-consistent Sent/Reply/Bounce (so it sits correctly beside the
    engine's rows) plus 30-day extras and an `idle` flag for a warmed pool
    that's currently between campaigns. Idempotent + best-effort: a label the
    engine already emitted is skipped, and any failure leaves batchStats
    untouched."""
    try:
        from datetime import date, datetime, timedelta
        if not isinstance(blob, dict) or not isinstance(blob.get("batchStats"), list):
            return
        existing = {str(r.get("batch", "")).lower() for r in blob["batchStats"]}
        specs = [s for s in _DELIV_MANUAL_BATCHES if s["label"].lower() not in existing]
        if not specs:
            return
        # Same sweep-delta window _deliv_fix_batch_stats uses, so a manual row's
        # Sent/Reply/Bounce mean exactly what every engine row beside it means.
        cutoff = (date.today() - timedelta(days=8)).isoformat()
        dnew = sb("GET", f"mailbox_stats_daily?select=stat_date&stat_date=gte.{cutoff}"
                         "&order=stat_date.desc&limit=1", prefer="return=representation")
        newest = dnew[0]["stat_date"] if dnew else None
        base = None
        if newest:
            dold = sb("GET", f"mailbox_stats_daily?select=stat_date&stat_date=gte.{cutoff}"
                             f"&stat_date=lt.{newest}&order=stat_date.asc&limit=1", prefer="return=representation")
            base = dold[0]["stat_date"] if dold else None

        def _pool_stats(sids, dates_in):
            rows = []
            for i in range(0, len(sids), 200):  # keep each id-filtered page well under PostgREST's 1000-row cap
                inlist = ",".join(str(s) for s in sids[i:i + 200])
                page = sb("GET", "mailbox_stats_daily?select=smartlead_id,stat_date,sent_30d,replies_30d,bounces_30d"
                                 f"&smartlead_id=in.({inlist})&stat_date=in.({dates_in})")
                if isinstance(page, list):
                    rows.extend(page)
            return rows

        for spec in specs:
            dom_list = ",".join('"%s"' % d for d in spec["domains"])
            boxes = sb_get_all("mailboxes?select=smartlead_id,domain,warmup_status,campaign_count,"
                               "blocked_reason,smtp_ok,imap_ok&order=smartlead_id"
                               "&domain=in.(%s)" % dom_list)
            if not boxes:  # None (Supabase down) or [] (no such domains) — skip, don't invent a row
                continue
            sids = [b["smartlead_id"] for b in boxes if b.get("smartlead_id") is not None]
            mailboxes = len(boxes)
            domains = len({b.get("domain") for b in boxes})
            # Health flags (dead/blocked) come from the mirror — the same source
            # the engine's own dead/blocked columns use. Sending vs warmup and
            # the `idle` flag are derived from ACTUAL send activity below, NOT
            # the mirror's campaign_count: that column is a daily snapshot that
            # lags reality (seen live 2026-08 — mirror still said "in 41
            # campaigns" days after the pool had detached and gone quiet).
            dead = sum(1 for b in boxes if b.get("smtp_ok") is False or b.get("imap_ok") is False)
            blocked = sum(1 for b in boxes if b.get("blocked_reason"))

            want = ",".join(d for d in (newest, base) if d)
            per = {}
            for s in (_pool_stats(sids, want) if (sids and want) else []):
                per.setdefault(s["smartlead_id"], {})[s["stat_date"]] = s
            sent30 = rep30 = bnc30 = 0          # trailing-30d (newest counter per box)
            wsent = wrep = wbnc = 0             # window delta (newest - base), same window as engine rows
            active = 0                          # boxes that actually sent across the window
            for by_date in per.values():
                n = by_date.get(newest)
                s_new = (n.get("sent_30d") or 0) if n else 0
                if n:
                    sent30 += s_new
                    rep30 += n.get("replies_30d") or 0
                    bnc30 += n.get("bounces_30d") or 0
                a = by_date.get(base) if base else None
                if base and a and n:
                    dsent = max(0, s_new - (a.get("sent_30d") or 0))
                    wsent += dsent
                    wrep += max(0, (n.get("replies_30d") or 0) - (a.get("replies_30d") or 0))
                    wbnc += max(0, (n.get("bounces_30d") or 0) - (a.get("bounces_30d") or 0))
                    if dsent > 0:
                        active += 1
                elif not base and s_new > 0:   # only one sweep on record — fall back to any recent sends
                    active += 1
            sending = active
            warmup = mailboxes - active         # warmed, but sent nothing across the window
            idle = active == 0                  # whole pool quiet — surfaces the "idle" badge + 30d history

            row = {
                "batch": spec["label"], "mailboxes": mailboxes, "domains": domains,
                "sending": sending, "warmup": warmup, "dead": dead, "blocked": blocked,
                "blacklisted": 0, "sent": wsent,
                "reply_rate": round(100.0 * wrep / wsent, 2) if wsent else 0,
                "bounce_rate": round(100.0 * wbnc / wsent, 2) if wsent else 0,
                "positive_rate": 0,
                # Extras the batch table surfaces for a warmed pool between
                # campaigns: an "idle" badge + its real trailing-30d numbers,
                # so an idle pool reads as "here, and how it last performed"
                # rather than a blank row.
                "idle": idle,
                "sent30": sent30,
                "reply30": round(100.0 * rep30 / sent30, 2) if sent30 else 0,
                "bounce30": round(100.0 * bnc30 / sent30, 2) if sent30 else 0,
            }
            blob["batchStats"].append(row)
            print(f"[deliv] manual batch '{spec['label']}' added ({mailboxes} mbx, {domains} dom, "
                  f"window sent={wsent}, 30d sent={sent30}, idle={row['idle']})", file=sys.stderr)
    except Exception as e:  # noqa: BLE001 — never break the audit over a display extra
        print(f"[deliv] WARNING manual batch add failed: {e}", file=sys.stderr)


def _deliv_audit_persist(blob):
    """Best-effort: mirror the finished audit blob to Supabase so it survives
    process restarts. Deploys restart the process and wiped the in-memory
    cache 8+ times on 2026-07-10 alone (two sessions shipping), each time
    costing a ~5-min re-audit and a 'no live data' page. sb() is already
    best-effort + retry-once, so an outage can never break the audit path."""
    from datetime import datetime, timezone
    try:
        sb("POST", "deliverability_audit_cache?on_conflict=id",
           {"id": "audit", "blob": blob, "ts": datetime.now(timezone.utc).isoformat()},
           prefer="resolution=merge-duplicates,return=minimal")
    except Exception as e:  # noqa: BLE001
        print(f"[deliv] WARNING audit persist failed: {e}", file=sys.stderr)


def _deliv_iso_epoch(ts: str) -> float:
    """Epoch seconds for a Supabase ISO timestamp, tolerant of fractional-
    second widths fromisoformat rejects on Python <3.11 (e.g. '.31426'). A
    silent 0.0 here made a restored bundle look infinitely stale — the
    freshness check then re-kicked a refresh on every GET."""
    from datetime import datetime
    s = (ts or "").replace("Z", "+00:00")
    try:
        return datetime.fromisoformat(s).timestamp()
    except ValueError:
        import re
        try:
            s = re.sub(r"\.(\d+)", lambda m: "." + (m.group(1) + "000000")[:6], s)
            return datetime.fromisoformat(s).timestamp()
        except Exception:  # noqa: BLE001
            return 0.0


def _deliv_audit_restore():
    """One attempt per process lifetime: if the in-memory cache is empty (fresh
    process), pull the last persisted blob so the page has real data instantly
    instead of a 'no live data' gap until a ~5-min audit completes. Stale-ness
    still applies — the normal TTL logic decides whether to refresh."""
    with _DELIV_AUDIT_LOCK:
        if _DELIV_AUDIT["restore_tried"] or _DELIV_AUDIT["blob"] is not None or _deliv_mock_on():
            return
        # a FAILED restore must not consume the one shot (a Supabase blip at
        # boot used to mean an empty page until the next full audit) — retry
        # on later requests, but at most every 30s
        if time.time() - _DELIV_AUDIT.get("restore_last_try", 0.0) < 30:
            return
        _DELIV_AUDIT["restore_last_try"] = time.time()
    from datetime import datetime
    try:
        rows = sb("GET", "deliverability_audit_cache?id=eq.audit&select=blob,ts", prefer="return=representation")
        if rows is not None:  # sb() returns None (not an exception) on failure —
            # only a definitive read (row present or absent) stops the retries
            with _DELIV_AUDIT_LOCK:
                _DELIV_AUDIT["restore_tried"] = True
        if rows and isinstance(rows, list) and rows[0].get("blob"):
            ts = rows[0].get("ts") or ""
            epoch = _deliv_iso_epoch(ts)
            with _DELIV_AUDIT_LOCK:
                if _DELIV_AUDIT["blob"] is None:  # a live run may have landed meanwhile
                    _DELIV_AUDIT.update(blob=rows[0]["blob"], ts=epoch)
            print(f"[deliv] audit blob restored from Supabase (stored {ts})", file=sys.stderr)
    except Exception as e:  # noqa: BLE001
        print(f"[deliv] WARNING audit restore failed: {e}", file=sys.stderr)


def _deliv_mock_on() -> bool:  # DELIV_MOCK
    """True only when DELIV_MOCK=1 is set in the environment — the single gate
    every mock hook below checks. Absent (prod default) → always False, so
    every gated block below is a dead no-op and behavior is byte-for-byte
    unchanged."""
    return os.environ.get("DELIV_MOCK") == "1"


_DELIV_REST_DAYS_MS = 7 * 86400 * 1000


def _deliv_fix_resting_due(dh):
    """The audit backend's `restingDue` map holds the timestamp a domain was
    PUT to rest (pause moment, ms) — not when the rest ends. The dashboard
    renders the value as a due-back date, so a freshly-rested domain flipped
    to "due now" as soon as a domain-health refetch replaced the client's
    local 7-day clock (verified live 2026-07-10: all 83 values sat in the
    past, each equal to its own pause moment). Shift every value to
    rested_at + 7 days on the way through, so all clients see the 7-day
    pause the warm-up dialog promises. If the backend ever starts sending
    real end dates, drop this shift."""
    if isinstance(dh, dict) and isinstance(dh.get("restingDue"), dict):
        dh["restingDue"] = {k: v + _DELIV_REST_DAYS_MS
                            for k, v in dh["restingDue"].items()
                            if isinstance(v, (int, float))}


def _deliv_audit_run_bg():
    """Fire the ~4-min live audit against the backend once; store blob or error."""
    if _deliv_mock_on():  # DELIV_MOCK — fake a short "run", then store a fresh mock blob
        try:
            secs = mock_deliv.scenario_get("audit_run_secs", 3) or 3
            time.sleep(secs)
            blob = mock_deliv.run_audit_blob()
            _deliv_fix_resting_due((blob or {}).get("domainHealth"))  # same shift as the live path
            with _DELIV_AUDIT_LOCK:
                _DELIV_AUDIT.update(blob=blob, ts=time.time(), running=False, error=None)
            _deliv_bundle_start(force=True)  # mock bundle rides the same refresh as prod
        except Exception as e:  # noqa: BLE001 — running=True must never outlive the thread
            with _DELIV_AUDIT_LOCK:
                _DELIV_AUDIT.update(running=False, error=str(e)[:300])
        return
    import base64, urllib.error  # noqa: F401 — urllib.error referenced via except below
    auth = os.environ.get("DELIV_AUDIT_AUTH") or KEYS.get("DELIV_AUDIT_AUTH") or ""
    if ":" not in auth:
        with _DELIV_AUDIT_LOCK:
            _DELIV_AUDIT.update(running=False, error="unconfigured")
        return
    try:
        req = urllib.request.Request(
            "https://navreo-email-deliverability-audit.onrender.com/api/run", data=b"", method="POST")
        req.add_header("Authorization", "Basic " + base64.b64encode(auth.encode()).decode())
        req.add_header("Content-Type", "application/json")
        # 2026-07-09: full audits started overrunning the old 330s cap (Smartlead
        # slows under load), leaving the cache blob-less and the UI stuck kicking
        # refreshes forever — give the run real headroom.
        with urllib.request.urlopen(req, timeout=600, context=SSL_CTX) as resp:
            blob = json.loads(resp.read())
        _deliv_fix_resting_due((blob or {}).get("domainHealth"))
        _deliv_fix_batch_stats(blob)  # replace top-59-domain batch metrics with sweep-delta truth
        _deliv_add_manual_batches(blob)  # surface warmed provider pools (e.g. sending.ac) the engine skips while idle
        with _DELIV_AUDIT_LOCK:
            _DELIV_AUDIT.update(blob=blob, ts=time.time(), running=False, error=None)
        _deliv_audit_persist(blob)  # survives the next deploy/restart
        _snapshot_from_blob(blob)  # daily fleet-count row for the trends header
        _deliv_bundle_start(force=True)  # keep manager views/windows coherent with the fresh blob
    except Exception as e:  # noqa: BLE001 — record the failure for the UI; never crash the thread
        with _DELIV_AUDIT_LOCK:
            _DELIV_AUDIT.update(running=False, error=str(e)[:300])


def _deliv_audit_start(force=False):
    """Kick a background refresh unless one's already running (or cache is fresh
    and not forced). Returns a small state dict for the caller."""
    _deliv_audit_restore()  # fresh process: recover the last persisted blob first
    with _DELIV_AUDIT_LOCK:
        if _DELIV_AUDIT["running"]:
            return {"started": False, "running": True}
        fresh = _DELIV_AUDIT["blob"] is not None and (time.time() - _DELIV_AUDIT["ts"]) < _DELIV_AUDIT_TTL_S
        if fresh and not force:
            return {"started": False, "running": False, "fresh": True}
        _DELIV_AUDIT.update(running=True, error=None)
    threading.Thread(target=_deliv_audit_run_bg, daemon=True).start()
    return {"started": True, "running": True}


# ── Live deliverability BUNDLE cache (manager views + domain-health windows) ──
# The manager's per-view GET /inboxes and per-window GET /domain-health each
# round-trip the audit backend live (45s / 87s measured on prod 2026-07-11,
# worse while the ~4-min sweep runs) — that is what made sub-tab clicks look
# dead for minutes. Same medicine as _DELIV_AUDIT: pull everything the manager
# can show ONCE in a background thread, serve it from cache instantly, refresh
# behind the scenes. Re-pulled after every successful audit run (so blob and
# bundle stay coherent) and covered by the hourly /api/cron/audit-refresh kick.
# Views deliberately exclude "sending"/"all": the backend truncates at 2,000
# rows with no pagination (probed live: limit/offset are ignored; batch tags
# overlap so partitioning can't reach the 7,997-box fleet either) and the
# four manager flows only need the small actionable views.
_DELIV_BUNDLE_VIEWS = ("warmupoff", "inwarmup", "rested", "reconnect", "blocked")
_DELIV_BUNDLE_WINDOWS = (7, 14, 30)
_DELIV_BUNDLE = {"data": None, "ts": 0.0, "running": False, "error": None, "restore_tried": False}
_DELIV_BUNDLE_LOCK = threading.Lock()


def _deliv_backend_get(rest: str, timeout: int = 240):
    """Authed GET against the audit backend (or the mock fleet under
    DELIV_MOCK=1) from a background thread — the request-handler proxy can't
    be used off-request. Returns the parsed JSON body or raises."""
    if _deliv_mock_on():
        status, obj = mock_deliv.handle_proxy("GET", rest, None)
        if status != 200:
            raise RuntimeError(f"mock {rest} -> {status}")
        return obj
    import base64
    auth = os.environ.get("DELIV_AUDIT_AUTH") or KEYS.get("DELIV_AUDIT_AUTH") or ""
    if ":" not in auth:
        raise RuntimeError("unconfigured")
    req = urllib.request.Request(
        "https://navreo-email-deliverability-audit.onrender.com/api/" + rest, method="GET")
    req.add_header("Authorization", "Basic " + base64.b64encode(auth.encode()).decode())
    with urllib.request.urlopen(req, timeout=timeout, context=SSL_CTX) as resp:
        return json.loads(resp.read())


def _deliv_bundle_persist(data):
    from datetime import datetime, timezone
    try:
        sb("POST", "deliverability_audit_cache?on_conflict=id",
           {"id": "bundle", "blob": data, "ts": datetime.now(timezone.utc).isoformat()},
           prefer="resolution=merge-duplicates,return=minimal")
    except Exception as e:  # noqa: BLE001
        print(f"[deliv] WARNING bundle persist failed: {e}", file=sys.stderr)


def _deliv_bundle_restore():
    with _DELIV_BUNDLE_LOCK:
        if _DELIV_BUNDLE["restore_tried"] or _DELIV_BUNDLE["data"] is not None or _deliv_mock_on():
            return
        # failed restores retry (see _deliv_audit_restore) — capped at every 30s
        if time.time() - _DELIV_BUNDLE.get("restore_last_try", 0.0) < 30:
            return
        _DELIV_BUNDLE["restore_last_try"] = time.time()
    from datetime import datetime
    try:
        rows = sb("GET", "deliverability_audit_cache?id=eq.bundle&select=blob,ts", prefer="return=representation")
        if rows is not None:  # sb() returns None on failure — see audit restore
            with _DELIV_BUNDLE_LOCK:
                _DELIV_BUNDLE["restore_tried"] = True
        if rows and isinstance(rows, list) and rows[0].get("blob"):
            # Belt-and-braces vs the mock-poisoning incident: refuse any
            # persisted bundle stamped mock, whatever wrote it.
            if isinstance(rows[0]["blob"], dict) and rows[0]["blob"].get("mock"):
                print("[deliv] ignoring mock-stamped bundle in Supabase", file=sys.stderr)
                return
            ts = rows[0].get("ts") or ""
            epoch = _deliv_iso_epoch(ts)
            with _DELIV_BUNDLE_LOCK:
                if _DELIV_BUNDLE["data"] is None:
                    _DELIV_BUNDLE.update(data=rows[0]["blob"], ts=epoch)
            print(f"[deliv] bundle restored from Supabase (stored {ts})", file=sys.stderr)
    except Exception as e:  # noqa: BLE001
        print(f"[deliv] WARNING bundle restore failed: {e}", file=sys.stderr)


_LEDGER_DEFEND_MEMO = {"key": None, "ts": 0.0}


def _ledger_delete_due_only(doms, have=None, reason=""):
    """Delete resting-ledger rows for `doms` ONLY where the 7-day rest has
    actually been served (first_rested_at past the clock). A row that is NOT
    yet due but whose domain has left the resting census is not a restore we
    honour — it is the signature of the park↔restore ping-pong (an audit-side
    restore, or a park that never landed in Smartlead): deleting it is what
    wiped rest clocks daily through Aug 2026. Those rows are DEFENDED — kept,
    surfaced with their real due-back date, and re-parked by rest_enforce().
    Dismissed rows (retired from auto-restore) are never deleted here.
    Returns {"deleted": [...], "defended": {domain: due_epoch_ms}}."""
    from datetime import datetime
    doms = [str(d).lower() for d in (doms or []) if d]
    if not doms:
        return {"deleted": [], "defended": {}}
    if have is None:
        have = {}
        for i in range(0, len(doms), 60):
            for r in sb("GET", "deliverability_resting_ledger"
                               "?select=domain,first_rested_at,dismissed"
                               "&domain=in.(%s)" % ",".join(doms[i:i + 60])) or []:
                have[str(r.get("domain") or "").lower()] = r
    now_ms = int(time.time() * 1000)
    deletable, defended = [], {}
    for d in doms:
        row = have.get(d)
        if not row:
            continue
        due_ms = None
        try:
            due_ms = int(datetime.fromisoformat(
                str(row.get("first_rested_at")).replace("Z", "+00:00")
            ).timestamp() * 1000) + _DELIV_REST_DAYS_MS
        except Exception:  # noqa: BLE001 — unparseable clock: treat as due (old behavior)
            pass
        if row.get("dismissed"):
            continue  # retired-from-restore rows are owned by restore-dismiss
        if due_ms is None or now_ms >= due_ms:
            deletable.append(d)
        else:
            defended[d] = due_ms
    for i in range(0, len(deletable), 80):
        sb("DELETE", "deliverability_resting_ledger?domain=in.(%s)"
                     % ",".join(deletable[i:i + 80]))
    if defended:
        # One log line when the defended set changes (not per sweep — the
        # bundle refreshes often), so the tug-of-war is visible in the panel.
        key = ",".join(sorted(defended))
        if key != _LEDGER_DEFEND_MEMO["key"] or time.time() - _LEDGER_DEFEND_MEMO["ts"] > 6 * 3600:
            _LEDGER_DEFEND_MEMO.update(key=key, ts=time.time())
            try:
                log_activity("/api/deliverability/_bundle",
                             payload={"reason": reason or "left resting census",
                                      "domains": sorted(defended)[:40],
                                      "count": len(defended)},
                             actor="deliverability", action="rest_clock_defended",
                             entity="domain")
            except Exception:  # noqa: BLE001 — logging must never break the sweep
                pass
    return {"deleted": deletable, "defended": defended}


def _deliv_resting_ledger_sync(rested_doms, allow_delete=True):
    """Authoritative due-back dates. The audit backend RE-STAMPS its
    restedAt/restingDue values on every sweep (verified live 2026-07-11:
    1,997/2,000 rested mailboxes carried the latest sweep's timestamp), so a
    +7d shift of its values reads "due in 7d" forever and nothing ever comes
    due. This ledger records when WE first saw each domain rested and derives
    due = first_rested_at + 7d. Sync: new rested domains are inserted at now
    (accurate to one refresh interval); restored domains are deleted so a
    later re-rest starts a fresh clock (skipped when the rested view arrived
    truncated — a missing row must not reset a domain's clock).
    Returns {domain: due_epoch_ms}."""
    from datetime import datetime, timezone
    rows = sb_get_all("deliverability_resting_ledger?select=domain,first_rested_at") or []
    have = {str(r.get("domain") or "").lower(): r for r in rows}
    now_iso = datetime.now(timezone.utc).isoformat()
    new = sorted(d for d in rested_doms if d not in have)
    if new:
        sb("POST", "deliverability_resting_ledger?on_conflict=domain",
           [{"domain": d, "first_rested_at": now_iso, "approx": False, "last_seen_at": now_iso}
            for d in new],
           prefer="resolution=ignore-duplicates,return=minimal")
    defended = {}
    deleted = []
    if allow_delete:
        gone = _safe_domains(sorted(d for d in have if d not in rested_doms))
        res = _ledger_delete_due_only(gone, have=have, reason="left resting census")
        deleted, defended = res["deleted"], res["defended"]
    if new or deleted:
        _restore_plan_invalidate()  # ledger changed — restore-plan must re-read
    due = {}
    now_ms = int(time.time() * 1000)
    for d in rested_doms:
        fr = (have.get(d) or {}).get("first_rested_at")
        if fr:
            try:
                due[d] = int(datetime.fromisoformat(str(fr).replace("Z", "+00:00")).timestamp() * 1000) + _DELIV_REST_DAYS_MS
                continue
            except Exception:  # noqa: BLE001
                pass
        due[d] = now_ms + _DELIV_REST_DAYS_MS  # first seen this sweep
    for d, due_ms in defended.items():
        # Defended rows: the census lost the domain mid-rest (ping-pong), but
        # the clock stands — keep it in restDue so the Resting tab still shows
        # it with its true due-back and the cap engines keep skipping it.
        due.setdefault(d, due_ms)
    return due


def _deliv_bundle_run_bg():
    """Thread entry — any escape from the inner run must still clear running,
    or the 2h refresh silently wedges forever (same pattern as
    _restore_sweep_run_bg)."""
    try:
        _deliv_bundle_run_bg_inner()
    except Exception as e:  # noqa: BLE001 — running=True must never outlive the thread
        with _DELIV_BUNDLE_LOCK:
            _DELIV_BUNDLE.update(running=False, error=str(e)[:300])


_INSTANTLY_BASE = "https://api.instantly.ai/api/v2"
_APP_SECRETS_CACHE: dict = {}


def _app_secret(name: str) -> str | None:
    """Env-first secret with a Supabase `app_secrets` fallback (RLS on, zero
    policies — service-role only). Exists because Render's env can't be edited
    from here: a key added to the DB unblocks a feature without a dashboard
    trip; the same-named env var still wins the moment it's set. 10-min cache."""
    v = KEYS.get(name)
    if v:
        return v
    hit = _APP_SECRETS_CACHE.get(name)
    if hit and hit[1] > time.time() - 600:
        return hit[0]
    val = None
    try:
        rows = sb("GET", "app_secrets?key=eq.%s&select=value" % urllib.parse.quote(name))
        val = (rows or [{}])[0].get("value") or None
    except Exception:  # noqa: BLE001 — a flaky read must not take the feature down
        val = hit[0] if hit else None
    _APP_SECRETS_CACHE[name] = (val, time.time())
    return val


def _instantly_accounts():
    """Every sending account in the Instantly workspace — that is where the
    Maildoso fleet actually warms (Smartlead only ever sees those boxes as
    'warmup off / external'). v2 API, Bearer key, /accounts paginated via
    next_starting_after. Raises when the key isn't configured so the bundle
    records a real error instead of silently painting 'all warming'."""
    key = _app_secret("INSTANTLY_API_KEY")
    if not key:
        raise RuntimeError("INSTANTLY_API_KEY not configured on this host")
    items, after, pages = [], None, 0
    while True:
        u = _INSTANTLY_BASE + "/accounts?limit=100"
        if after:
            u += "&starting_after=" + urllib.parse.quote(str(after))
        d = http_json("GET", u, {"Authorization": "Bearer " + key}, timeout=45) or {}
        batch = d.get("items") or []
        items.extend(batch)
        after = d.get("next_starting_after")
        pages += 1
        if not after or not batch or pages > 80:
            break
    return items


def _deliv_client_ws_provider(host):
    h = str(host or "").lower()
    if "gmail" in h or "google" in h:
        return "Google"
    if "outlook" in h or "office" in h or "azure" in h:
        return "Outlook"
    if "maildoso" in h:
        return "Maildoso"
    return "SMTP"


def _deliv_client_ws_warming_doms():
    """Domains of client-workspace mailboxes currently In warm-up, for the
    rest LEDGER union (owner ruling 2026-08-23: client domains get the SAME
    first-seen + 7d due-back clock as Navreo's — the merge runs after the
    ledger path, so without this they rendered with no real countdown).
    Same classification as _deliv_merge_client_ws's inwarmup branch and the
    same 48h staleness guard — raises on a stale/empty mirror so the caller
    can withhold ledger deletes that sweep (a flaky mirror pull must never
    reset client rest clocks)."""
    from datetime import datetime, timedelta, timezone
    ws_ids = [w.get("id") for w in ws_enabled()
              if w.get("id") and w.get("id") != "navreo"]
    if not ws_ids:
        return set()
    boxes = sb_get_all(
        "mailboxes?select=domain,message_per_day,warmup_enabled,smtp_ok,imap_ok,"
        "campaign_count,last_synced_at&workspace=in.(%s)" % ",".join(ws_ids)) or []
    newest = max((str(r.get("last_synced_at") or "") for r in boxes), default="")
    if not boxes or newest < (datetime.now(timezone.utc) - timedelta(hours=48)).isoformat():
        raise RuntimeError("client mirror stale or empty (newest=%s)" % (newest or "none"))
    doms = set()
    for r in boxes:
        if r.get("smtp_ok") is False or r.get("imap_ok") is False:
            continue
        if not r.get("warmup_enabled"):
            continue
        # Resting = warm-up ON and cap 0. NEVER campaign_count: it is stale-zero
        # on every client-ws mirror row (owner audit 2026-08-24), and using it
        # put rest clocks on domains that were actively sending 2.3k/day.
        if not r.get("message_per_day"):
            d = (r.get("domain") or "").lower()
            if d:
                doms.add(d)
    return doms


def _deliv_merge_client_ws(out):
    """Client-workspace federation (inbox-manager-all-workspaces, 2026-07-28):
    the audit backend only sees Navreo's Smartlead, so client workspaces could
    never reach the manager's views/windows however green their ingestion was.
    Append mirror-derived rows (Supabase `mailboxes` + `mailbox_stats_daily`,
    workspace-stamped by the nightly sweep) into the already-built views and
    dh windows. Additive and idempotent: every appended row carries
    `workspace`, prior stamped rows are stripped first (the carry-forward can
    resurrect them), and this runs AFTER the ledger/ghost paths so those only
    ever see backend rows. A stale (>48h) or unreadable mirror raises — the
    caller records the error and Navreo data ships untouched."""
    from datetime import date, datetime, timedelta, timezone
    # Strip first, unconditionally, so a workspace disabled since the last
    # bundle drains instead of riding the carry-forward forever.
    for p in list((out.get("views") or {}).values()) + list((out.get("dh") or {}).values()):
        if isinstance(p, dict) and isinstance(p.get("rows"), list):
            p["rows"] = [r for r in p["rows"] if not (isinstance(r, dict) and r.get("workspace"))]
    ws_ids = [w.get("id") for w in ws_enabled()
              if w.get("id") and w.get("id") != "navreo"]
    if not ws_ids:
        return
    ws_in = ",".join(ws_ids)
    boxes = sb_get_all(
        "mailboxes?select=smartlead_id,email,domain,workspace,tags,message_per_day,"
        "warmup_enabled,warmup_status,blocked_reason,smtp_ok,imap_ok,smtp_host,"
        "campaign_count,last_synced_at&workspace=in.(%s)" % ws_in) or []
    newest = max((str(r.get("last_synced_at") or "") for r in boxes), default="")
    if not boxes or newest < (datetime.now(timezone.utc) - timedelta(hours=48)).isoformat():
        raise RuntimeError("client mirror stale or empty (newest=%s)" % (newest or "none"))
    view_rows = {v: [] for v in _DELIV_BUNDLE_VIEWS}
    for r in boxes:
        ws = r.get("workspace")
        cap = r.get("message_per_day")
        tags = r.get("tags") if isinstance(r.get("tags"), list) else []
        # Mirror tags are Smartlead tag OBJECTS ({name, color, …}) — the view
        # rows the UI renders carry plain strings.
        tags = [t for t in ((t.get("name") if isinstance(t, dict) else str(t)) for t in tags) if t]
        row = {"id": "ws-%s-%s" % (ws, r.get("smartlead_id")),
               "email": (r.get("email") or "").lower(),
               "domain": (r.get("domain") or "").lower(),
               "provider": _deliv_client_ws_provider(r.get("smtp_host")),
               "cap": cap, "maildoso": False, "tags": [ws] + tags[:2],
               "warmup_status": r.get("warmup_status"), "reason": "",
               "reason_category": "", "reconnectable": False, "eligible": False,
               "rested": False, "restedAt": None, "kind": "", "workspace": ws}
        # Same vocabulary the backend views use (mirrored in mock_deliv):
        # connection failure > warm-up off > held (cap 0); a healthy sending
        # box belongs in no manager view. blocked_reason is NOT a view of its
        # own here — the mirror's copy is mostly stale bounce text (361 of 572
        # sat on warmup-ACTIVE boxes, checked 2026-07-28) — it rides along as
        # the row's reason instead.
        if r.get("smtp_ok") is False or r.get("imap_ok") is False:
            row.update(kind="reconnect", reason="SMTP/IMAP connection failed",
                       reason_category="conn fail")
            view_rows["reconnect"].append(row)
        elif not r.get("warmup_enabled"):
            row.update(kind="warmupoff",
                       reason=str(r.get("blocked_reason") or "")[:160])
            view_rows["warmupoff"].append(row)
        elif not cap:
            # In warm-up = warming and NOT configured to send (cap 0). The old
            # rule also swept in campaign_count==0 — meant for pre-launch Grout —
            # but campaign_count is stale-zero on EVERY client-ws mirror row, so
            # it classified all 1,660 KRG boxes (visibly sending 2.3k/day) as
            # resting (owner audit 2026-08-24: "remove all phantoms"). Grout has
            # since launched; a box with a live cap is a sender, full stop.
            row["kind"] = "ok"
            view_rows["inwarmup"].append(row)
    for v, rows in view_rows.items():
        if rows:
            p = out.setdefault("views", {}).setdefault(v, {"rows": []})
            p.setdefault("rows", []).extend(rows)
    # Domain-health windows: the mirror's rolling-30d counters ARE the 30-day
    # window; 7/14 come from the delta between the latest snapshot and the
    # snapshot at the window boundary (earliest in range when history is
    # younger than the window). Per-box deltas clamp at 0 — a rolling counter
    # shrinks when old sends age out of its own 30d tail.
    today = date.today()
    since = (today - timedelta(days=max(_DELIV_BUNDLE_WINDOWS) + 1)).isoformat()
    stats = sb_get_all(
        "mailbox_stats_daily?select=smartlead_id,workspace,stat_date,sent_30d,"
        "replies_30d,bounces_30d,positive_replies_30d&workspace=in.(%s)&stat_date=gte.%s"
        % (ws_in, since)) or []
    # Keyed by (workspace, id): Smartlead account ids are per-account counters
    # and can collide across client workspaces.
    dom_of = {(r.get("workspace"), r.get("smartlead_id")):
              ((r.get("domain") or "").lower(), r.get("workspace")) for r in boxes}
    hist = {}
    for s in stats:
        hist.setdefault((s.get("workspace"), s.get("smartlead_id")), []).append(s)
    for h in hist.values():
        h.sort(key=lambda s: str(s.get("stat_date")))
    for days in _DELIV_BUNDLE_WINDOWS:
        bound = (today - timedelta(days=days)).isoformat()
        agg = {}
        for sid, h in hist.items():
            dom, ws = dom_of.get(sid, ("", None))
            if not dom or not h:
                continue
            latest = h[-1]
            base = None if days >= 30 else next(
                (s for s in h if str(s.get("stat_date")) >= bound), None)
            def delta(col):
                cur = latest.get(col) or 0
                return cur if base is None else max(0, cur - (base.get(col) or 0))
            a = agg.setdefault(dom, {"sent": 0, "replied": 0, "bounced": 0,
                                     "positive": 0, "ws": ws})
            a["sent"] += delta("sent_30d")
            a["replied"] += delta("replies_30d")
            a["bounced"] += delta("bounces_30d")
            a["positive"] += delta("positive_replies_30d")
        rows = []
        for dom, a in sorted(agg.items()):
            sent = a["sent"]
            if not sent and not a["replied"]:
                continue
            pct = lambda n: round(n * 100.0 / sent, 2) if sent else 0
            rows.append({"domain": dom, "sent": sent, "lead": 0,
                         "replied": a["replied"], "bounced": a["bounced"],
                         "positive": a["positive"], "reply_rate": pct(a["replied"]),
                         "bounce_rate": pct(a["bounced"]),
                         "positive_rate": pct(a["positive"]), "batches": [a["ws"]],
                         "maildoso": False, "flag": "", "workspace": a["ws"]})
        if rows:
            w = out.setdefault("dh", {}).setdefault(str(days), {"rows": []})
            w.setdefault("rows", []).extend(rows)


# Client-workspace manager rows are actionable in-tool (owner permission
# 2026-07-28): the audit backend only sees Navreo's Smartlead, so client rows'
# reconnect / re-enable / pause / restore run directly against the owning
# workspace's Smartlead — the same calls the backend makes on the Navreo side.
# Row ids are "ws-<workspace>-<smartlead_id>" (minted by _deliv_merge_client_ws)
# so a client id can never collide with a backend account id.
_WS_ROW_ID_RE = re.compile(r"^ws-([A-Za-z0-9_-]+?)-(\d+)$")


def _client_ws_ids(raw_ids):
    """(workspace, smartlead_id) pairs for every client-row id in raw_ids."""
    out = []
    for s in raw_ids:
        m = _WS_ROW_ID_RE.match(str(s).strip())
        if m:
            out.append((m.group(1), int(m.group(2))))
    return out


def _client_ws_restore_cap(ws, slid, outlook):
    """The cap a client box gets back on restore: its own last non-zero cap
    from the daily stats history (client fleets hand-set caps — asteri runs
    50/day Gmail boxes — so Navreo's house 15/2 would clobber them). House
    caps only as the last resort for a box with no recorded history."""
    try:
        rows = sb("GET", "mailbox_stats_daily?workspace=eq.%s&smartlead_id=eq.%s"
                         "&message_per_day=gt.0&select=message_per_day"
                         "&order=stat_date.desc&limit=1" % (ws, slid)) or []
        if rows and rows[0].get("message_per_day"):
            return int(rows[0]["message_per_day"])
    except Exception:  # noqa: BLE001 — fall through to house caps
        pass
    return 2 if outlook else 15


def _client_ws_action(action, pairs):
    """Run one manager action for client-workspace boxes. Returns
    (ok, skipped, failed, message). Smartlead writes use the owning
    workspace's key; the mirror row is patched immediately so the next
    bundle merge shows the new state without waiting for tonight's sync."""
    ok = skipped = failed = 0
    msgs = []
    if action == "reconnect":
        # Smartlead exposes reconnection only as a per-account bulk retry of
        # every failed box (no per-box endpoint) — fire it once per workspace;
        # the boxes clicked are covered by their workspace's sweep.
        for ws in sorted({w for w, _ in pairs}):
            n = sum(1 for w, _ in pairs if w == ws)
            try:
                _smartlead_json("POST", "/email-accounts/reconnect-failed-email-accounts",
                                {}, workspace=ws, timeout=120)
                ok += n
            except Exception as e:  # noqa: BLE001 — Smartlead rate-limits this to ~1/day
                failed += n
                msgs.append("%s: %s" % (ws, str(e)[:120]))
        return ok, skipped, failed, "; ".join(msgs)
    rows = {}
    slids = sorted({str(sl) for _, sl in pairs})
    for i in range(0, len(slids), 80):
        for r in sb("GET", "mailboxes?smartlead_id=in.(%s)&workspace=neq.navreo"
                           "&select=smartlead_id,workspace,account_type,message_per_day"
                           % ",".join(slids[i:i + 80])) or []:
            rows[(r.get("workspace"), r.get("smartlead_id"))] = r
    pol = MAILBOX_SETTINGS_POLICY.get("providers") or {}
    for ws, sl in pairs:
        r = rows.get((ws, sl)) or {}
        outlook = (r.get("account_type") == "OUTLOOK")
        wp = ((pol.get("microsoft" if outlook else "google") or {}).get("warmup") or {})
        try:
            if action == "reenable":
                _smartlead_json("POST", "/email-accounts/%s/warmup" % sl,
                                {"warmup_enabled": True,
                                 "total_warmup_per_day": ((wp.get("per_day") or {}).get("value") or 10),
                                 "daily_rampup": 2,
                                 "reply_rate_percentage": ((wp.get("reply_rate_pct") or {}).get("value") or 30)},
                                workspace=ws)
                sb("PATCH", "mailboxes?workspace=eq.%s&smartlead_id=eq.%s" % (ws, sl),
                   {"warmup_enabled": True, "warmup_status": "ACTIVE"})
            elif action == "capacity-pause":
                if not (r.get("message_per_day") or 0):
                    skipped += 1
                    continue
                _smartlead_json("POST", "/email-accounts/%s" % sl,
                                {"max_email_per_day": 0}, workspace=ws)
                sb("PATCH", "mailboxes?workspace=eq.%s&smartlead_id=eq.%s" % (ws, sl),
                   {"message_per_day": 0})
            elif action == "capacity-resume":
                if r.get("message_per_day"):
                    skipped += 1
                    continue
                cap = _client_ws_restore_cap(ws, sl, outlook)
                _smartlead_json("POST", "/email-accounts/%s" % sl,
                                {"max_email_per_day": cap}, workspace=ws)
                sb("PATCH", "mailboxes?workspace=eq.%s&smartlead_id=eq.%s" % (ws, sl),
                   {"message_per_day": cap})
            else:
                failed += 1
                msgs.append("unknown action %s" % action)
                continue
            ok += 1
        except Exception as e:  # noqa: BLE001 — keep going, report per box
            failed += 1
            msgs.append("ws-%s-%s: %s" % (ws, sl, str(e)[:100]))
        time.sleep(0.35)  # shared 200req/min Smartlead budget
    return ok, skipped, failed, "; ".join(msgs[:5])


# ── Reconnect outcome watcher (Tasks panel, 2026-08-17) ─────────────────────
# A reconnect click only ever reported "queued N" — Smartlead retries the
# connection asynchronously and nothing said whether the box actually came
# back. Every reconnect POST now also spawns a Tasks-panel job that re-checks
# the clicked boxes against Smartlead over the following minutes and finishes
# green ("back online") or red ("still failing"), so the outcome is visible
# where the operator already looks for background work.

def _reconnect_watch_verify_one(t: dict):
    """One box's connection state, straight from Smartlead.
    True = back online, False = still failing, None = could not verify."""
    if _deliv_mock_on():
        # Dev fleet: everything reconnects except boxes named broken1, so the
        # local flow can demo both the green and the red ending.
        return "broken1" not in str(t.get("email") or t.get("key") or "")
    email = (t.get("email") or "").lower()
    if not email:
        return None
    if not t.get("slid"):
        # email -> (workspace, smartlead_id) via the Supabase mirror; the
        # mapping is stable even though the mirror's health flags are nightly.
        try:
            rows = sb("GET", "mailboxes?email=eq.%s&select=smartlead_id,workspace&limit=5"
                      % urllib.parse.quote(email)) or []
        except Exception:  # noqa: BLE001 — transient mirror error: retry next check
            return None
        pick = next((r for r in rows if r.get("workspace") == t.get("workspace")),
                    rows[0] if rows else None)
        if not pick or not pick.get("smartlead_id"):
            return None
        t["slid"] = pick["smartlead_id"]
        t["workspace"] = pick.get("workspace") or t.get("workspace") or "navreo"
    try:
        a = _smartlead_json("GET", "/email-accounts/%s/" % t["slid"],
                            workspace=t.get("workspace") or "navreo", timeout=30) or {}
    except Exception:  # noqa: BLE001 — Smartlead hiccup: retry next check
        return None
    # Two response shapes exist: is_smtp_success/is_imap_success (account GET,
    # what sync_mailboxes reads) and is_smtp_failure/is_imap_failure
    # (fetch_data's analyse shape). Any explicit failure -> still failing;
    # neither shape present -> unknown, never a false "back online".
    smtp = a.get("is_smtp_success")
    imap = a.get("is_imap_success")
    if smtp is None and imap is None:
        sf, imf = a.get("is_smtp_failure"), a.get("is_imap_failure")
        smtp = None if sf is None else (not sf)
        imap = None if imf is None else (not imf)
    if smtp is None and imap is None:
        return None
    return smtp is not False and imap is not False


def _reconnect_watch_run(job: dict, targets: list):
    _job_started(job)
    n = len(targets)
    # Live: first look after 90s, then every 2.5 min (~11.5 min window —
    # Smartlead's bulk retry usually lands within a few minutes). Mock: fast.
    delays = (4, 5) if _deliv_mock_on() else (90, 150, 150, 150, 150)
    back, unknown = set(), set()

    def tkey(t):
        return t.get("email") or t.get("key")

    # Durable copy of the watch list rides in counts so a redeploy-killed
    # watcher can be revived from its app_jobs row (see
    # _revive_reconnect_watchers). Dropped from the final counts — a finished
    # watch is never revived, and the tray's counts line must stay clean.
    tpersist = [{"email": t.get("email"), "workspace": t.get("workspace"),
                 "key": t.get("key")} for t in targets]

    def paint():
        with JOBS_LOCK:
            job["progress"] = {"done": len(back), "total": n}
            job["counts"] = {"back_online": len(back), "still_failing": n - len(back),
                             "targets": tpersist}
        _job_persist(job)

    paint()
    for d in delays:
        for _ in range(int(d)):  # 1s steps so Cancel lands promptly
            if job.get("cancel_requested"):
                _job_finished(job, "cancelled")
                return
            time.sleep(1)
        unknown = set()
        for t in targets:
            if tkey(t) in back:
                continue
            v = _reconnect_watch_verify_one(t)
            if v is True:
                back.add(tkey(t))
            elif v is None:
                unknown.add(tkey(t))
        paint()
        if len(back) == n:
            break
    still = [tkey(t) for t in targets if tkey(t) not in back]
    failing = [s for s in still if s not in unknown]
    if not still:
        with JOBS_LOCK:
            job["counts"] = {"back_online": n, "still_failing": 0,
                             "detail": "Back online ✓" if n == 1
                             else "All %d back online ✓" % n}
        _job_finished(job, "done")
        return
    if not failing:
        # Only unknowns left: never paint red on missing evidence — say so.
        with JOBS_LOCK:
            job["counts"] = {"back_online": len(back), "still_failing": 0,
                             "detail": (("%d back online · " % len(back)) if back else "")
                             + "%d could not be verified — check the Needs reconnect "
                               "tab after the next refresh" % len(unknown)}
        _job_finished(job, "done")
        return
    ex = ", ".join(failing[:2]) + ("…" if len(failing) > 2 else "")
    msg = (("%d back online · " % len(back)) if back else "") \
        + "%d of %d still failing after the retry window (%s). " % (len(failing), n, ex) \
        + "Smartlead could not reconnect them — fix the login in Smartlead, then Reconnect again."
    with JOBS_LOCK:  # final counts drop the durable targets copy (never revived once finished)
        job["counts"] = {"back_online": len(back), "still_failing": len(failing)}
    _job_finished(job, "failed", msg[:400])


def _reconnect_watch_start(raw_ids):
    """Spawn the watcher for one reconnect POST. Never raises into the
    request path — the reconnect itself must not fail on a watcher bug."""
    try:
        raw = [str(s).strip() for s in raw_ids if str(s).strip()]
        if not raw:
            return
        # Resolve the clicked ids to emails via the bundle rows the click came
        # from (both Navreo backend rows and ws-* client rows live there).
        rows = (((((_DELIV_BUNDLE.get("data") or {}).get("views") or {})
                  .get("reconnect") or {}).get("rows")) or [])
        by_key = {}
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") is not None:
                by_key[str(r["id"])] = r
            if r.get("email"):
                by_key[str(r["email"]).lower()] = r
        targets, seen = [], set()
        for s in raw:
            r = by_key.get(s) or by_key.get(s.lower()) or {}
            email = r.get("email") or (s if "@" in s else "")
            ws = r.get("workspace") or "navreo"
            m = _WS_ROW_ID_RE.match(s)
            if m:
                ws = m.group(1)
            k = (email or s).lower()
            if k in seen:
                continue
            seen.add(k)
            targets.append({"key": s, "email": email, "workspace": ws})
        if not targets:
            return
        n = len(targets)
        # One watcher per box-set: a re-click while a watcher is already
        # covering every clicked box must NOT stack a second identical card
        # (seen live 2026-08-17 — the tray showed two "Reconnect: 10" jobs
        # because the first card took a poll cycle to appear). _watch_keys is
        # memory-only (not in _JOB_DB_FIELDS) — good enough, since a restart
        # marks running watchers interrupted anyway. _JOB_CREATE_LOCK spans
        # check + create so two rapid clicks can't both pass the check.
        keys = sorted({(t["email"] or t["key"]).lower() for t in targets})
        with _JOB_CREATE_LOCK:
            with JOBS_LOCK:
                for j in JOBS.values():
                    if j.get("kind") == "reconnect-watch" \
                            and j.get("status") in ("queued", "running") \
                            and set(keys) <= set(j.get("_watch_keys") or ()):
                        return
            label = ("Reconnect: " + targets[0]["email"]) if n == 1 and targets[0]["email"] \
                else "Reconnect: %d mailbox(es)" % n
            job = _new_job("reconnect-watch", label, None, mock=_deliv_mock_on())
            job["_watch_keys"] = keys
        threading.Thread(target=_reconnect_watch_run, args=(job, targets),
                         daemon=True).start()
    except Exception as e:  # noqa: BLE001 — watcher is best-effort
        print("[reconnect-watch] failed to start:", e)


def _revive_reconnect_watchers():
    """Pick freshly-interrupted reconnect watches back up after a redeploy.

    This service deploys many times a day, so an ~12-minute watcher dying
    mid-run is the COMMON case, not an edge (seen live 2026-08-17: both of the
    operator's "Reconnect: 10" cards ended 'interrupted' with no outcome).
    Same job id → the SAME tray card flips back to Running; checks restart
    from scratch (they are cheap reads — already-recovered boxes re-verify on
    the first pass). Storm guards mirror _maybe_auto_resume: render instance
    only, recent rows only, resume_count-capped, and a compare-and-set PATCH
    so overlapping incarnations can't both revive one row."""
    if not _ON_RENDER or _deliv_mock_on():
        return
    from datetime import datetime, timedelta, timezone
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=25)).isoformat()
    try:
        rows = sb("GET", "app_jobs?kind=eq.reconnect-watch&status=eq.interrupted"
                         "&updated_at=gte.%s" % urllib.parse.quote(cutoff, safe="")) or []
    except Exception:  # noqa: BLE001 — best-effort; never block boot
        return
    for r in rows:
        targets = ((r.get("counts") or {}).get("targets")) or []
        targets = [t for t in targets
                   if isinstance(t, dict) and (t.get("email") or t.get("key"))]
        if not targets or int(r.get("resume_count") or 0) >= 3:
            continue  # nothing durable to watch, or churning across rapid deploys
        try:
            won = sb("PATCH", "app_jobs?id=eq.%s&status=eq.interrupted" % r["id"],
                     {"status": "running", "owner": _SERVER_INSTANCE,
                      "resume_count": int(r.get("resume_count") or 0) + 1,
                      "error": None, "finished_at": None},
                     prefer="return=representation")
        except Exception:  # noqa: BLE001 — one bad row must not stop the rest
            continue
        if not won:
            continue  # another incarnation revived it first
        job = {k: r.get(k) for k in _JOB_DB_FIELDS}
        job.update(status="running", error=None, finished_at=None,
                   owner=_SERVER_INSTANCE, cancel_requested=False, mock=False,
                   resume_count=int(r.get("resume_count") or 0) + 1,
                   progress=r.get("progress") or {"done": 0, "total": len(targets)},
                   counts=r.get("counts") or {})
        job["_watch_keys"] = sorted({str(t.get("email") or t.get("key")).lower()
                                     for t in targets})
        with JOBS_LOCK:
            JOBS[job["id"]] = job
        threading.Thread(target=_reconnect_watch_run, args=(job, targets),
                         daemon=True).start()


# ── High bounce-rate tab: domain-level pause/resume with a durable cap stash ─
# Pause zeroes every mailbox on the domain (Navreo + client workspaces alike);
# the pre-pause caps land in deliverability_audit_cache (id "cap_stash")
# BEFORE the first Smartlead write, so Resume restores each box's EXACT cap —
# never a house default. Stash shape: {"domains": {domain: {"ws:slid": cap}}}.
_CAP_STASH_ID = "cap_stash"


def _cap_stash_read() -> dict:
    return (_blob_snapshot_load(_CAP_STASH_ID) or {}).get("domains") or {}


def _cap_stash_write(domains: dict) -> None:
    _blob_snapshot_save(_CAP_STASH_ID, {"domains": domains})


def _bounce_action(action: str, domain: str):
    """(ok, skipped, failed, message) for bounce-pause / bounce-resume.
    Mailboxes resolve from the Supabase mirror (full fleet, all workspaces);
    Smartlead writes use the owning workspace's key and the mirror row is
    patched immediately so the next bundle merge shows the new state."""
    dom = (domain or "").strip().lower()
    if not dom:
        return 0, 0, 1, "missing domain"
    boxes = sb("GET", "mailboxes?domain=eq.%s"
                      "&select=smartlead_id,workspace,account_type,message_per_day" % dom) or []
    boxes = [r for r in boxes if r.get("smartlead_id")]
    if not boxes:
        return 0, 0, 1, "no mailboxes found for %s" % dom
    ok = skipped = failed = 0
    msgs = []
    stash = _cap_stash_read()
    if action == "bounce-pause":
        entry = dict(stash.get(dom) or {})
        targets = []
        for r in boxes:
            cap = int(r.get("message_per_day") or 0)
            if cap <= 0:
                skipped += 1
                continue
            entry["%s:%s" % (r.get("workspace") or "navreo", r["smartlead_id"])] = cap
            targets.append(r)
        if not targets:
            return 0, skipped, 0, ""
        # Hard rule: the stash is durable BEFORE the first cap write, so a
        # crash mid-pause can never orphan a box on 0 with its cap forgotten.
        stash[dom] = entry
        _cap_stash_write(stash)
        for r in targets:
            ws, sl = r.get("workspace") or "navreo", r["smartlead_id"]
            try:
                _smartlead_json("POST", "/email-accounts/%s" % sl,
                                {"max_email_per_day": 0}, workspace=ws)
                sb("PATCH", "mailboxes?workspace=eq.%s&smartlead_id=eq.%s" % (ws, sl),
                   {"message_per_day": 0})
                ok += 1
            except Exception as e:  # noqa: BLE001 — keep going, report per box
                failed += 1
                msgs.append("%s:%s: %s" % (ws, sl, str(e)[:100]))
            time.sleep(0.35)  # shared 200req/min Smartlead budget
        return ok, skipped, failed, "; ".join(msgs[:5])
    # bounce-resume: stashed cap first; history, then house caps, only for a
    # 0-cap box the stash never saw. Boxes already sending are never touched.
    entry = stash.get(dom) or {}
    for r in boxes:
        ws, sl = r.get("workspace") or "navreo", r["smartlead_id"]
        if int(r.get("message_per_day") or 0) > 0:
            skipped += 1
            continue
        cap = int(entry.get("%s:%s" % (ws, sl)) or 0)
        if cap <= 0:
            cap = _client_ws_restore_cap(ws, sl, r.get("account_type") == "OUTLOOK")
        try:
            _smartlead_json("POST", "/email-accounts/%s" % sl,
                            {"max_email_per_day": cap}, workspace=ws)
            sb("PATCH", "mailboxes?workspace=eq.%s&smartlead_id=eq.%s" % (ws, sl),
               {"message_per_day": cap})
            ok += 1
        except Exception as e:  # noqa: BLE001 — keep going, report per box
            failed += 1
            msgs.append("%s:%s: %s" % (ws, sl, str(e)[:100]))
        time.sleep(0.35)
    if not failed and dom in stash:
        # Only a clean restore clears the stash — a partial one keeps it so a
        # retry can still restore the failed boxes to their exact caps.
        stash.pop(dom, None)
        _cap_stash_write(stash)
    return ok, skipped, failed, "; ".join(msgs[:5])


def _bounce_job_worker(job: dict, action: str, domain: str):
    """Runs a high-bounce pause/resume inside the job queue so the click shows
    up in the Tasks panel (parity with warm-up), survives a refresh, and a
    failure carries a real error instead of a silent inline wait — the domain's
    mailboxes get zeroed/restored one at a time under the Smartlead rate budget,
    which can run many seconds for a wide domain."""
    _job_started(job)
    try:
        ok, skipped, failed, msg = _bounce_action(action, domain)
        counts = {**(job.get("counts") or {}),
                  ("paused" if action == "bounce-pause" else "resumed"): ok,
                  "skipped": skipped, "failed": failed}
        if failed and msg:
            counts["detail"] = msg[:200]
        with JOBS_LOCK:
            job["counts"] = counts
        # A failure on every box (nothing paused/resumed) is a real failure;
        # a partial one still surfaces its per-box detail but counts as done.
        if failed and not ok:
            _job_finished(job, "failed", msg[:300] or "bounce action failed")
        else:
            _job_finished(job, "done")
    except Exception as e:  # noqa: BLE001 — never let a worker die silently
        _job_finished(job, "failed", str(e)[:300])


def api_bounce_job(action: str, domain: str):
    """Queue a high-bounce pause/resume as a Tasks-panel job. Returns
    {job_id}, 202 — the client pings NavreoJobs and the panel tracks it."""
    dom = (domain or "").strip().lower()
    if action not in ("bounce-pause", "bounce-resume"):
        return {"error": "bad_action"}, 400
    if not dom:
        return {"error": "missing_domain", "message": "missing domain"}, 400
    verb = "High-bounce pause" if action == "bounce-pause" else "Resume sending"
    job = _new_job("bounce_" + ("pause" if action == "bounce-pause" else "resume"),
                   f"{verb}: {dom}", None)
    with JOBS_LOCK:
        job["counts"] = {"domains_list": [dom], "action": action}
    _job_persist(job)
    _enqueue_job(_bounce_job_worker, job, (job, action, dom))
    return {"job_id": job["id"]}, 202


def _deliv_apply_instantly_warmupoff(out, iwarming):
    """Instantly is the warm-up TRUTH for the Maildoso fleet (owner request
    2026-08-23): Smartlead only ever sees those boxes as 'warmup off /
    external', so the audit backend dumps the whole fleet into the Not-warming
    (warmupoff) view. Drop every warmupoff row whose mailbox Instantly reports
    as actively warming (warmup_status==1), matched on lowercased email. Both
    the tab count (mgrCount) and the table read this same rows array, so this
    one filter corrects both. Caller runs it ONLY when the Instantly pull
    SUCCEEDED — an outage passes an empty `iwarming`, leaving the
    Smartlead-derived rows untouched (over-report, never a false 'all
    warming'). Must run BEFORE _deliv_merge_client_ws so client-workspace
    warmupoff rows (non-Maildoso, no Instantly presence) are never filtered.
    Returns the number of rows removed."""
    wo = (out.get("views") or {}).get("warmupoff")
    if not (isinstance(wo, dict) and isinstance(wo.get("rows"), list) and iwarming):
        return 0
    before = len(wo["rows"])
    wo["rows"] = [r for r in wo["rows"]
                  if str((r or {}).get("email") or "").lower() not in iwarming]
    removed = before - len(wo["rows"])
    if isinstance(out.get("instantly"), dict):
        out["instantly"]["warmupoffRemoved"] = removed
    return removed


def _deliv_bundle_run_bg_inner():
    """Pull the manager's five actionable views + three domain-health windows
    from the backend, sequentially (its Smartlead budget is shared with the
    sweep — parallel fan-out is what used to starve it). Partial results are
    kept: one failed pull records its error but never voids the others."""
    from datetime import date, timedelta
    blob_dh = ((_DELIV_AUDIT.get("blob") or {}).get("domainHealth") or {})
    min_sent = blob_dh.get("minSent", 500)
    cutoff = blob_dh.get("cutoff", 0.7)
    out = {"views": {}, "dh": {}, "errors": {}, "minSent": min_sent, "cutoff": cutoff,
           "mock": _deliv_mock_on()}
    for v in _DELIV_BUNDLE_VIEWS:
        try:
            out["views"][v] = _deliv_backend_get(f"inboxes?view={v}&batch=")
        except Exception as e:  # noqa: BLE001
            out["errors"][v] = str(e)[:200]
    today = date.today()
    for days in _DELIV_BUNDLE_WINDOWS:
        try:
            dh = _deliv_backend_get(
                "domain-health?start=%s&end=%s&minSent=%s&cutoff=%s"
                % ((today - timedelta(days=days)).isoformat(), today.isoformat(), min_sent, cutoff))
            _deliv_fix_resting_due(dh)  # same pause-moment -> due-back shift as the blob path
            out["dh"][str(days)] = dh
        except Exception as e:  # noqa: BLE001
            out["errors"]["dh" + str(days)] = str(e)[:200]
    # Per-domain mailbox counts, so the floor view can show the blast radius
    # of "Warm up domain" BEFORE the click. The backend's inboxes endpoint
    # truncates at 2,000 rows, so live counts come from the Supabase mailboxes
    # mirror (full fleet, daily-synced); mock mode counts its own fake fleet.
    mdoms = set()  # Maildoso-fleet domains — parked by design, never "due back"
    try:
        boxes = {}
        zero = {}
        census_fresh = False
        if _deliv_mock_on():
            for r in (_deliv_backend_get("inboxes?view=all&batch=").get("rows") or []):
                d = (r.get("domain") or "").lower()
                if d:
                    boxes[d] = boxes.get(d, 0) + 1
                    if not (r.get("cap") or 0):
                        zero[d] = zero.get(d, 0) + 1
            census_fresh = True
        else:
            newest = ""
            for r in sb_get_all("mailboxes?select=domain,message_per_day,last_synced_at,smtp_host") or []:
                d = (r.get("domain") or "").lower()
                if d:
                    boxes[d] = boxes.get(d, 0) + 1
                    if not (r.get("message_per_day") or 0):
                        zero[d] = zero.get(d, 0) + 1
                    if "maildoso" in str(r.get("smtp_host") or "").lower():
                        mdoms.add(d)
                ts = str(r.get("last_synced_at") or "")
                if ts > newest:
                    newest = ts
            # The census is only trustworthy while the nightly Smartlead sync
            # is alive — a mirror that stopped updating days ago must never
            # drive ledger deletes or hide rows.
            from datetime import datetime, timedelta, timezone
            census_fresh = bool(boxes) and newest >= (
                datetime.now(timezone.utc) - timedelta(hours=48)).isoformat()
        out["domainBoxes"] = boxes
        # High-bounce tab: domains paused via the durable cap stash, as
        # {domain: n_boxes_stashed} — the tab's Pause/Resume buttons read
        # this off the cached bundle (no per-tab fetch).
        try:
            out["capStash"] = (mock_deliv.bounce_stash_domains() if _deliv_mock_on()
                               else {d: len(m or {}) for d, m in _cap_stash_read().items()})
        except Exception as e:  # noqa: BLE001
            out["errors"]["capStash"] = str(e)[:200]
        # sends-paused truth: per-domain count of cap-0 boxes across the FULL
        # fleet (the audit backend's views truncate at 2,000 rows, so counting
        # its rows undercounts big domains and ghosts linger). Domains absent
        # from this map are UNKNOWN, not ghost-free — client keeps them.
        if census_fresh:
            out["liveZeroCap"] = zero
            if not _deliv_mock_on():
                # Freshness cue for any surface that wants to disclose the
                # census age (mirror last_synced_at, nightly).
                out["liveZeroCapAsOf"] = newest
    except Exception as e:  # noqa: BLE001
        out["errors"]["domainBoxes"] = str(e)[:200]
    # Due-back dates for every rested domain on display — ledger-derived in
    # live mode; in mock mode straight from the fake fleet's restedAt (those
    # ARE true pause moments, unlike the real backend's).
    try:
        rested_rows = ((out["views"].get("rested") or {}).get("rows")) or []
        if _deliv_mock_on():
            first = {}
            for r in rested_rows:
                d, ra = (r.get("domain") or "").lower(), r.get("restedAt")
                if d and ra:
                    first[d] = min(first.get(d, ra), ra)
            out["restDue"] = {d: v + _DELIV_REST_DAYS_MS for d, v in first.items()}
        else:
            rested_doms = {(r.get("domain") or "").lower() for r in rested_rows if r.get("domain")}
            blob_resting = ((_DELIV_AUDIT.get("blob") or {}).get("domainHealth") or {}).get("resting") or {}
            rested_doms |= {str(d).lower() for d in blob_resting}
            # Warm-up ENTRY stamps too (owner ruling 2026-07-15): freshly-warming
            # domains (inwarmup view — building reputation, never "rested") get a
            # ledger row the first sweep we see them, so EVERY domain in the
            # In-warm-up union carries due = first seen + 7d, one clock for the
            # whole tab. ignore-duplicates keeps established rest clocks intact.
            warming_rows = ((out["views"].get("inwarmup") or {}).get("rows")) or []
            union_doms = rested_doms | {(r.get("domain") or "").lower()
                                        for r in warming_rows if r.get("domain")}
            # Client-workspace warming domains join the SAME ledger so their
            # due-back clocks are real first-seen countdowns, not a client-side
            # placeholder (the client merge runs after this block, so their
            # rows can't be read from out["views"] here). A failed/stale
            # mirror pull withholds deletes below instead of raising — client
            # clocks must survive one flaky sweep, exactly like the trunc guard.
            client_ws_ok = True
            try:
                union_doms |= _deliv_client_ws_warming_doms()
            except Exception as ce:  # noqa: BLE001
                client_ws_ok = False
                out["errors"]["clientWsLedger"] = str(ce)[:200]
            # A FAILED pull of EITHER view must never look like "those domains
            # left warm-up" — that path mass-deleted the ledger and reset every
            # domain's rest clock on one flaky backend refresh. Same guard for
            # truncation: a missing row must not reset a domain's clock.
            trunc = any(bool((out["views"].get(v) or {}).get("truncated"))
                        for v in ("rested", "inwarmup"))
            # Ghost drain: a domain whose FULL-fleet census says zero cap-0
            # boxes is not resting, whatever the (truncated) backend views or
            # a stale ledger row claim. Ghosts leave the union AND get their
            # own targeted ledger delete on census evidence alone — the
            # absence-based delete below keeps its both-views-healthy gate so
            # a flaky pull still can't mass-reset rest clocks. Domains the
            # census doesn't know (client-workspace fleets) are untouched.
            lz = out.get("liveZeroCap")
            known = out.get("domainBoxes") or {}
            ghosts = set()
            if isinstance(lz, dict):
                ghosts = {d for d in union_doms
                          if known.get(d, 0) > 0 and lz.get(d, 0) == 0}
                union_doms -= ghosts
                # Census-held domains the truncated views dropped entirely
                # still deserve a rest clock — without this they render (the
                # client synthesizes their rows) but with no due-back date,
                # and "ledger 95 vs tab 94" style splits reappear. Maildoso
                # included: its rest is a plain timer like everyone else's
                # (owner ruling 2026-07-25 — due-back = parked-at + 7d, not a
                # warm-up-reputation readout).
                union_doms |= {d for d, n in lz.items()
                               if n > 0 and d not in union_doms}
            out["restDue"] = _deliv_resting_ledger_sync(
                union_doms,
                allow_delete=("rested" in out["views"]) and ("inwarmup" in out["views"])
                             and not trunc and client_ws_ok)
            out["maildosoDomains"] = sorted(mdoms)
            gdoms = _safe_domains(sorted(ghosts))
            if gdoms and not _deliv_mock_on():
                # Due-gated (2026-08-28): a ghost mid-rest is a park that never
                # landed or an audit-side restore — deleting its row here is
                # what reset rest clocks daily. Only served rests are dropped;
                # defended ghosts keep their due-back and get re-parked by
                # rest_enforce().
                gres = _ledger_delete_due_only(gdoms, reason="ghost census (all boxes live)")
                if gres["deleted"]:
                    _restore_plan_invalidate()
                for gd, gdue in gres["defended"].items():
                    out["restDue"].setdefault(gd, gdue)
    except Exception as e:  # noqa: BLE001
        out["errors"]["restDue"] = str(e)[:200]
    # Instantly truth for the Maildoso fleet (owner request 2026-07-25): those
    # boxes warm on Instantly, so the manager reads their REAL warm-up state
    # from Instantly on every bundle refresh — per-domain aggregates for the
    # In-warm-up rows, plus a per-box list of anything NOT warming so the
    # Not-warming tab can surface real gaps instead of hiding the fleet.
    if not _deliv_mock_on():
        try:
            idoms, inw, iwarming = {}, [], set()
            for a in _instantly_accounts():
                email = str(a.get("email") or "").lower()
                dom = email.rpartition("@")[2]
                if not dom:
                    continue
                g = idoms.setdefault(dom, {"boxes": 0, "warming": 0, "off": 0, "score_sum": 0.0})
                sc = a.get("stat_warmup_score") or 0
                g["boxes"] += 1
                g["score_sum"] += sc
                if a.get("warmup_status") == 1:
                    g["warming"] += 1
                    iwarming.add(email)
                else:
                    g["off"] += 1
                    inw.append({"email": email, "domain": dom, "score": sc,
                                "status": a.get("status"),
                                "warmup_status": a.get("warmup_status")})
            out["instantly"] = {
                "asOf": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                "domains": {d: {"boxes": g["boxes"], "warming": g["warming"], "off": g["off"],
                                "avgScore": round(g["score_sum"] / g["boxes"], 1) if g["boxes"] else 0}
                            for d, g in idoms.items()},
                "notWarming": inw,
            }
            _deliv_apply_instantly_warmupoff(out, iwarming)
        except Exception as e:  # noqa: BLE001 — key missing / API down: keep last good data
            out["errors"]["instantly"] = str(e)[:200]
    # A partial refresh must not clobber keys the last complete bundle had:
    # carry forward every view/window that ERRORED this sweep (keyed on error
    # presence, never on emptiness, so a legitimately-emptied view is not
    # resurrected). Mock/live bundles never merge into each other.
    if out["errors"]:
        with _DELIV_BUNDLE_LOCK:
            prev = _DELIV_BUNDLE["data"] if isinstance(_DELIV_BUNDLE["data"], dict) else None
        if prev and bool(prev.get("mock")) == bool(out.get("mock")):
            for v in _DELIV_BUNDLE_VIEWS:
                if v in out["errors"] and v in (prev.get("views") or {}):
                    out["views"][v] = prev["views"][v]
            for dkey in (str(d) for d in _DELIV_BUNDLE_WINDOWS):
                if ("dh" + dkey) in out["errors"] and dkey in (prev.get("dh") or {}):
                    out["dh"][dkey] = prev["dh"][dkey]
            # liveZeroCap shares the domainBoxes try-block, so its failure is
            # recorded under that error key; carry it on that signal only —
            # a merely-stale census (key absent, no error) must NOT be revived.
            for k, ek in (("domainBoxes", "domainBoxes"), ("restDue", "restDue"),
                          ("liveZeroCap", "domainBoxes"), ("liveZeroCapAsOf", "domainBoxes"),
                          ("maildosoDomains", "domainBoxes"), ("instantly", "instantly")):
                if ek in out["errors"] and k in prev and k not in out:
                    out[k] = prev[k]
    # Client-workspace rows LAST: after the ledger/ghost paths (which must
    # only see backend rows) and after the carry-forward (which may have
    # resurrected a previous merge — the helper strips those before adding).
    if not _deliv_mock_on():
        try:
            _deliv_merge_client_ws(out)
        except Exception as e:  # noqa: BLE001 — client merge failing must never void Navreo's bundle
            out["errors"]["clientWs"] = str(e)[:200]
    ok = bool(out["views"]) or bool(out["dh"])
    err = json.dumps(out["errors"])[:300] if out["errors"] else None
    with _DELIV_BUNDLE_LOCK:
        if ok:
            _DELIV_BUNDLE.update(data=out, ts=time.time(), running=False, error=err)
        else:
            _DELIV_BUNDLE.update(running=False, error=err or "empty bundle")
    # NEVER persist a mock-mode bundle: the Supabase cache row is shared with
    # production, and a local DELIV_MOCK=1 run writing here served fake
    # domains to the live manager (caught on the 2026-07-11 live verify).
    if ok and not _deliv_mock_on():
        _deliv_bundle_persist(out)


def _deliv_bundle_start(force=False):
    """Kick a background bundle refresh unless one's already running (or the
    cache is fresh and not forced). Mirrors _deliv_audit_start."""
    _deliv_bundle_restore()
    if not force and not _deliv_mock_on() and \
            ":" not in (os.environ.get("DELIV_AUDIT_AUTH") or KEYS.get("DELIV_AUDIT_AUTH") or ""):
        return {"started": False, "running": False, "configured": False}
    with _DELIV_BUNDLE_LOCK:
        if _DELIV_BUNDLE["running"]:
            return {"started": False, "running": True}
        fresh = _DELIV_BUNDLE["data"] is not None and (time.time() - _DELIV_BUNDLE["ts"]) < _DELIV_AUDIT_TTL_S
        if fresh and not force:
            return {"started": False, "running": False, "fresh": True}
        # outage cooldown: after a FAILED attempt, unforced kicks (every 10s
        # poll tick hits this) wait 60s before spawning another doomed thread
        if not force and _DELIV_BUNDLE["error"] and \
                (time.time() - _DELIV_BUNDLE.get("last_attempt", 0.0)) < 60:
            return {"started": False, "running": False, "error": _DELIV_BUNDLE["error"]}
        _DELIV_BUNDLE.update(running=True, error=None, last_attempt=time.time())
    threading.Thread(target=_deliv_bundle_run_bg, daemon=True).start()
    return {"started": True, "running": True}


# ── Deliverability trends (30-day health series for the glance header) ──────
# Per-day sent / reply% / bounce% comes straight from Smartlead's day-wise
# analytics (backfills instantly); fleet counts Smartlead can't backfill
# (smtp/imap fails, real blocks, auth misses, blacklists) accrue one row per
# day in deliverability_daily_snapshots, written on every successful audit
# refresh — same writer, no extra cron.
import datetime as _dtmod

_DELIV_TRENDS = {}  # days -> {"data":…, "ts":…} so 7/14/30 toggles stop evicting each other
_DELIV_TRENDS_LOCK = threading.Lock()
_DELIV_TRENDS_BUILDING = set()  # days values with a build in flight (dedupe concurrent firsts)
_DELIV_TRENDS_TTL_S = 7200  # same 2h clock as the audit/bundle caches


def _snapshot_from_blob(blob: dict):
    """Upsert today's fleet-count snapshot from a fresh audit blob. Best-effort:
    a Supabase outage must never fail the audit refresh that carries it."""
    try:
        row = {
            "snapshot_date": _dtmod.date.today().isoformat(),
            "smtp_fails": int(blob.get("smtp") or 0),
            "imap_fails": int(blob.get("imap") or 0),
            "blocked_real": int(blob.get("blockedReal") or 0),
            "spf_miss": int(blob.get("spfMiss") or 0),
            "dkim_miss": int(blob.get("dkimMiss") or 0),
            "dmarc_miss": int(blob.get("dmarcMiss") or 0),
            "blacklisted": len(blob.get("blacklist") or []),
            "inboxes": blob.get("inboxes"), "domains": blob.get("domains"),
            "updated_at": _dtmod.datetime.utcnow().isoformat() + "Z",
        }
        sb("POST", "deliverability_daily_snapshots?on_conflict=snapshot_date", row,
           prefer="resolution=merge-duplicates,return=minimal")
    except Exception as e:  # noqa: BLE001
        print(f"[trends] snapshot write failed: {e}", file=sys.stderr)


def _deliv_trends_build(days: int) -> dict:
    """Fetch + shape the per-day series. Raises on Smartlead failure — the
    caller keeps serving the previous cached copy in that case."""
    # Ends YESTERDAY, like _client_win_build (owner ruling 2026-09-02) — today is
    # a partial bucket, and the two series share the Analytics chart's axis.
    end = _dtmod.date.today() - _dtmod.timedelta(days=1)
    start = end - _dtmod.timedelta(days=days - 1)
    # navreo-fleet-only BY DESIGN: OUR fleet's day-wise history
    url = (f"{SMARTLEAD_BASE}/analytics/day-wise-overall-stats"
           f"?api_key={KEYS.get('SMARTLEAD_API_KEY', '')}"
           f"&start_date={start.isoformat()}&end_date={end.isoformat()}")
    data = http_json("GET", url, {}, timeout=30)
    raw = ((data or {}).get("data") or {}).get("day_wise_stats") or []
    # Smartlead dates come back as "10 Jun" (no year) — key on (day, month);
    # a ≤90-day window can't contain the same day+month twice.
    months = {m: i + 1 for i, m in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"])}
    by_daymonth = {}
    for r in raw:
        try:
            d, mon = str(r.get("date", "")).split()
            m = r.get("email_engagement_metrics") or {}
            by_daymonth[(int(d), months.get(mon[:3], 0))] = m
        except (ValueError, AttributeError):
            continue
    if not by_daymonth:
        # empty day-wise read = Smartlead outage/4xx body; raise before paying
        # the snapshots round-trip (the all-zero guard below stays as backstop)
        raise RuntimeError("smartlead day-wise returned no rows")
    # Snapshot rows for the same window (issues series — may be sparse at first).
    snaps = sb("GET", ("deliverability_daily_snapshots"
                       f"?snapshot_date=gte.{start.isoformat()}&order=snapshot_date.asc")) or []
    snap_by_date = {s.get("snapshot_date"): s for s in snaps if isinstance(s, dict)}
    days_out, sent, reply_pct, bounce_pct, issues = [], [], [], [], []
    cur = start
    while cur <= end:
        m = by_daymonth.get((cur.day, cur.month)) or {}
        s = int(m.get("sent") or 0)
        days_out.append(cur.isoformat())
        sent.append(s)
        reply_pct.append(round(int(m.get("replied") or 0) * 100.0 / s, 2) if s else None)
        bounce_pct.append(round(int(m.get("bounced") or 0) * 100.0 / s, 2) if s else None)
        sn = snap_by_date.get(cur.isoformat())
        issues.append(None if sn is None else
                      int(sn.get("smtp_fails") or 0) + int(sn.get("imap_fails") or 0)
                      + int(sn.get("blocked_real") or 0) + int(sn.get("spf_miss") or 0)
                      + int(sn.get("dkim_miss") or 0) + int(sn.get("dmarc_miss") or 0)
                      + int(sn.get("blacklisted") or 0))
        cur += _dtmod.timedelta(days=1)
    if not by_daymonth or not any(sent):
        # http_json returns a parsed 4xx body (e.g. a 429 note) rather than
        # raising, which left raw=[] and built a structurally valid all-zero
        # month that then cached AND persisted as fresh (panel round-1 HIGH).
        # This fleet sends every weekday — an empty/zero window is an outage.
        raise RuntimeError("smartlead day-wise returned no usable rows")
    return {"series": {"days": days_out, "sent": sent, "reply_pct": reply_pct,
                       "bounce_pct": bounce_pct, "issues": issues},
            "asof": _dtmod.datetime.utcnow().isoformat() + "Z"}


def _deliv_trends_refresh_bg(days: int) -> None:
    try:
        data = _deliv_trends_build(days)
    except Exception as e:  # noqa: BLE001 — keep serving the stale copy
        print(f"[trends] background rebuild failed: {e}", file=sys.stderr)
        with _DELIV_TRENDS_LOCK:
            _DELIV_TRENDS_BUILDING.discard(days)
        return
    with _DELIV_TRENDS_LOCK:
        _DELIV_TRENDS_BUILDING.discard(days)
        _DELIV_TRENDS[days] = {"data": data, "ts": time.time()}
    if days == 30:
        _blob_snapshot_save("deliv_trends_30", data)


def deliv_trends_get(days: int = 30) -> tuple[dict, int]:
    days = max(7, min(90, days))
    with _DELIV_TRENDS_LOCK:
        ent = _DELIV_TRENDS.get(days)
    if ent is None and days == 30:
        # deploy-warm restore: serve the persisted snapshot stale (ts 0) and
        # let the background rebuild bring it current
        snap = _blob_snapshot_load("deliv_trends_30")
        if snap:
            with _DELIV_TRENDS_LOCK:
                ent = _DELIV_TRENDS.setdefault(30, {"data": snap, "ts": 0.0})
    if ent:
        if (time.time() - ent["ts"]) < _DELIV_TRENDS_TTL_S:
            return ent["data"], 200
        # stale: serve immediately, kick exactly one background rebuild — the
        # 3-4s Smartlead day-wise call never sits on the request thread once
        # any copy exists (same SWR semantics as every other cache here)
        kick = False
        with _DELIV_TRENDS_LOCK:
            if days not in _DELIV_TRENDS_BUILDING:
                _DELIV_TRENDS_BUILDING.add(days)
                kick = True
        if kick:
            threading.Thread(target=_deliv_trends_refresh_bg, args=(days,), daemon=True).start()
        return ent["data"], 200
    with _DELIV_TRENDS_LOCK:
        _DELIV_TRENDS_BUILDING.add(days)
    try:
        data = _deliv_trends_build(days)
    except Exception as e:  # noqa: BLE001 — nothing cached yet, surface the error
        with _DELIV_TRENDS_LOCK:
            _DELIV_TRENDS_BUILDING.discard(days)
        return {"error": "trends_unavailable", "message": str(e)[:200]}, 502
    with _DELIV_TRENDS_LOCK:
        _DELIV_TRENDS_BUILDING.discard(days)
        _DELIV_TRENDS[days] = {"data": data, "ts": time.time()}
    if days == 30:
        _blob_snapshot_save("deliv_trends_30", data)
    return data, 200


# ── Fleet sending CAPACITY (per-day, per-workspace) ─────────────────────────
# Capacity for a day = summed per-box daily cap (message_per_day, snapshotted in
# mailbox_stats_daily that day) over mailboxes ATTACHED TO A CAMPAIGN
# (campaign_count>0) — boxes on no campaign can't send, so they don't count
# (Bjion 2026-08-19). The join+sum runs in the DB (fleet_capacity_daily RPC;
# PostgREST has aggregates disabled). Boxes aren't client-tagged inside the
# shared navreo workspace, so capacity is exact per WORKSPACE and for the
# all-clients sum; the chart maps client -> workspace (navreo-workspace clients
# share one pool, so they omit the ceiling). Fast RPC (~one call), so a plain
# TTL cache — no background-rebuild machinery.
_FLEET_CAP = {}  # days -> {"data":…, "ts":…}
_FLEET_CAP_LOCK = threading.Lock()
_FLEET_CAP_TTL_S = 3600
_FLEET_CAP_WS = ("navreo", "asteri", "krg", "grout")


def _fleet_capacity_build(days: int) -> dict:
    end = _dtmod.date.today()
    startd = end - _dtmod.timedelta(days=days - 1)
    # pull a week of extra history so carry-forward can seed the first axis day
    # The RPC can return None or a PostgREST error OBJECT (not rows) on the app's
    # first cold DB connection at boot — a truthy non-list that must NOT be shaped
    # into an all-null window and cached for the TTL (that once blanked the
    # ceiling). Retry a few times (the pool warms within a second or two) and
    # require a non-empty LIST; raise otherwise so the caller serves stale / 502s
    # and the next request retries.
    body = {"p_start": (startd - _dtmod.timedelta(days=7)).isoformat()}
    rows, resp = None, None
    for _attempt in range(3):
        resp = sb("POST", "rpc/fleet_capacity_daily", body)
        if isinstance(resp, list) and resp:
            rows = resp
            break
        time.sleep(0.8)
    if rows is None:
        raise RuntimeError(f"fleet_capacity_daily: no rows after retries ({type(resp).__name__})")
    per_ws: dict = {}
    for r in rows:
        if not isinstance(r, dict):
            continue
        ws, d = r.get("workspace"), r.get("stat_date")
        if ws and d:
            per_ws.setdefault(ws, {})[str(d)[:10]] = int(r.get("cap") or 0)
    axis, cur = [], startd
    while cur <= end:
        axis.append(cur.isoformat())
        cur += _dtmod.timedelta(days=1)
    cap: dict = {}
    total = [0] * len(axis)
    seen = [False] * len(axis)
    for ws in _FLEET_CAP_WS:
        m = per_ws.get(ws, {})
        prior = [d for d in m if d < axis[0]]
        last = m[max(prior)] if prior else None   # carry-forward seed from before the window
        arr = []
        for i, d in enumerate(axis):
            if d in m:
                last = m[d]
            arr.append(last)
            if last:
                total[i] += last
                seen[i] = True
        cap[ws] = arr
    cap["__all"] = [total[i] if seen[i] else None for i in range(len(axis))]
    return {"days": axis, "capacity": cap,
            "asof": _dtmod.datetime.utcnow().isoformat() + "Z"}


_CLIENT_CAP = {"data": {}, "ts": 0.0}
_CLIENT_CAP_TTL_S = 600


_CLIENT_CAP_HIST_KEY = "client_capacity_hist_v1"   # rolling per-day blob (deliverability_audit_cache)


def _mirror_pool_caps() -> dict:
    """{workspace: {cap, boxes}} = Σ GLOBAL message_per_day over boxes attached to a
    campaign (campaign_count>0), from the mailboxes mirror. A PAUSE writes cap 0
    HERE (the global cap), so this reflects pauses — the sweep's per-campaign cap
    is a stale copy a pause never updates (Bjion 2026-08-21). Fast: one DB read."""
    rows = sb_get_all("mailboxes?select=workspace,message_per_day,campaign_count") or []
    out: dict = {}
    for r in rows:
        if (r.get("campaign_count") or 0) > 0:
            ws = r.get("workspace") or "navreo"
            e = out.setdefault(ws, {"cap": 0, "boxes": 0})
            e["cap"] += r.get("message_per_day") or 0
            e["boxes"] += 1
    return out


def _navreo_box_caps() -> dict:
    """{lower(email): global message_per_day} for ATTACHED navreo boxes (a paused
    box is 0 here), so a paused mailbox contributes 0 to its client's total."""
    rows = sb_get_all("mailboxes?select=email,message_per_day,campaign_count&workspace=eq.navreo") or []
    return {(r.get("email") or "").lower(): (r.get("message_per_day") or 0)
            for r in rows if r.get("email") and (r.get("campaign_count") or 0) > 0}


def _navreo_cap_from_sweep(sweep: dict, score: list, box_caps: dict, pool: dict) -> dict:
    """Per-client navreo capacity: the sweep says which client(s) each box serves.
    The CAP is the mirror's global, pause-aware cap (box_caps) when present — but a
    box the sweep found on an ACTIVE campaign yet MISSING from the mirror (a sync
    gap) is no longer dropped: it falls back to the sweep's own Smartlead cap
    (rec['cap'] = that mailbox's message_per_day). Dropping such boxes silently
    UNDER-counted a client's capacity — the Amplifyy case where recorded per-client
    capacity sat below the client's actual daily sends (Bjion 2026-08-22). This is
    pause-safe: a paused/parked mailbox reports message_per_day 0 in BOTH the mirror
    and the sweep, so it contributes 0 either way and the `cap <= 0` skip drops it.
    Only a mirror-absent box with a POSITIVE Smartlead cap (confirmed active) is
    added. Pool comes straight from the mirror."""
    cl_of = {}
    for r in score:
        if (r.get("workspace") or "navreo") == "navreo":
            cl = (r.get("client") or "").strip()
            if cl and not cl.startswith("__"):
                cl_of[str(r.get("smartlead_campaign_id"))] = cl
    clients: dict = {}
    for email, rec in (sweep.get("accounts") or {}).items():
        cap = box_caps.get(email)
        if cap is None:                      # box absent from the mirror (sync gap)
            cap = int(rec.get("cap") or 0)   # fall back to the sweep's Smartlead cap
        else:
            cap = int(cap or 0)
        if cap <= 0:                         # paused/parked (mpd 0) or unknown → skip
            continue
        seen = set()
        for cid in [str(c) for c in (rec.get("camps") or [])]:
            cl = cl_of.get(cid)
            if cl and cl not in seen:
                seen.add(cl)
                e = clients.setdefault(cl, {"cap": 0, "boxes": 0})
                e["cap"] += cap
                e["boxes"] += 1
    return {"workspace": pool, "clients": clients}


def _navreo_capacity_breakdown(force_fresh: bool = False) -> dict:
    """Every workspace's pool capacity (mirror, pause-aware) + navreo per-client
    (sweep membership × mirror caps). The pools need no sweep; only per-client does.
    force_fresh runs the sweep synchronously (daily cron); otherwise it uses the
    cached sweep — pools are still returned even before the sweep warms."""
    pool = _mirror_pool_caps()
    with _RESTORE_SWEEP_LOCK:
        sweep = _RESTORE_SWEEP["data"]
        fresh = sweep is not None and (time.time() - _RESTORE_SWEEP["ts"]) < _RESTORE_SWEEP_TTL_S
    if force_fresh and not fresh:
        _restore_sweep_run_bg()
        with _RESTORE_SWEEP_LOCK:
            sweep = _RESTORE_SWEEP["data"]
    if sweep is None:
        if not force_fresh:
            _restore_sweep_start()
        return {"workspace": pool, "clients": {}} if pool else {}
    try:
        score = sb_get_all("campaign_scorecard?select=smartlead_campaign_id,client,workspace") or []
        box_caps = _navreo_box_caps()
    except Exception:  # noqa: BLE001 — capacity map is an enhancement, never a 500
        return {"workspace": pool, "clients": {}} if pool else {}
    return _navreo_cap_from_sweep(sweep, score, box_caps, pool)


def _navreo_caps_live() -> dict:
    """Read path: cached (10-min) live breakdown {workspace, clients}. {} until warm."""
    if _CLIENT_CAP["data"] and (time.time() - _CLIENT_CAP["ts"]) < _CLIENT_CAP_TTL_S:
        return _CLIENT_CAP["data"]
    bd = _navreo_capacity_breakdown(force_fresh=False)
    if bd and (bd.get("clients") or bd.get("workspace", {}).get("navreo", {}).get("cap")):
        _CLIENT_CAP.update(data=bd, ts=time.time())
        return bd
    cur = _CLIENT_CAP["data"]
    return cur if isinstance(cur, dict) and cur.get("clients") else {}


def _client_capacity_now() -> dict:
    """Back-compat: {client: cap} for the shared navreo workspace, today, live."""
    return {c: v["cap"] for c, v in (_navreo_caps_live().get("clients") or {}).items()}


def _client_cap_history_compute() -> dict:
    return (_blob_snapshot_load(_CLIENT_CAP_HIST_KEY) or {}).get("days") or {}


# The cap-history blob is written once a day by the cap crons, yet it was read
# from Supabase on EVERY /api/fleet-capacity call (the main ~1s cost behind that
# endpoint once its 1h base series is warm, audit 2026-08-22). SWR-cache it 300s.
_CLIENT_CAP_HIST_SWR = _SWRCache(_client_cap_history_compute, 300,
                                 is_degraded=lambda p: not isinstance(p, dict),
                                 name="client-cap-history")


def _client_cap_history() -> dict:
    """The rolling per-day capacity blob written by the daily cap crons:
    {date: {"workspace": {navreo:{cap,boxes}}, "clients": {client:{cap,boxes}}}}."""
    return _CLIENT_CAP_HIST_SWR.get() or {}


def _cap_hw_merge(prev: dict | None, new: dict, src: str, asof: str) -> dict:
    """High-water merge of ONE entity's (workspace or client) daily capacity.
    Appends an immutable provenance snap and keeps:
      cap_max  the high-water — the highest authorized cap in force that day.
               Used for DISPLAY (chart ceiling) and as the VIOLATION threshold.
      cap_min  the lowest POSITIVE authorized cap in force that day — the ONLY
               value that may CLEAR a day as within-cap (a total at or below it
               is safe under any intraday ordering).
      cap      kept = cap_max for back-compat readers.
    SENT is never an input here, so this value only ever rises via a genuine
    authorized snapshot — the high-water can never silently absorb an over-send
    (Bjion 2026-08-22, capacity>=sent invariant). A later same-day snapshot the
    tiering engine LOWERED can no longer erase an earlier, higher ceiling that
    sends already went out under."""
    ncap = int(new.get("cap") or 0)
    snap = {"cap": ncap, "asof": asof, "src": src}
    if not prev:
        return {"cap": ncap, "boxes": new.get("boxes"),
                "cap_min": ncap, "cap_max": ncap, "snaps": [snap]}
    pmax = int(prev.get("cap_max", prev.get("cap") or 0))
    _pm = prev.get("cap_min")
    pmin = int(_pm) if _pm is not None else pmax
    cap_max = max(pmax, ncap)
    # a 0 (whole fleet paused / cold read) is not a real "authorized cap in
    # force" floor, so it never drops cap_min; only positive snaps fold in.
    if ncap > 0:
        cap_min = min(pmin, ncap) if pmin > 0 else ncap
    else:
        cap_min = pmin
    snaps = (prev.get("snaps") or [])[-23:] + [snap]      # keep last 24 snaps/day
    return {"cap": cap_max, "boxes": new.get("boxes"),
            "cap_min": cap_min, "cap_max": cap_max, "snaps": snaps}


def _cap_blob_upsert(today: str, workspace_updates: dict, client_updates: dict | None,
                     src: str = "sync") -> None:
    """Merge today's capacity into the rolling blob WITHOUT clobbering other
    workspaces already written this day (the federated mailbox sync writes every
    workspace at 04:30; the navreo cap crons then refresh just navreo at 05:15 /
    06:00). Every entity is HIGH-WATER merged (see _cap_hw_merge) — a later,
    lower same-day snapshot can no longer overwrite an earlier higher ceiling,
    and each entity carries immutable provenance snaps so the authorized cap in
    force is auditable."""
    hist = _blob_snapshot_load(_CLIENT_CAP_HIST_KEY) or {}
    days = hist.get("days") or {}
    rec = days.get(today) or {"workspace": {}, "clients": {}}
    asof = _dtmod.datetime.utcnow().isoformat() + "Z"
    ws_rec = rec.setdefault("workspace", {})
    for ws, val in (workspace_updates or {}).items():
        ws_rec[ws] = _cap_hw_merge(ws_rec.get(ws), val or {}, src, asof)
    if client_updates is not None:
        cl_rec = rec.setdefault("clients", {})
        for cl, val in client_updates.items():
            cl_rec[cl] = _cap_hw_merge(cl_rec.get(cl), val or {}, src, asof)
    rec["asof"] = asof
    days[today] = rec
    if len(days) > 130:                       # keep ~120 days of history
        for d in sorted(days)[:-120]:
            days.pop(d, None)
    hist["days"] = days
    hist["updated"] = today
    _blob_snapshot_save(_CLIENT_CAP_HIST_KEY, hist)


def snapshot_navreo_capacity() -> dict:
    """Persist TODAY's navreo pool + per-client capacity (merge). Called at the end
    of the reply-rate cap crons so the estimate tracks the caps just applied."""
    bd = _navreo_capacity_breakdown(force_fresh=True)
    nav = (bd.get("workspace") or {}).get("navreo")
    if not nav:
        return {"ok": False, "error": "no capacity data"}
    today = _dtmod.date.today().isoformat()
    _cap_blob_upsert(today, {"navreo": nav}, bd.get("clients") or {}, src="navreo-caps")
    _CLIENT_CAP.update(data=bd, ts=time.time())
    mcm_clients = _persist_mcm_after_sweep()
    return {"ok": True, "date": today, "navreo_workspace_cap": nav["cap"],
            "clients": len(bd.get("clients") or {}), "mcm_clients": mcm_clients}


def _persist_mcm_after_sweep():
    """Persist the mailbox→client map (mcm) that drives the Mailboxes tab's client
    filter. That map is only written from INSIDE api_mailbox_client_map(), which needs
    a completed restore sweep; the 512MB web instance OOMs before the sweep finishes,
    so the snapshot was never written and the web served an EMPTY map — the client
    filter showed "attributing…" for every client forever. Both snapshot_* callers run
    the sweep synchronously in a cron process just before calling this, so the map is
    ready here and gets persisted to the shared blob for the web to read. Best-effort:
    a failure must never break the capacity cron. Returns the client count, or None."""
    try:
        mp = api_mailbox_client_map()
        if mp.get("status") == "ready":
            return len(mp.get("clients") or {})
    except Exception as e:  # noqa: BLE001
        print(f"[mcm persist] skipped: {e}", file=sys.stderr)
    return None


def snapshot_all_capacity(workspaces: list | None = None,
                          force_fresh: bool = True) -> dict:
    """Persist TODAY's capacity for EVERY workspace — each pool straight from the
    mailboxes mirror (pause-aware), plus navreo per-client. Called from the
    federated mailbox sync so every workspace gets a real per-day row (navreo is
    additionally refreshed by the cap crons). One breakdown = all pools + clients;
    no per-workspace Smartlead sweep.

    force_fresh=True runs the ~7-min restore sweep synchronously — correct in a
    cron process, fatal on the web tier (512MB instance, see
    web-instance-oom-crashloop). force_fresh=False reuses the 10-min cached
    breakdown: the POOL caps come straight from the mailboxes mirror either way
    (one DB read, no Smartlead fan-out), so an intraday web-tier top-up still
    records a real per-workspace cap; only the navreo PER-CLIENT split needs the
    sweep, and it is simply omitted when the sweep is cold."""
    bd = _navreo_capacity_breakdown(force_fresh=force_fresh)
    pools = bd.get("workspace") or {}
    if not pools:
        return {"ok": False, "error": "no capacity data for any workspace"}
    if workspaces is None:
        workspaces = list(_FLEET_CAP_WS)
    ws_updates = {ws: pools[ws] for ws in workspaces if ws in pools}
    client_updates = bd.get("clients") if "navreo" in workspaces else None
    if client_updates is not None and not client_updates:
        # cold sweep (force_fresh=False): write the pools we DO know and leave the
        # per-client blob untouched rather than merging an empty client map
        client_updates = None
    today = _dtmod.date.today().isoformat()
    _cap_blob_upsert(today, ws_updates, client_updates, src="sync")
    _CLIENT_CAP.update(data=bd, ts=time.time())
    # This is the reliable SERVER-SIDE path (federated mailbox-sync cron), so persist
    # the mcm snapshot here too — the navreo cap crons that also persist it are
    # laptop-side scripts that don't always run. See _persist_mcm_after_sweep.
    mcm_clients = (_persist_mcm_after_sweep()
                   if force_fresh and "navreo" in workspaces else None)
    return {"ok": True, "date": today,
            "workspaces": {ws: v["cap"] for ws, v in ws_updates.items()},
            "clients": len(client_updates or {}), "mcm_clients": mcm_clients}


# Hourly per-workspace capacity top-up, from /api/cron/audit-refresh.
#
# WHY: the own-workspace pools (asteri/krg/grout) get exactly ONE capacity row a
# day, written by the 04:30 federated mailbox sync. Every cap change after that
# — a pause, a restore, a tier change — lands in the mirror but not in the day's
# recorded cap, so the Actively-sending cell measured that day's sends against a
# stale morning ceiling and could read over 100%. High-water merging means a
# later, higher snapshot can only raise the day's ceiling, never lower it
# (_cap_hw_merge), so topping up hourly is safe by construction.
#
# It runs on a background thread with force_fresh=False so the web tier never
# pays for the ~7-min restore sweep (web-instance-oom-crashloop) and never fans
# out to Smartlead on a request thread. The pool caps it records come from one
# mailboxes-mirror read.
_CAP_TOPUP_MIN_S = 55 * 60          # ≥55 min between runs — the tick is hourly
_CAP_TOPUP_LAST = [0.0]
_CAP_TOPUP_LOCK = threading.Lock()


def _capacity_topup_bg() -> None:
    try:
        r = snapshot_all_capacity(list(_FLEET_CAP_WS), force_fresh=False)
        print(f"[cap-topup] {r}", flush=True)
    except Exception as e:  # noqa: BLE001 — a top-up failure must never break the tick
        print(f"[cap-topup] failed: {e}", file=sys.stderr)


def _capacity_topup_start() -> dict:
    """Kick the throttled top-up. Returns what it did, so the cron response says
    whether it ran or was still inside its window."""
    with _CAP_TOPUP_LOCK:
        age = time.time() - _CAP_TOPUP_LAST[0]
        if age < _CAP_TOPUP_MIN_S:
            return {"started": False, "throttled_for_s": int(_CAP_TOPUP_MIN_S - age)}
        _CAP_TOPUP_LAST[0] = time.time()
    threading.Thread(target=_capacity_topup_bg, daemon=True).start()
    return {"started": True}


# ── warm-up capacity (sends/day currently being "repaired") ───────────────
# Estimated daily sending capacity currently IN WARM-UP, per client. Membership
# = the mailboxes currently RESTING per the deliverability bundle's inwarmup
# view (the rest-ledger truth the Resting tab shows) — owner-verified
# 2026-08-24: "resting" IS the definition of in-warm-up. The previous mirror
# heuristic (warmup_enabled AND (cap 0 OR no campaigns)) overcounted navreo
# 3.8x by sweeping in thousands of warmup-enabled-but-healthy pool boxes.
# Provider comes from the mirror's `account_type` (Smartlead's own field,
# joined by email; audit matched 0-miss), with the bundle's maildoso flag on
# top. Capacity is an ESTIMATE from fixed provider defaults (Outlook 2,
# Gmail 20, Maildoso 15, SMTP 15 sends/day/box) — deliberately NOT
# message_per_day, which is the configured cap, not the warm-up potential.
_WARMUP_CAP_DEFAULTS = {"OUTLOOK": 2, "GMAIL": 20, "MAILDOSO": 15, "SMTP": 15}
_WARMUP_CAP_CACHE: dict = {}
_WARMUP_CAP_TTL_S = 600


def warmup_capacity_get() -> tuple[dict, int]:
    """{ok, perClient:{Client:{capacityPerDay,boxes,byProvider}}, perWorkspace,
    total, boxes, mapReady, basis:"resting", generated_at}. 10-min cached;
    serves stale on a transient source hiccup.

    perClient is the surface the UI renders: every client — Navreo INCLUDED —
    gets its own warm-up capacity, no shared bucket. Attribution:
      • own-workspace clients → their workspace, keyed by display name from
        campaign_scorecard;
      • navreo-workspace boxes → the client whose ACTIVE campaigns they run
        (mailbox→client map, same truth as the client filter), else "Navreo".
    While the map is warming (mapReady false) navreo-ws boxes read under
    Navreo and split out when the sweep (or its persisted snapshot) lands."""
    from datetime import datetime, timezone
    ent = _WARMUP_CAP_CACHE.get("data")
    if ent and (time.time() - ent["ts"]) < _WARMUP_CAP_TTL_S:
        return ent["data"], 200
    # Resting truth: the deliverability bundle's inwarmup view (restored from
    # Supabase on a cold instance — one row read, no Smartlead traffic).
    _deliv_bundle_restore()
    with _DELIV_BUNDLE_LOCK:
        bundle = _DELIV_BUNDLE.get("data")
    # Warm-up cohort = the SAME warming set the Inbox & Domain Manager's Resting
    # tab renders: the deliverability bundle's inwarmup UNION rested views (dedup
    # by email). Reading inwarmup alone (the old behaviour) hid every parked-but-
    # warming domain — Smartlead warmup ACTIVE, no live campaign, sitting in the
    # "rested" view — so a client whose whole fleet was parked (e.g. Arnic) read
    # 0/day here while the Resting tab showed 14 domains "warming — sends held".
    # The rested view is navreo-ws only (the client-ws merge emits inwarmup only
    # for cap==0), so this cannot resurface the KRG cap>0 phantom; the client-ws
    # guard (_clientws_resting) below still protects every non-navreo box.
    _bv = ((bundle or {}).get("views") or {})
    _seen_cohort: dict = {}
    resting = []
    for _r in ((((_bv.get("inwarmup") or {}).get("rows")) or [])
               + (((_bv.get("rested") or {}).get("rows")) or [])):
        _ek = str(_r.get("email") or _r.get("id") or "").lower()
        if _ek and _ek in _seen_cohort:
            continue
        if _ek:
            _seen_cohort[_ek] = 1
        resting.append(_r)
    if not resting:
        # No bundle yet (or an empty view, which a real fleet never has) — a
        # cold/degraded instance, not a real zero. Never cache it.
        if ent:
            return ent["data"], 200
        return {"error": "warmup_capacity_unavailable",
                "message": "resting ledger (deliverability bundle) not available yet"}, 502
    # Provider truth: mirror account_type by email (Smartlead's own field).
    try:
        mrows = sb_get_all("mailboxes?select=email,account_type,workspace,"
                           "warmup_enabled,message_per_day,tags,domain") or []
    except Exception as e:  # noqa: BLE001
        if ent:
            return ent["data"], 200
        return {"error": "warmup_capacity_unavailable", "message": str(e)[:200]}, 502
    acct = {str(r.get("email") or "").lower(): str(r.get("account_type") or "").upper()
            for r in mrows if r.get("email")}
    # Ledger-only domains: in the rest LEDGER (bundle.restDue — a row is deleted
    # on restore, so a listed domain IS held) but with no held-box rows in either
    # bundle view yet (refresh lag). The Resting tab lists them; without this the
    # fleet number counted 0 boxes for them. Synthesize their held boxes from the
    # mirror (navreo-ws only — the ledger is navreo-ws) so volume tracks the tab.
    _rd_doms = {str(d).lower() for d in ((bundle or {}).get("restDue") or {})}
    if _rd_doms:
        _have_doms = {str(r.get("domain") or "").lower() for r in resting}
        _have_emails = {str(r.get("email") or "").lower() for r in resting}
        _ledger_only = _rd_doms - _have_doms
        for m in mrows:
            if str(m.get("workspace") or "") != "navreo":
                continue
            _dom = str(m.get("domain") or "").lower()
            _em = str(m.get("email") or "").lower()
            if _dom in _ledger_only and _em and _em not in _have_emails:
                _have_emails.add(_em)
                resting.append({"email": _em, "domain": _dom,
                                "workspace": "navreo", "tags": [], "provider": ""})
    # Mirror tag names by email (Smartlead tag OBJECTS → plain names) — used to
    # attribute a rested navreo-ws box to its client even when the bundle row
    # carries no tags.
    def _tag_names(r):
        out_ = []
        for t in (r.get("tags") or []):
            nm = t.get("tag_name") if isinstance(t, dict) else str(t)
            if nm:
                out_.append(str(nm))
        return out_
    mirror_tags = {str(r.get("email") or "").lower(): _tag_names(r)
                   for r in mrows if r.get("email")}
    # Client-workspace resting truth (owner audit #2, 2026-08-24): the bundle's
    # client-ws inwarmup rows are built on the mirror's campaign_count, which is
    # 0 on EVERY client-ws box (stale sync field) — so all 1,660 KRG boxes read
    # "resting" while KRG visibly sent 2.3k/day. A box that is configured to
    # send (message_per_day > 0) is NEVER resting; client-ws resting = warm-up
    # ON and cap 0. (Navreo-ws rows come from the real rest ledger — trusted.)
    mirror_box = {str(r.get("email") or "").lower(): r for r in mrows if r.get("email")}

    def _clientws_resting(email):
        r = mirror_box.get(email)
        if r is None:
            return True   # unknown to the mirror — keep the bundle's verdict
        return bool(r.get("warmup_enabled")) and not (r.get("message_per_day") or 0)
    # Attribution maps: email→client (shared-fleet boxes under navreo, from the
    # campaign-membership map) and workspace-slug→display name (own-workspace
    # clients). Both are best-effort — a failure just leaves boxes under Navreo
    # / their slug rather than 500-ing the column.
    email_client, ws_display, map_ready = {}, {}, False
    try:
        mp = api_mailbox_client_map()
        map_ready = (mp.get("status") == "ready")
        for cl, emails in (mp.get("clients") or {}).items():
            for em in emails:
                email_client[str(em).lower()] = cl
    except Exception:  # noqa: BLE001
        pass
    nav_clients = {}   # lowercase match token → display name (navreo-ws roster)
    try:
        for r in (sb_get_all("campaign_scorecard?select=client,workspace") or []):
            ws_ = (r.get("workspace") or "").strip()
            cl_ = (r.get("client") or "").strip()
            if not cl_ or cl_.startswith("__"):
                continue
            if ws_ and ws_ != "navreo":
                ws_display.setdefault(ws_, cl_)
            else:
                nav_clients.setdefault(cl_.lower(), cl_)
                first = cl_.split()[0]
                if len(first) >= 4:   # "Altius Reach" also matches plain "altius"
                    nav_clients.setdefault(first.lower(), cl_)
    except Exception:  # noqa: BLE001
        pass

    def _tag_client(r):
        """Fallback attribution for a navreo-ws resting box the campaign-
        membership map doesn't know (map cold after a deploy, or box parked
        with its campaigns since removed): a Smartlead tag literally naming a
        known client ("Amplifyy - Hypertide", "Arnic - Temporary") is strong
        evidence. The map stays primary — this only fills its gaps, so every
        resting box still lands on a client instead of "not mapped"."""
        email_ = str(r.get("email") or "").lower()
        cand = list(r.get("tags") or []) + mirror_tags.get(email_, [])
        for t in cand:
            tl = str(t).lower()
            for token, disp in nav_clients.items():
                if token in tl:
                    return disp
        return None

    def _provider(r, email):
        if r.get("maildoso"):
            return "MAILDOSO"
        a = acct.get(email, "")
        if "OUTLOOK" in a or "MICROSOFT" in a:
            return "OUTLOOK"
        if "GMAIL" in a or "GOOGLE" in a:
            return "GMAIL"
        if a:
            return "SMTP"
        # mirror miss → the bundle row's own provider string
        p = str(r.get("provider") or "").lower()
        if "maildoso" in p:
            return "MAILDOSO"
        if "outlook" in p or "office" in p or "azure" in p:
            return "OUTLOOK"
        if "gmail" in p or "google" in p:
            return "GMAIL"
        return "SMTP"

    # Seed every known client at zero so one with nothing resting reads "0/day"
    # (real) rather than dropping out; Navreo is always present too.
    def _seed():
        return {"capacityPerDay": 0, "boxes": 0, "byProvider": {}}
    per_client: dict = {"Navreo": _seed()}
    per_ws: dict = {}
    for cl in set(email_client.values()):
        per_client.setdefault(cl, _seed())
    # The whole navreo-ws client roster too: a client with NOTHING resting
    # right now must read "0/day" (real), never fall back to "— not mapped".
    for cl in set(nav_clients.values()):
        per_client.setdefault(cl, _seed())
    for r in mrows:
        ws0 = str(r.get("workspace") or "unknown")
        per_ws.setdefault(ws0, _seed())
        if ws0 != "navreo":
            per_client.setdefault(ws_display.get(ws0, ws0), _seed())
    total = boxes_total = 0
    for r in resting:
        ws = str(r.get("workspace") or "navreo")
        email = str(r.get("email") or "").lower()
        # A client-ws box configured to send is a SENDER the stale-campaign_count
        # bundle rule swept in — not resting; skip it (see _clientws_resting).
        if ws != "navreo" and not _clientws_resting(email):
            continue
        # navreo-ws boxes are NOT gated on the mirror's Smartlead warmup_status:
        # this cohort means "held from sending" (what the Resting tab shows), not
        # "Smartlead warm-up job running". Maildoso boxes warm on Instantly, so
        # their Smartlead job is INACTIVE by design, and parked/capped jobs read
        # INACTIVE too — an ACTIVE-only gate dropped 599 genuinely-held boxes
        # (2026-08-25) and made the fleet number contradict the Resting tab.
        cl = (email_client.get(email) or _tag_client(r) or "Navreo") if ws == "navreo" \
            else ws_display.get(ws, ws)
        prov = _provider(r, email)
        add = _WARMUP_CAP_DEFAULTS[prov]
        for tgt in (per_ws.setdefault(ws, _seed()), per_client.setdefault(cl, _seed())):
            tgt["capacityPerDay"] += add
            tgt["boxes"] += 1
            tgt["byProvider"][prov] = tgt["byProvider"].get(prov, 0) + 1
        total += add
        boxes_total += 1
    out = {"ok": True, "perClient": per_client, "perWorkspace": per_ws,
           "mapReady": map_ready, "basis": "resting",
           "total": total, "boxes": boxes_total,
           "generated_at": datetime.now(timezone.utc).isoformat()}
    # Don't cache a not-yet-attributed result for the full 10 min — a shorter
    # hold lets the split appear soon after the sweep (or its snapshot) lands.
    _WARMUP_CAP_CACHE["data"] = {"data": out,
                                 "ts": time.time() - (_WARMUP_CAP_TTL_S - 60 if not map_ready else 0)}
    return out, 200


# ── Repeat parks (park churn) ────────────────────────────────────────────────
# The 2026-08-28 capacity study found the real waste in the rest conveyor is a
# small tail of domains that keep earning a park: parked, rested 7 days,
# restored, parked again — some 10+ cycles in six weeks. Each cycle burns a
# rest window plus restore sends on a domain the market has already judged.
# This read surfaces that tail so the owner can retire domains instead of
# endlessly resurrecting them.
#
# Park events come from app_activity_log: `warmup_pause` rows (the warm-up-job
# path every parking flow uses — the deliverability service's floor/health
# sweeps, the manager's own Warm-up button) carry payload.domains_list, and
# `reply-caps` rows (the in-tool cap engines) carry payload.parked. The COUNT
# is distinct park DAYS per domain, not raw events — sweeps can double-fire
# the same pause within a minute, and "parked twice on Tuesday" is one strike,
# not two. Old `warmup-pause` (hyphen) rows have empty payloads — no domains
# to read, so they can't be counted.
_PARK_CHURN_CACHE: dict = {}
_PARK_CHURN_TTL_S = 600
PARK_CHURN_DAYS = 42       # trailing window (owner spec: "last 6 weeks")
PARK_CHURN_MIN = 2         # flag at 2+ parks; the UI escalates 3+ to "retire"
PARK_CYCLE_MIN_DAYS = 5    # a held run this long (through snapshot gaps) = a real 7-day rest
PARK_CYCLE_SAMPLE = 8      # boxes per domain read from mailbox_stats_daily
PARK_SNAPSHOT_EPOCH = "2026-07-08"  # first mailbox_stats_daily snapshot: "all time" = since then


def rest_enforce(mode: str = "preview") -> dict:
    """A rest, once ordered, must be SERVED (owner: 'we need to fix this',
    2026-08-28). The park↔restore ping-pong: the audit backend's warmup-pause
    routinely no-ops on navreo boxes and its own engine restores parked
    domains off-schedule, so a domain the floors engine parked could be back
    sending within hours — 10 park orders in 15 days with zero rest served.
    The pause path now zeroes caps directly and the ledger sync defends
    not-yet-due clocks; this is the third leg: any box found LIVE on a domain
    whose rest clock has not come due gets re-zeroed, workspace-aware.

    Runs daily right after the cap crons (which run after the 04:30 mailbox
    sync, so the mirror it reads is last night's Smartlead truth). Rows
    younger than 30 minutes are skipped — a pause job may still be zeroing
    them. Dismissed rows are skipped (restore-dismiss owns those). mode=
    "preview" returns the plan and writes nothing."""
    from datetime import datetime
    rows = sb_get_all("deliverability_resting_ledger"
                      "?select=domain,first_rested_at,dismissed&dismissed=is.false"
                      "&order=domain.asc") or []
    now_ms = int(time.time() * 1000)
    not_due = {}
    for r in rows:
        d = str(r.get("domain") or "").lower()
        try:
            start_ms = int(datetime.fromisoformat(
                str(r.get("first_rested_at")).replace("Z", "+00:00")).timestamp() * 1000)
        except Exception:  # noqa: BLE001 — no readable clock, nothing to enforce against
            continue
        if now_ms < start_ms + _DELIV_REST_DAYS_MS and now_ms - start_ms > 30 * 60000:
            not_due[d] = start_ms + _DELIV_REST_DAYS_MS
    live = []
    doms = sorted(not_due)
    for i in range(0, len(doms), 40):
        live.extend(sb_get_all(
            "mailboxes?select=smartlead_id,email,domain,workspace,message_per_day"
            "&message_per_day=gt.0&order=smartlead_id.asc"
            "&domain=in.(%s)" % ",".join(doms[i:i + 40])) or [])
    REST_ENFORCE_BOX_CAP = 400  # bound one run's Smartlead writes; the daily cadence drains the rest
    capped_out = live[:REST_ENFORCE_BOX_CAP]
    by_dom: dict = {}
    for b in capped_out:
        by_dom.setdefault(str(b.get("domain") or "").lower(), []).append(b)
    out = {"ok": True, "mode": mode, "restingNotDue": len(not_due),
           "liveDomains": len(by_dom), "liveBoxes": len(live),
           "boxesThisRun": len(capped_out),
           "plan": [{"domain": d, "boxes": len(bs),
                     "due_back": not_due.get(d)} for d, bs in sorted(by_dom.items())]}
    if mode != "apply" or not capped_out:
        return out
    job = _new_job("rest_enforce", "Rest enforcement: re-parking "
                   f"{len(capped_out)} live box(es) on {len(by_dom)} resting domain(s)", None)
    with JOBS_LOCK:
        job["counts"] = {"op": "rest_enforce", "domains": len(by_dom),
                         "boxes": len(capped_out),
                         "domains_list": sorted(by_dom)[:12]}
        job["progress"] = {"done": 0, "total": len(capped_out)}
    _job_started(job)
    zeroed, failed = [], []
    try:
        for i, b in enumerate(capped_out):
            try:
                _smartlead_json("POST", f"/email-accounts/{b['smartlead_id']}",
                                {"max_email_per_day": 0},
                                workspace=b.get("workspace") or "navreo")
                zeroed.append(str(b["smartlead_id"]))
            except Exception as ex:  # noqa: BLE001 — one bad box must not stop the sweep
                failed.append({"email": b.get("email"), "error": str(ex)[:120]})
            with JOBS_LOCK:
                job["progress"]["done"] = i + 1
            time.sleep(0.35)  # shared 200req/min Smartlead budget
        for i in range(0, len(zeroed), 60):
            try:
                sb("PATCH", "mailboxes?smartlead_id=in.(%s)" % ",".join(zeroed[i:i + 60]),
                   {"message_per_day": 0})
            except Exception:  # noqa: BLE001 — nightly sync self-corrects
                pass
    except Exception as e:  # noqa: BLE001 — the job row must never orphan as "running"
        with JOBS_LOCK:
            job["counts"].update(zeroed=len(zeroed), enforce_failed=len(failed))
        _job_finished(job, "failed", str(e)[:300])
        raise
    out.update(zeroed=len(zeroed), failed=failed)
    with JOBS_LOCK:
        job["counts"].update(zeroed=len(zeroed), enforce_failed=len(failed))
    _job_finished(job, "failed" if failed and not zeroed else "done",
                  failed[0]["error"] if failed and not zeroed else None)
    try:
        log_activity("/api/cron/rest-enforce",
                     payload={"domains": sorted(by_dom)[:40], "domain_count": len(by_dom),
                              "zeroed": len(zeroed), "failed": len(failed)},
                     actor="deliverability", action="rest_enforced", entity="domain")
    except Exception:  # noqa: BLE001 — logging must never fail the sweep
        pass
    return out


def park_churn_get(days: int = PARK_CHURN_DAYS, min_parks: int = PARK_CHURN_MIN,
                   force: bool = False) -> tuple[dict, int]:
    """{ok, days, min_parks, rows:[{domain, parks, first_parked, last_parked,
    resting_now, boxes, workspace}], generated_at}. rows sorted worst-first.
    10-min cached — the log scan is cheap but the manager badge polls it."""
    from datetime import datetime, timezone, timedelta
    days = max(7, min(120, int(days or PARK_CHURN_DAYS)))
    min_parks = max(1, int(min_parks or PARK_CHURN_MIN))
    key = (days, min_parks)
    hit = _PARK_CHURN_CACHE.get(key)
    if hit and not force and time.time() - hit["ts"] < _PARK_CHURN_TTL_S:
        return hit["data"], 200
    # Date-only bound: a full ISO timestamp carries "+00:00", whose "+" decodes
    # to a space in the query string and 400s the PostgREST read.
    since = (datetime.now(timezone.utc) - timedelta(days=days)).date().isoformat()
    # All-time read (the log starts 2026-07-11): the window only scopes the
    # per-row counts, "All time" cycles need every domain ever ordered parked.
    events = sb_get_all("app_activity_log?select=ts,action,payload"
                        f"&ts=gte.{PARK_SNAPSHOT_EPOCH}&action=in.(warmup_pause,reply-caps)"
                        "&order=id.asc")
    if not isinstance(events, list):
        if hit:  # transient log hiccup — stale beats a broken tab
            return hit["data"], 200
        return {"ok": False, "error": "activity-log read failed"}, 502
    # Two counts per domain (owner's arithmetic check, 2026-08-28: "10 parks
    # × 7 days can't fit in 42"): `orders` = distinct days ANY park order was
    # issued; `cycles` = distinct days a park VERIFIABLY landed on live boxes
    # — a warmup_pause whose job actually zeroed something (paused /
    # client_paused / direct_capped > 0) or a cap-engine park (which zeroes
    # caps itself, and only ever fires on non-resting domains). A big
    # orders-minus-cycles gap is the ping-pong signature: the same dead
    # domain ordered parked day after day while its rest never held.
    # History honesty: before the pause true-up shipped (2026-08-28), a park
    # could land at Smartlead without any of those counters (`paused: 0`
    # no-ops), so old cycles read LOW — the resting-now floor below keeps a
    # genuinely parked domain from reading zero.
    order_days: dict = {}
    landed_days: dict = {}
    for ev in events:
        p = ev.get("payload") or {}
        if not isinstance(p, dict):
            continue
        if ev.get("action") == "warmup_pause":
            doms = p.get("domains_list") or []
            landed = (int(p.get("paused") or 0) + int(p.get("client_paused") or 0)
                      + int(p.get("direct_capped") or 0)) > 0
        else:
            doms = p.get("parked") or []
            landed = True
        if not isinstance(doms, list):
            continue
        day = str(ev.get("ts") or "")[:10]
        for d in doms:
            d = str(d).strip().lower()
            if not d:
                continue
            order_days.setdefault(d, set()).add(day)
            if landed:
                landed_days.setdefault(d, set()).add(day)
    # ── Verified rest cycles (owner audit 2026-09-02) ───────────────────
    # "Landed" park days are NOT rests: the cap-history audit found the tab
    # crediting 288 "cycles" across 125 domains while the daily cap snapshots
    # (mailbox_stats_daily.message_per_day, per box per day) showed only 55
    # rests that actually ran their course — getnavreo.biz read 7 cycles and
    # had its caps at 0 for exactly ONE day. A cycle now means: the park
    # landed, the domain's boxes STAYED at cap 0 for a real rest, and the
    # domain came back to sending. Counted from the snapshots, not the log:
    #   held day   = >= 80% of the sampled boxes at message_per_day 0
    #   run        = consecutive held snapshots (the sync skips days, so a
    #                calendar gap with no snapshot in between does not break it)
    #   completed  = the run is followed by a live snapshot (it came BACK) and
    #                spans >= PARK_CYCLE_MIN_DAYS (5 — a 7-day rest read through
    #                snapshot gaps); a run still held today is `resting_days`,
    #                not a cycle; a run shorter than that which ended is a park
    #                that never held (`broken`).
    # Up to PARK_CYCLE_SAMPLE boxes per domain keep the read bounded (a park
    # zeroes the whole domain, so a handful of boxes is representative).
    candidates = sorted(order_days)
    ledger = {str(r.get("domain") or "").lower()
              for r in (sb_get_all("deliverability_resting_ledger?select=domain"
                                   "&dismissed=is.false&order=domain.asc") or [])}
    boxes: dict = {}
    ws: dict = {}
    sample: dict = {}
    all_ids: dict = {}   # smartlead_id -> domain, EVERY box (30d reply rate below)
    for i in range(0, len(candidates), 40):
        for b in (sb_get_all("mailboxes?select=smartlead_id,domain,workspace&order=smartlead_id.asc"
                             "&domain=in.(%s)" % ",".join(candidates[i:i + 40])) or []):
            d = str(b.get("domain") or "").lower()
            boxes[d] = boxes.get(d, 0) + 1
            ws.setdefault(d, b.get("workspace") or "navreo")
            all_ids[int(b["smartlead_id"])] = d
            if len(sample.setdefault(d, [])) < PARK_CYCLE_SAMPLE:
                sample[d].append(int(b["smartlead_id"]))
    dom_of = {sid: d for d, sids in sample.items() for sid in sids}
    ids = sorted(dom_of)
    # Whole snapshot history (from PARK_SNAPSHOT_EPOCH): the window count and
    # the "All time" count read the same runs, and a cycle that ENDS inside
    # the window is seen whole.
    snap_since = PARK_SNAPSHOT_EPOCH
    cap: dict = {}   # domain -> day -> [zero, total]
    for i in range(0, len(ids), 150):
        for r in (sb_get_all("mailbox_stats_daily?select=smartlead_id,stat_date,message_per_day"
                             f"&stat_date=gte.{snap_since}&order=smartlead_id.asc,stat_date.asc"
                             "&smartlead_id=in.(%s)" % ",".join(str(x) for x in ids[i:i + 150])) or []):
            d = dom_of.get(r.get("smartlead_id"))
            if not d:
                continue
            c = cap.setdefault(d, {}).setdefault(str(r.get("stat_date") or "")[:10], [0, 0])
            c[1] += 1
            if int(r.get("message_per_day") or 0) == 0:
                c[0] += 1
    today = datetime.now(timezone.utc).date()
    # Trailing-30d reply rate per domain from the LATEST mirror snapshot over
    # every box on the domain (owner 2026-09-02: the audit backend's
    # domain-health rows only cover the domains its inventory knows — 91 of
    # 129 flagged domains had no row in ANY window, so the tab read "—").
    # mailbox_stats_daily.sent_30d / replies_30d are Smartlead's own rolling
    # counters, so this covers parked domains too (their last 30 days of
    # sends before the park).
    rr: dict = {}   # domain -> [sent_30d, replies_30d]
    try:
        latest = (sb_get_all("mailbox_stats_daily?select=stat_date"
                             "&order=stat_date.desc&limit=1") or [{}])[0].get("stat_date")
    except Exception:  # noqa: BLE001 — rate is context, never a 502
        latest = None
    if latest:
        aid = sorted(all_ids)
        for i in range(0, len(aid), 200):
            for r in (sb_get_all("mailbox_stats_daily?select=smartlead_id,sent_30d,replies_30d"
                                 f"&stat_date=eq.{str(latest)[:10]}&order=smartlead_id.asc"
                                 "&smartlead_id=in.(%s)" % ",".join(str(x) for x in aid[i:i + 200])) or []):
                d = all_ids.get(r.get("smartlead_id"))
                if not d:
                    continue
                a = rr.setdefault(d, [0, 0])
                a[0] += int(r.get("sent_30d") or 0)
                a[1] += int(r.get("replies_30d") or 0)

    def _cycles(d: str) -> dict:
        runs, cur = [], None
        for day in sorted(cap.get(d) or {}):
            z, t = cap[d][day]
            share = (z / t) if t else 0
            # A run STARTS at >= 80% of boxes on cap 0 and only ENDS once the
            # majority is live again (< 50% still at 0): a restore in flight
            # (a few boxes woken, the rest still parked) is still the same rest,
            # not "came back" — the 5-box sample misread krgglobaladvisors.info
            # (44/52 at 0 on the day of the read) as a completed cycle.
            held = t > 0 and (share >= 0.8 or (cur is not None and share >= 0.5))
            if held:
                cur = [day, day] if cur is None else [cur[0], day]
            elif cur:
                runs.append((cur[0], cur[1], False))
                cur = None
        if cur:
            runs.append((cur[0], cur[1], True))
        done, done_all, broken, resting_days = [], [], 0, 0
        for a, b, ongoing in runs:
            if ongoing:
                resting_days = (today - datetime.fromisoformat(a).date()).days
                continue
            span = (datetime.fromisoformat(b).date() - datetime.fromisoformat(a).date()).days
            if span >= PARK_CYCLE_MIN_DAYS:
                done_all.append((a, b))
                if b >= since:
                    done.append((a, b))
            elif a >= since:
                broken += 1
        return {"cycles": len(done), "cycle_spans": done,
                "cycles_all": len(done_all), "cycle_spans_all": done_all,
                "broken": broken, "resting_days": resting_days}

    rows = []
    for d in candidates:
        ds = sorted(day for day in order_days[d] if day >= since)
        orders = len(ds)
        cy = _cycles(d)
        landed = len(landed_days.get(d) or ())
        # Owner 2026-09-02: a row = a domain with at least one VERIFIED rest
        # ever; park orders alone no longer earn a row (they're not rests).
        if cy["cycles_all"] < 1:
            continue
        sent30, rep30 = rr.get(d, [0, 0])
        rows.append({"domain": d, "orders": orders,
                     "cycles": cy["cycles"],            # VERIFIED completed rests in window
                     "cycle_spans": cy["cycle_spans"],
                     "cycles_all": cy["cycles_all"],    # VERIFIED completed rests since snapshots began
                     "cycle_spans_all": cy["cycle_spans_all"],
                     "sent_30d": sent30, "replies_30d": rep30,
                     "reply_rate_30d": (round(rep30 * 100.0 / sent30, 2) if sent30 else None),
                     "stats_as_of": latest,
                     "landed": landed,                  # park days that zeroed boxes (old "cycles")
                     "broken": cy["broken"],            # parks that never held a rest
                     "resting_days": cy["resting_days"],
                     "parks": orders,  # legacy alias — clients before the cycles split
                     "rest_not_holding": cy["broken"] >= 2,
                     "first_parked": ds[0] if ds else None, "last_parked": ds[-1] if ds else None,
                     "resting_now": (d in ledger) or cy["resting_days"] > 0,
                     "boxes": boxes.get(d, 0),
                     "workspace": ws.get(d, "navreo")})
    rows.sort(key=lambda r: r["last_parked"] or "", reverse=True)   # ties: newest first
    rows.sort(key=lambda r: r["cycles_all"], reverse=True)          # stable
    rows.sort(key=lambda r: r["cycles"], reverse=True)              # window cycles first
    out = {"ok": True, "days": days, "min_parks": min_parks, "rows": rows,
           "snapshots_since": PARK_SNAPSHOT_EPOCH, "stats_as_of": latest,
           "generated_at": datetime.now(timezone.utc).isoformat()}
    _PARK_CHURN_CACHE[key] = {"data": out, "ts": time.time()}
    return out, 200


def fleet_capacity_get(days: int = 30) -> tuple[dict, int]:
    days = max(7, min(90, days))
    with _FLEET_CAP_LOCK:
        ent = _FLEET_CAP.get(days)
    if ent and (time.time() - ent["ts"]) < _FLEET_CAP_TTL_S:
        base = ent["data"]
    else:
        try:
            base = _fleet_capacity_build(days)
        except Exception as e:  # noqa: BLE001
            if ent:
                base = ent["data"]      # serve stale on a transient DB hiccup
            else:
                return {"error": "capacity_unavailable", "message": str(e)[:200]}, 502
        else:
            with _FLEET_CAP_LOCK:
                _FLEET_CAP[days] = {"data": base, "ts": time.time()}
    # per-client caps ride outside the 1h series cache so they populate as soon
    # as the restore sweep warms (own 10-min cache).
    out = dict(base)
    live = _navreo_caps_live()                       # {} until the sweep warms
    live_clients = {c: v["cap"] for c, v in (live.get("clients") or {}).items()}
    out["client_caps"] = live_clients
    # Real per-day history from the daily cap-cron snapshot: overlay the navreo
    # pool series (replace carried-forward days, anchor TODAY to live) and add
    # per-client daily lines so shared-client charts stop borrowing the fleet
    # shape (Bjion 2026-08-21 capacity audit).
    try:
        hist = _client_cap_history()
    except Exception:  # noqa: BLE001 — history is an enhancement, never a 500
        hist = {}
    days = out.get("days") or []
    live_pools = live.get("workspace") or {}          # every workspace's live pool (mirror, pause-aware)
    if days and (hist or live_pools or live_clients):
        today = _dtmod.date.today().isoformat()
        cap = dict(out.get("capacity") or {})
        # Overlay EVERY workspace's real recorded per-day capacity, and anchor
        # TODAY to the live mirror pool — a pause zeroes the global cap there, so
        # this reflects pauses and is never a carried-forward value.
        for ws in _FLEET_CAP_WS:
            arr = list(cap.get(ws) or [None] * len(days))
            live_ws = (live_pools.get(ws) or {}).get("cap")
            for i, d in enumerate(days):
                rec = hist.get(d)
                hv = rec.get("workspace", {}).get(ws, {}).get("cap") if rec else None
                if hv is not None:
                    arr[i] = hv
                if d == today and live_ws is not None:
                    # today is never carried forward, but the live pause-aware
                    # pool must not DROP the ceiling below caps already recorded
                    # today (a late pause can't retroactively un-authorize sends
                    # already banked) — take the high-water.
                    arr[i] = max(arr[i] or 0, live_ws)
            cap[ws] = arr
        clients_all = set(live_clients)
        for rec in hist.values():
            clients_all.update((rec.get("clients") or {}).keys())
        ccd: dict = {}
        for cl in clients_all:
            arr = []
            for d in days:
                rec = hist.get(d)
                v = rec.get("clients", {}).get(cl, {}).get("cap") if rec else None
                if d == today and cl in live_clients:
                    v = max(v or 0, live_clients[cl])   # high-water, never drop below recorded
                arr.append(v)
            ccd[cl] = arr
        out["client_caps_daily"] = ccd
        # 'All' capacity = the sum of the individual clients/businesses, never the
        # pooled workspace figure (Bjion 2026-08-21: the Navreo pool is meaningless
        # — capacity is always client-by-client, business-by-business). navreo side
        # = Σ its per-client caps where recorded, else the navreo pool as a history
        # fallback; asteri/krg/grout each stand for one business.
        total = [0] * len(days)
        seen = [False] * len(days)
        navarr = cap.get("navreo") or []
        for i in range(len(days)):
            navsum, havenav = 0, False
            for arr in ccd.values():
                v = arr[i] if i < len(arr) else None
                if v:
                    navsum += v
                    havenav = True
            nav = navsum if havenav else (navarr[i] if i < len(navarr) else None)
            if nav:
                total[i] += nav
                seen[i] = True
            for ws in ("asteri", "krg", "grout"):
                a = cap.get(ws) or []
                v = a[i] if i < len(a) else None
                if v:
                    total[i] += v
                    seen[i] = True
        cap["__all"] = [total[i] if seen[i] else None for i in range(len(days))]
        out["capacity"] = cap
    return out, 200


def capacity_invariant_check(days: int = 30) -> tuple[dict, int]:
    """Enforce capacity >= sent per (client_label, day), honestly, given Smartlead
    exposes only DAILY sent totals (no intraday send timeline).

    Each stored day carries the authorized-cap snapshots taken by the crons:
      cap_min  lowest POSITIVE authorized cap in force that day
      cap_max  high-water (highest authorized cap in force that day)
    Neither is ever derived from sent, so neither can silently absorb an over-send.
    Verdict per (client, day):
      clean      sent <= cap_min          safe under any intraday ordering
      suspect    cap_min < sent <= cap_max  daily totals can't prove/disprove an
                                           intraday breach — flagged, NOT cleared
      violation  sent > cap_max           no authorized cap in force explains it →
                                           a genuine hard-cap enforcement defect
      no_capacity  a day with sent but no recorded capacity snapshot (a missed/
                                           failed writer run — a data gap, flagged)
    Only cap_min clears a day; the display high-water never clears one. Returns
    non-clean rows newest-first plus a summary, so the frontend/audit can surface
    genuine over-sends without hiding them and Step 8 has an independent yardstick."""
    try:
        hist = _client_cap_history()          # {date: {"workspace":{}, "clients":{}}}
    except Exception as e:  # noqa: BLE001
        return {"error": "capacity_history_unavailable", "message": str(e)[:200]}, 502
    cw, _st = client_windows_get()
    axis = (cw or {}).get("days") or []
    series = (cw or {}).get("series") or {}
    if not axis:
        return {"error": "sent_series_unavailable"}, 502
    # A sent label is EITHER a navreo sub-client (stored under day["clients"]) or a
    # connected workspace (stored under day["workspace"] by slug — e.g. "KRG"->"krg"
    # via ws_labels). Resolve BOTH so connected-workspace days aren't all no_capacity.
    ws_labels = (cw or {}).get("ws_labels") or {}      # {"KRG":"krg", "Grout":"grout", ...}

    def _cap_rec(day: str, label: str):
        drec = hist.get(day) or {}
        r = (drec.get("clients") or {}).get(label)
        if r:
            return r
        slug = ws_labels.get(label) or label.lower()
        return (drec.get("workspace") or {}).get(slug)

    horizon = set(axis[-max(7, min(120, days)):])
    rows = []
    counts = {"clean": 0, "suspect": 0, "violation": 0, "no_capacity": 0}
    for label, s in series.items():
        if label.startswith("__"):            # __all / __navreo_ws aggregates — skip
            continue
        sent_arr = (s or {}).get("sent") or []
        for i, d in enumerate(axis):
            if d not in horizon:
                continue
            sent = int(sent_arr[i] or 0) if i < len(sent_arr) else 0
            if sent <= 0:
                continue
            rec = _cap_rec(d, label)
            if not rec:
                counts["no_capacity"] += 1
                rows.append({"client": label, "day": d, "sent": sent,
                             "cap_min": None, "cap_max": None, "verdict": "no_capacity",
                             "excess": sent, "snaps": []})
                continue
            cap_max = int(rec.get("cap_max", rec.get("cap") or 0))
            cap_min = int(rec.get("cap_min", cap_max))
            if sent <= cap_min:
                counts["clean"] += 1
                continue
            verdict = "violation" if sent > cap_max else "suspect"
            counts[verdict] += 1
            rows.append({"client": label, "day": d, "sent": sent,
                         "cap_min": cap_min, "cap_max": cap_max, "verdict": verdict,
                         "excess": sent - cap_max if verdict == "violation" else sent - cap_min,
                         "snaps": rec.get("snaps") or []})
    rows.sort(key=lambda r: (r["day"], r["client"]), reverse=True)
    ok = counts["violation"] == 0 and counts["suspect"] == 0 and counts["no_capacity"] == 0
    return {"ok": ok, "counts": counts, "rows": rows,
            "checked_days": sorted(horizon, reverse=True),
            "note": "Smartlead exposes daily sent only; 'suspect' = a day daily totals "
                    "cannot prove clean or in-violation without intraday send checkpoints.",
            "asof": _dtmod.datetime.utcnow().isoformat() + "Z"}, 200


# ── Client windows: per-client sent/replies/bounces for 7/14/30 days ────────
# The analytics hub's date+client filters need SENT split by client and window,
# and no store has it (sent_messages archives repliers only; day-wise stats are
# per-workspace). Built here from Smartlead itself: one analytics-by-date call
# per candidate campaign per window, aggregated to the client label the page
# already uses (workspace when not navreo, else name keyword — mirrors
# analytics_hub_v1's cmap). Per-workspace day-wise series ride along so Asteri/
# KRG (and the all-clients sum) get true daily sent/bounce/rate lines.
# Slow to build (~2-4 min for ~300 campaigns), so: SWR cache, background build,
# serve stale forever, and a disk snapshot for instant warm boots.
_CLIENT_WIN_FILE = APP_DIR / "data" / "client_windows.json"
_CLIENT_WIN = {"data": None, "ts": 0.0, "running": False, "error": None}
_CLIENT_WIN_LOCK = threading.Lock()
_CLIENT_WIN_TTL_S = 7200
_CLIENT_WIN_WINDOWS = (30, 14, 7)


# Clients that SHARE the navreo Smartlead workspace are told apart purely by
# campaign NAME (case-insensitive substring) — this is exactly the filter Bjion
# runs by hand in Smartlead ("all campaigns whose name contains X"), so the tool
# must replicate it 1:1 (Bjion 2026-07-29). Ordered: first match wins. A shared-
# workspace campaign matching NONE of these is UNASSIGNED — it belongs to no
# client and must not inflate anyone's totals (previously everything unmatched
# was silently dumped into "Navreo", over-counting Navreo 30d sent by ~34%).
_SHARED_WS_CLIENTS = (
    ("amplif", "Amplifyy"),
    ("arnic", "Arnic"),
    ("qwintiq", "Qwintiq"),
    ("thunderbird", "ThunderBird"),   # ThunderBird is its own client (Bjion 2026-07-28)
    ("revive", "REViVE"),             # in-workspace client (Bjion 2026-09-02)
    ("greenshift", "Greenshift"),     # in-workspace client (Bjion 2026-09-02)
    ("altius", "Altius Reach"),       # in-workspace client (Bjion 2026-08-11)
    ("touchpoint", "TouchPoint"),     # in-workspace client (Bjion 2026-08-11)
    ("acme", "Acme"),                 # DEMO client (Bjion 2026-07-29) — see _DEMO_CLIENT_LABELS
    ("navreo", "Navreo"),             # Navreo is now name-gated like every other client
)
_CLIENT_UNASSIGNED = "__unassigned"

# Demo clients: fake clients that PERSIST in the tool so prospects can be shown how
# the platform works. Their data must never mix into a real client's numbers — the
# Settings "Show demo clients" toggle filters them in/out of every surface (Campaigns,
# Lists, Analytics, Setter) via is_demo_client(). Name-gated demos live in the label
# set below; own-workspace demos (none yet) would carry a slug in _DEMO_WORKSPACE_SLUGS.
_DEMO_CLIENT_LABELS = frozenset({"Acme"})
_DEMO_WORKSPACE_SLUGS = frozenset()


def is_demo_client(label=None, workspace=None) -> bool:
    """True if a client (by display label and/or workspace slug) is a demo client."""
    if workspace and workspace in _DEMO_WORKSPACE_SLUGS:
        return True
    return bool(label) and label in _DEMO_CLIENT_LABELS


# UI prefs — KV-backed (same deliverability_audit_cache store client_windows uses, so a
# deploy restores instantly). Currently one pref: whether DEMO clients show in day-to-day
# surfaces. Default False → demo clients hidden everywhere until Bjion flips the Settings
# "Show demo clients" switch.
#
# Keyed patch (auto-mover Step 3): the blob now carries more than the demo
# switch. Every key has a declared coercer + default in _UI_PREFS_KEYS, so a
# read miss, a legacy blob written before the key existed, and a partial POST
# all land on the same shape. show_demo_clients behaviour is unchanged.
_UI_PREFS_KEYS = {
    # key                 -> (coercer, default)
    "show_demo_clients":   (bool, False),
    # Variant Auto-Mover global switch. Default False — the mover is inert
    # until someone flips this on Settings → General (arming is Step 5).
    "auto_mover_enabled":  (bool, False),
    # Circuit breaker (R1): {"tripped": bool, "reason": str, "at": iso}. Set by
    # the mover when a counter drops or saves fail; clears only by hand.
    "auto_mover_breaker":  (dict, {}),
}
_UI_PREFS = {k: (d.copy() if isinstance(d, dict) else d)
             for k, (_c, d) in _UI_PREFS_KEYS.items()}
_UI_PREFS_TS = 0.0
_UI_PREFS_TTL = 30.0


def _ui_prefs_coerce(key: str, val) -> object:
    """One declared value for one declared key — never a raw blob passthrough."""
    coercer, default = _UI_PREFS_KEYS[key]
    if val is None:
        return default.copy() if isinstance(default, dict) else default
    if coercer is dict:
        return dict(val) if isinstance(val, dict) else (default.copy() if isinstance(default, dict) else default)
    return coercer(val)


def _ui_prefs(force: bool = False) -> dict:
    global _UI_PREFS_TS
    if not force and (time.time() - _UI_PREFS_TS) < _UI_PREFS_TTL:
        return dict(_UI_PREFS)
    try:
        rows = sb("GET", "deliverability_audit_cache?id=eq.ui_prefs&select=blob") or []
        if rows and isinstance(rows[0].get("blob"), dict):
            blob = rows[0]["blob"]
            for k in _UI_PREFS_KEYS:
                _UI_PREFS[k] = _ui_prefs_coerce(k, blob.get(k))
    except Exception:  # noqa: BLE001 — a read miss just keeps the default
        pass
    _UI_PREFS_TS = time.time()
    return dict(_UI_PREFS)


def show_demo_clients() -> bool:
    if os.environ.get("DEMO_FORCE") == "1":  # local dev/test override (never set in prod)
        return True
    return bool(_ui_prefs().get("show_demo_clients"))


def _ui_prefs_set(patch) -> dict:
    """Patch one or more ui_prefs keys and return the FULL new prefs blob.

    Accepts either a partial dict (the keyed patch — unknown keys ignored) or,
    for the original single-switch callers, a bare bool meaning show_demo_clients.
    Untouched keys keep their current stored value: the blob is always written
    whole, so a partial POST can never drop a sibling key.
    """
    global _UI_PREFS_TS
    if not isinstance(patch, dict):
        patch = {"show_demo_clients": bool(patch)}
    cur = _ui_prefs(force=True)  # read-modify-write: never clobber a sibling key
    blob = {k: cur.get(k, d.copy() if isinstance(d, dict) else d)
            for k, (_c, d) in _UI_PREFS_KEYS.items()}
    for k in _UI_PREFS_KEYS:
        if k in patch:
            blob[k] = _ui_prefs_coerce(k, patch[k])
    sb("POST", "deliverability_audit_cache?on_conflict=id",
       {"id": "ui_prefs", "blob": blob, "ts": _dtmod.datetime.utcnow().isoformat() + "Z"},
       prefer="resolution=merge-duplicates,return=minimal")
    _UI_PREFS.update(blob)
    _UI_PREFS_TS = 0.0
    return dict(blob)


def auto_mover_enabled(force: bool = False) -> bool:
    """The global kill switch. The mover reads it with force=True at run start,
    before every enqueue, and inside the queued job before the save (R11)."""
    return bool(_ui_prefs(force=force).get("auto_mover_enabled"))


# ── Variant Auto-Mover — per-campaign switch + move ledger ───────────────────
# The per-campaign switch is three-state: `inherit` (follow the global switch —
# the default, and no row is stored), `on`, `off`. Per-campaign `off` beats
# global `on`; per-campaign `on` NEVER beats global `off` (R11).
_AUTO_MOVER_MODES = ("inherit", "on", "off")


def auto_mover_campaign_mode(cid: str) -> str:
    from urllib.parse import quote
    try:
        rows = sb("GET", "auto_mover_campaign_prefs?campaign_id=eq."
                  + quote(str(cid), safe="") + "&select=mode&limit=1") or []
        m = (rows[0].get("mode") if rows else "") or "inherit"
        return m if m in _AUTO_MOVER_MODES else "inherit"
    except Exception:  # noqa: BLE001 — a read miss inherits, it never arms
        return "inherit"


def auto_mover_campaign_pref(cid: str) -> dict:
    """{mode, set_by, set_at} for one campaign — absence reads as inherit."""
    from urllib.parse import quote
    try:
        rows = sb("GET", "auto_mover_campaign_prefs?campaign_id=eq."
                  + quote(str(cid), safe="") + "&select=mode,set_by,set_at&limit=1") or []
    except Exception:  # noqa: BLE001
        rows = []
    r = rows[0] if rows else {}
    mode = (r.get("mode") or "inherit")
    return {"mode": mode if mode in _AUTO_MOVER_MODES else "inherit",
            "set_by": r.get("set_by"), "set_at": r.get("set_at")}


def auto_mover_last_move(cid: str) -> dict:
    """The latest ledger row for a campaign, or {} — powers "last auto-move: …"."""
    from urllib.parse import quote
    try:
        rows = sb("GET", "auto_mover_moves?campaign_id=eq." + quote(str(cid), safe="")
                  + "&select=id,step,action,winner,mode,pcts_before,pcts_after,"
                    "actor,outcome,issue_kind,created_at"
                    "&order=created_at.desc&limit=1") or []
    except Exception:  # noqa: BLE001
        rows = []
    return rows[0] if rows else {}


def api_campaign_auto_move_get(cid: str) -> tuple:
    """GET /api/campaigns/{cid}/auto-move — the switch + the last move."""
    cid = str(cid or "").strip()
    if not cid:
        return 400, {"ok": False, "message": "campaign id required"}
    pref = auto_mover_campaign_pref(cid)
    return 200, {"ok": True, "campaign_id": cid, **pref,
                 "global_enabled": auto_mover_enabled(),
                 "last_auto_move": auto_mover_last_move(cid) or None}


def api_campaign_auto_move_set(cid: str, payload: dict, actor: str = "") -> tuple:
    """POST /api/campaigns/{cid}/auto-move {mode: inherit|on|off}."""
    cid = str(cid or "").strip()
    if not cid:
        return 400, {"ok": False, "message": "campaign id required"}
    mode = str((payload or {}).get("mode") or "").strip().lower()
    if mode not in _AUTO_MOVER_MODES:
        return 400, {"ok": False,
                     "message": "mode must be one of: " + ", ".join(_AUTO_MOVER_MODES)}
    row = {"campaign_id": cid, "mode": mode, "set_by": actor or "app",
           "set_at": _dtmod.datetime.utcnow().isoformat() + "Z"}
    sb("POST", "auto_mover_campaign_prefs?on_conflict=campaign_id", row,
       prefer="resolution=merge-duplicates,return=minimal")
    return 200, {"ok": True, "campaign_id": cid, "mode": mode,
                 "set_by": row["set_by"], "set_at": row["set_at"],
                 "global_enabled": auto_mover_enabled(),
                 "last_auto_move": auto_mover_last_move(cid) or None}


def api_auto_mover_moves(limit: int = 50, issues_only: bool = False,
                         thin_only: bool = False) -> dict:
    """GET /api/auto-mover/moves?limit=50[&issues=1|&thin=1] — General's feed.

    ``issues=1`` is the real-issue feed (save_failed / counter_drop / human_owned
    / flap / breaker). ``thin_evidence`` is digest-only by design (rule R3 — it
    never becomes a Notion task), so it is excluded there and served on its own
    via ``thin=1``.
    """
    try:
        limit = max(1, min(200, int(limit or 50)))
    except (TypeError, ValueError):
        limit = 50
    sel = ("id,campaign_id,step,action,winner,leaders,mode,via,laggards,dropped,"
           "pcts_before,pcts_after,notification_id,actor,outcome,issue_kind,"
           "notion_task_url,created_at")
    qs = "auto_mover_moves?select=" + sel + "&order=created_at.desc&limit=" + str(limit)
    if thin_only:
        qs += "&issue_kind=eq.thin_evidence"
    elif issues_only:
        qs += "&or=(outcome.eq.issue,issue_kind.not.is.null)&issue_kind=neq.thin_evidence"
    try:
        rows = sb("GET", qs) or []
    except Exception as e:  # noqa: BLE001 — an empty feed beats a 500 on the page
        return {"ok": True, "moves": [], "count": 0, "warning": str(e)[:200]}
    return {"ok": True, "moves": rows, "count": len(rows)}


# ── Campaign change log ──────────────────────────────────────────────────────
# One unified, newest-first feed of every change made to ONE campaign, for the
# campaign page's "Change Logs" tab (Bjion, 2026-09-04). Read-only. Sources:
#   * auto_mover_moves        — auto-optimise traffic moves (the "variant" moves)
#   * app_activity_log        — manual version edits, list-verify audits, status
#                               changes, and auto-optimise switch flips
#   * list_upload_qa_runs     — upload-gate list audits
#   * qa_gate_runs            — reviewed upload-gate runs
#   * replies (positive cats) — new positives, and meetings booked (Call Booked)
# Each source is read in its own try, so one outage drops only that lane, never
# the whole feed (same discipline as _report_auto_moves).
_CLOG_POS_CATS = ("Interested", "Information Request", "Meeting Request")
_CLOG_ALL_POS = ("Interested", "Information Request", "Meeting Request", "Call Booked")


def _clog_pcts(before, after) -> str:
    """A short 'A 20%->80%, B 80%->20%' line for a traffic move, or ''."""
    if not isinstance(after, dict) or not after:
        return ""
    before = before if isinstance(before, dict) else {}
    parts = []
    for lab in sorted(after.keys()):
        b = before.get(lab)
        a = after.get(lab)
        try:
            a_i = int(round(float(a)))
        except (TypeError, ValueError):
            continue
        try:
            b_i = int(round(float(b)))
        except (TypeError, ValueError):
            b_i = None
        if b_i is None or b_i == a_i:
            parts.append(f"{lab} {a_i}%")
        else:
            parts.append(f"{lab} {b_i}% → {a_i}%")
    return ", ".join(parts)


def _clog_from_activity(row: dict):
    """Map one app_activity_log row to (kind, title, detail, tag) or None."""
    action = str(row.get("action") or "")
    pl = row.get("payload") if isinstance(row.get("payload"), dict) else {}

    def _email_step(default="1"):
        e = pl.get("email")
        return str(e) if e not in (None, "") else default

    if action == "variant-action":
        va = str(pl.get("action") or "")
        lab = str(pl.get("variant_label") or "").strip()
        step = _email_step()
        titles = {
            "scale_winner": f"Sent all of Email {step} to version {lab}",
            "back_winner":  f"Sent most of Email {step} to version {lab}, kept testing the rest",
            "disable":      f"Turned off version {lab} on Email {step}",
            "enable":       f"Turned version {lab} back on for Email {step}",
            "shift_share":  f"Shifted Email {step} traffic to version {str(pl.get('to_label') or lab)}",
            "split_leaders": f"Split Email {step} evenly between the leading versions",
        }
        return ("variant", titles.get(va, f"Changed the version split on Email {step}"),
                "", "Version edit")
    if action in ("add_variant", "add-variant"):
        step = _email_step()
        lab = str(pl.get("label") or "").strip()
        base = str(pl.get("base") or "").strip()
        det = (f"Copied from version {base}" if base else "")
        return ("variant", f"Added a new version to Email {step}"
                + (f" (version {lab})" if lab else ""), det, "Version edit")
    if action in ("draft", "draft-challenger"):
        return ("variant", "Drafted a challenger version", "", "Version edit")
    if action == "campaign-status":
        st = str(pl.get("status") or "").upper()
        m = {"START": "Set the campaign live",
             "PAUSED": "Paused the campaign",
             "STOPPED": "Marked the campaign completed"}
        if st not in m:
            return None
        return ("status", m[st], "", "Status")
    if action == "auto-move":
        mode = str(pl.get("mode") or "").lower()
        m = {"on": "Auto Optimise turned on for this campaign",
             "off": "Auto Optimise turned off for this campaign",
             "inherit": "Auto Optimise set to follow the tool-wide switch"}
        if mode not in m:
            return None
        return ("switch", m[mode], "", "Auto Optimise")
    if action == "verify_run":
        total = _sc_int(pl.get("total"))
        bad = _sc_int(pl.get("bad"))
        det = ""
        if pl.get("removed") is not None:
            det = f"{_sc_int(pl.get('removed'))} risky leads removed"
        return ("audit", f"Audited the list for deliverability — checked {total:,}, "
                f"{bad:,} flagged", det, "List audit")
    if action == "remove_bad":
        removed = _sc_int(pl.get("removed"))
        if not removed and not pl.get("cancelled"):
            return None
        return ("audit", f"Removed {removed:,} risky leads from the list", "", "List audit")
    return None


def campaign_change_log(cid: str, limit: int = 200) -> tuple:
    """GET /api/campaigns/{cid}/change-log — the campaign's whole change history,
    newest first, as a plain-English event feed."""
    from urllib.parse import quote
    try:
        n = int(str(cid).strip())
    except (TypeError, ValueError):
        return 400, {"ok": False, "message": "campaign id must be numeric"}
    scid = str(n)
    events: list = []

    def _add(at, kind, title, detail="", who="", tag=""):
        if not at or not title:
            return
        events.append({"at": str(at), "kind": kind, "title": title,
                       "detail": detail or "", "who": who or "", "tag": tag or ""})

    # 1 — auto-optimise traffic moves (the "variant" changes)
    try:
        rows = sb("GET", "auto_mover_moves?select=winner,mode,leaders,outcome,"
                  "pcts_before,pcts_after,actor,created_at"
                  f"&campaign_id=eq.{scid}&order=created_at.desc&limit=120") or []
        for r in (rows if isinstance(rows, list) else []):
            mode = str(r.get("mode") or "")
            win = r.get("winner")
            leaders = [str(x) for x in (r.get("leaders") or [])]
            if str(r.get("outcome") or "") != "moved":
                title = "Auto Optimise reviewed the versions and made no change"
            elif mode == "tie" and leaders:
                title = "Split Email 1 evenly between the tied versions (" + ", ".join(leaders) + ")"
            elif mode == "partial" and win:
                title = f"Sent most of Email 1 to the best version ({win}), kept testing the rest"
            elif win:
                title = f"Sent all of Email 1 to the best version ({win})"
            else:
                title = "Adjusted the version split on Email 1"
            _add(r.get("created_at"), "optimise", title,
                 _clog_pcts(r.get("pcts_before"), r.get("pcts_after")),
                 r.get("actor") or "auto-optimise@navreo.ai", "Auto Optimise")
    except Exception:  # noqa: BLE001
        pass

    # 2 — activity log: manual edits, list-verify audits, status + switch flips
    try:
        rows = sb("GET", "app_activity_log?select=ts,actor,action,payload"
                  f"&entity_id=eq.{scid}&order=ts.desc&limit=200") or []
        for r in (rows if isinstance(rows, list) else []):
            ev = _clog_from_activity(r)
            if ev:
                _add(r.get("ts"), ev[0], ev[1], ev[2], r.get("actor") or "", ev[3])
    except Exception:  # noqa: BLE001
        pass

    # 3a — upload-gate list audits
    try:
        rows = sb("GET", "list_upload_qa_runs?select=rows_in,rows_uploaded,verdict,run_at"
                  f"&campaign_id=eq.{scid}&order=run_at.desc&limit=40") or []
        for r in (rows if isinstance(rows, list) else []):
            n_in = _sc_int(r.get("rows_in"))
            n_up = _sc_int(r.get("rows_uploaded"))
            verdict = str(r.get("verdict") or "").strip()
            det = f"{n_up:,} of {n_in:,} leads passed the gate" if n_in else ""
            title = "Audited a list before upload" + (f" — {verdict}" if verdict else "")
            _add(r.get("run_at"), "audit", title, det, "upload-gate", "List audit")
    except Exception:  # noqa: BLE001
        pass

    # 3b — reviewed upload-gate runs
    try:
        rows = sb("GET", "qa_gate_runs?select=campaign_name,run,created_at"
                  f"&campaign_id=eq.{scid}&order=created_at.desc&limit=40") or []
        for r in (rows if isinstance(rows, list) else []):
            run = r.get("run") if isinstance(r.get("run"), dict) else {}
            n_in = _sc_int(run.get("rows_in"))
            det = f"{n_in:,} leads reviewed" if n_in else ""
            _add(r.get("created_at"), "audit", "Ran the upload-gate list review",
                 det, "upload-gate", "List audit")
    except Exception:  # noqa: BLE001
        pass

    # 4 — new positives + meetings booked, from the reply archive
    try:
        cats = ",".join(quote(f'"{c}"') for c in _CLOG_ALL_POS)
        rows = sb("GET", "replies?select=email,category,replied_at,reply_subject,raw"
                  f"&smartlead_campaign_id=eq.{scid}&category=in.({cats})"
                  "&order=replied_at.desc&limit=200") or []
        rows = rows if isinstance(rows, list) else []
        # one cheap name lookup for every replier without an invitee_name
        need = sorted({(r.get("email") or "").strip().lower() for r in rows
                       if (r.get("email") or "").strip()})
        people: dict = {}
        for i in range(0, len(need), 100):
            chunk = ",".join(quote(f'"{e}"') for e in need[i:i + 100])
            pr = sb("GET", "people?select=email,first_name,last_name,title,company_domain"
                    f"&email=in.({chunk})") or []
            for p in (pr if isinstance(pr, list) else []):
                people[(p.get("email") or "").strip().lower()] = p

        def _name(r):
            raw = r.get("raw") if isinstance(r.get("raw"), dict) else {}
            if (raw.get("invitee_name") or "").strip():
                return raw["invitee_name"].strip()
            em = (r.get("email") or "").strip().lower()
            p = people.get(em) or {}
            nm = " ".join(x for x in [(p.get("first_name") or "").strip(),
                                      (p.get("last_name") or "").strip()] if x).strip()
            if nm:
                return nm
            local = em.split("@", 1)[0].replace(".", " ").replace("_", " ").strip()
            return local.title() if local else "A lead"

        def _company(r):
            em = (r.get("email") or "").strip().lower()
            p = people.get(em) or {}
            dom = (p.get("company_domain") or "").strip()
            if not dom and "@" in em:
                dom = em.split("@", 1)[1]
            return dom

        for r in rows:
            cat = str(r.get("category") or "")
            nm = _name(r)
            comp = _company(r)
            p = people.get((r.get("email") or "").strip().lower()) or {}
            title_role = (p.get("title") or "").strip()
            if cat == "Call Booked":
                bits = [b for b in [title_role, comp] if b]
                _add(r.get("replied_at"), "booked", f"Meeting booked with {nm}",
                     " · ".join(bits), "", "Booked")
            else:
                bits = [b for b in [title_role, comp] if b]
                _add(r.get("replied_at"), "positive", f"New positive reply from {nm}",
                     " · ".join(bits), "", cat)
    except Exception:  # noqa: BLE001
        pass

    def _ts(e):
        s = str(e.get("at") or "").strip().replace(" ", "T")
        if s and not s.endswith("Z") and "+" not in s[10:] and "-" not in s[10:]:
            s += "+00:00"
        try:
            from datetime import datetime
            return datetime.fromisoformat(s.replace("Z", "+00:00")).timestamp()
        except Exception:  # noqa: BLE001
            return 0.0

    events.sort(key=_ts, reverse=True)
    try:
        limit = max(1, min(500, int(limit or 200)))
    except (TypeError, ValueError):
        limit = 200
    return 200, {"ok": True, "campaign_id": n, "count": len(events),
                 "truncated": len(events) > limit, "events": events[:limit]}


# ── Notion Client Tasks — one helper, factored from sync_booked.py's REST ────
# Data source 2776e755-98d9-806a-88af-000b091e215e ("Client Tasks"). Property
# keys are exact and fussy: `Client ` carries a TRAILING SPACE, Status is a
# status property, Due Date is a date. Notion-Version 2025-09-03 is the one
# that accepts a data_source_id parent (memory notion-api-key-rest-recipe).
NOTION_API_BASE = "https://api.notion.com/v1"
NOTION_TASKS_VERSION = "2025-09-03"
NOTION_CLIENT_TASKS_DS = "2776e755-98d9-806a-88af-000b091e215e"
# Touchpoint's select option is spelled "Touchpoint PPC" — a plain "Touchpoint"
# silently creates a SECOND option nobody filters on.
_NOTION_CLIENT_ALIASES = {"touchpoint": "Touchpoint PPC"}


def _notion_task_headers() -> dict:
    key = KEYS.get("NOTION_API_KEY") or os.environ.get("NOTION_API_KEY") or ""
    if not key:
        raise RuntimeError("NOTION_API_KEY is not configured on this host")
    return {"Authorization": f"Bearer {key}", "Notion-Version": NOTION_TASKS_VERSION}


def notion_client_option(client: str) -> str:
    c = str(client or "").strip() or "MISC."
    return _NOTION_CLIENT_ALIASES.get(c.lower(), c)


def _working_days_from(days: int) -> str:
    """today + N WORKING days (Mon-Fri), ISO date."""
    from datetime import date, timedelta
    d = date.today()
    left = max(0, int(days or 0))
    while left > 0:
        d += timedelta(days=1)
        if d.weekday() < 5:
            left -= 1
    return d.isoformat()


def _notion_task_blocks(body: str) -> list:
    """Markdown-ish body -> Notion blocks. `## X` becomes a heading, `- x` a
    bullet, everything else a paragraph. Blank lines are dropped."""
    out = []
    for raw in str(body or "").splitlines():
        line = raw.rstrip()
        if not line.strip():
            continue
        if line.startswith("## "):
            out.append({"object": "block", "type": "heading_2",
                        "heading_2": {"rich_text": [{"type": "text",
                                                     "text": {"content": line[3:][:1900]}}]}})
        elif line.lstrip().startswith("- "):
            out.append({"object": "block", "type": "bulleted_list_item",
                        "bulleted_list_item": {"rich_text": [{"type": "text",
                                                              "text": {"content": line.lstrip()[2:][:1900]}}]}})
        else:
            out.append({"object": "block", "type": "paragraph",
                        "paragraph": {"rich_text": [{"type": "text",
                                                     "text": {"content": line[:1900]}}]}})
    return out[:90]


def notion_open_task_with_marker(marker: str) -> str:
    """The URL of an OPEN Client Task whose title carries `marker`, or "".
    The dedupe gate: one open task per (campaign, issue kind), never two."""
    data = http_json("POST", f"{NOTION_API_BASE}/data_sources/{NOTION_CLIENT_TASKS_DS}/query",
                     _notion_task_headers(),
                     {"page_size": 25,
                      "filter": {"and": [
                          {"property": "Name", "title": {"contains": marker}},
                          {"property": "Status", "status": {"does_not_equal": "Done"}}]}})
    if not isinstance(data, dict) or data.get("object") == "error":
        raise RuntimeError(f"Notion query failed: {str(data)[:250]}")
    for r in (data.get("results") or []):
        if isinstance(r, dict) and not r.get("archived"):
            return str(r.get("url") or r.get("id") or "")
    return ""


def notion_create_task(title: str, client: str, body: str, priority: str,
                       due_days: int = 2, marker: str = "") -> dict:
    """Create ONE Client Task. Returns {ok, url, id, skipped, reason}.

    `marker` (e.g. "[auto-mover:3445988:flap]") is appended to the title and is
    the dedupe key: if an open task already carries it, nothing is created."""
    title = str(title or "").strip()[:180]
    if marker:
        if marker not in title:
            title = f"{title} {marker}"
        try:
            existing = notion_open_task_with_marker(marker)
        except Exception as e:  # noqa: BLE001 — a query blip must not double-file
            return {"ok": False, "skipped": True, "reason": f"dedupe check failed: {str(e)[:200]}"}
        if existing:
            return {"ok": True, "skipped": True, "reason": "already open",
                    "url": existing}
    props = {
        "Name": {"title": [{"text": {"content": title}}]},
        "Client ": {"select": {"name": notion_client_option(client)}},
        "Status": {"status": {"name": "Not started"}},
        "Due Date": {"date": {"start": _working_days_from(due_days)}},
    }
    if priority:
        props["Priority"] = {"select": {"name": str(priority)}}
    data = http_json("POST", f"{NOTION_API_BASE}/pages", _notion_task_headers(),
                     {"parent": {"type": "data_source_id",
                                 "data_source_id": NOTION_CLIENT_TASKS_DS},
                      "properties": props,
                      "children": _notion_task_blocks(body)})
    if not isinstance(data, dict) or data.get("object") == "error":
        raise RuntimeError(f"Notion page create failed: {str(data)[:250]}")
    return {"ok": True, "skipped": False, "id": data.get("id") or "",
            "url": data.get("url") or ""}


# ── Variant Auto-Mover — the runner ─────────────────────────────────────────
# THE ONE DESIGN RULE: this runner contains NO judging logic. Per campaign it
# calls server._cockpit_messaging(cid) and build_notifications.pill_best_opener(m)
# and does exactly what the returned evidence says. It never re-implements a
# bar, a metric, a winner pick or a share. If the engine changes, the mover
# follows on the next tick with zero code change here.
AUTO_MOVER_ACTOR = "auto-mover@navreo.ai"
_AUTO_MOVE_LOCK = threading.Lock()
_AM_STEP = 1                     # the engine only ever judges the opener step
_AM_MAX_MOVES_RUN = 10           # R8
_AM_MAX_MOVES_DAY = 60           # R8
_AM_SPACING_S = 20.0             # R8
_AM_MAX_CONSEC_FAILS = 2         # R8 — abort the run
_AM_BREAKER_FAILS = 3            # R8 — trip the breaker
_AM_HUMAN_OWNED_DAYS = 14        # R4
_AM_FLAP_HOURS = 48              # R2
_AM_THIN_EVIDENCE_MIN = 2        # R3 — a ledger FLAG only, never a gate
_AM_POLL_TIMEOUT_S = 240.0
# R12: the hard-coded allowlist. Mode -> (door action, confirm token). Anything
# the engine could ever return that is not one of these three is refused.
_AM_ACTION_BY_MODE = {"full": ("scale_winner", "SCALE"),
                      "partial": ("back_winner", "BACK"),
                      "tie": ("split_leaders", "SPLITLEADERS")}


def _am_iso() -> str:
    return _dtmod.datetime.now(_dtmod.timezone.utc).isoformat()


def _am_breaker_tripped() -> dict:
    b = _ui_prefs(force=True).get("auto_mover_breaker") or {}
    return b if isinstance(b, dict) and b.get("tripped") else {}


def _am_trip_breaker(reason: str) -> dict:
    """R1/R8: kill the whole thing — breaker tripped AND the global switch off.
    Clears only by hand on Settings -> General."""
    blob = {"tripped": True, "reason": str(reason)[:250], "at": _am_iso()}
    try:
        _ui_prefs_set({"auto_mover_breaker": blob, "auto_mover_enabled": False})
    except Exception as e:  # noqa: BLE001 — a write miss must still stop the run
        print(f"[auto-mover] breaker write failed: {e}", file=sys.stderr)
    return blob


def _am_meta(cid: str) -> dict:
    """{name, client, workspace, status} for one campaign, or {}."""
    try:
        rows = sb("GET", f"campaign_scorecard?smartlead_campaign_id=eq.{cid}"
                         "&select=name,client,workspace,status&limit=1") or []
    except Exception:  # noqa: BLE001
        rows = []
    return rows[0] if rows else {}


def _am_splits(cid: str) -> dict:
    """{label: pct} for the opener step, FRESH from Smartlead (never a cache).
    Pure transport: it reads the distribution, it never decides one.

    A NULL `variant_distribution_percentage` is NOT 0. Smartlead serves null
    for a share that was never set explicitly, and those variants really split
    the REMAINING percentage evenly between them (its observed behaviour, the
    same rule `even_split` and the write door already rely on). Reading a null
    as 0 made the ledger record a live 50/50 step as `{B: 0, C: 0}` (campaign
    3343012, 2 Sep 2026) — a "before" that says both versions were off when
    both were sending half the traffic. That is only the recorded/displayed
    number — the door itself was already null-safe, because `_find_step` calls
    `_normalise_default_split` before any mutation — but the wrong number then
    feeds the General page, the Change Logs tab, and R4's "did a human change
    the split?" comparison, so it must be the factual share. Normalise here
    with the SAME helper the door uses; an explicit 0 (human-off) is left at 0.
    """
    data = _smartlead_json("GET", f"/campaigns/{cid}/sequences", timeout=20, attempts=2)
    steps = data if isinstance(data, list) else (data or {}).get("data") or []
    out: dict = {}
    for s in steps:
        if not isinstance(s, dict) or str(s.get("seq_number")) != str(_AM_STEP):
            continue
        try:
            _normalise_default_split(s)   # null share -> its factual even part
        except Exception:  # noqa: BLE001 — an odd payload still reads raw below
            pass
        for v in (s.get("sequence_variants") or []):
            lab = v.get("variant_label")
            if lab is None or v.get("is_deleted"):
                continue
            try:
                out[str(lab)] = int(v.get("variant_distribution_percentage") or 0)
            except (TypeError, ValueError):
                out[str(lab)] = 0
    return out


def _am_counters(cid: str) -> dict:
    """{"<step>|<label>": {sent, replies, positives}} for EVERY version, fresh
    from variant-statistics. The R1 evidence: compared before vs after a move."""
    data = _smartlead_json("GET", f"/campaigns/{cid}/variant-statistics",
                           timeout=20, attempts=2)
    rows = data.get("data") if isinstance(data, dict) else None
    out: dict = {}
    for r in (rows or []):
        if not isinstance(r, dict) or r.get("seq_variant_id") is None:
            continue
        key = f"{r.get('seq_number')}|{r.get('variant_label')}"
        out[key] = {"sent": int(r.get("sent_count") or 0),
                    "replies": int(r.get("reply_count") or 0),
                    "positives": int(r.get("positive_reply_count") or 0)}
    return out


def _am_counter_drop(before: dict, after: dict) -> str:
    """R1: "" when every version held its ground, else the offending version."""
    for key, b in (before or {}).items():
        a = (after or {}).get(key)
        if a is None:
            return f"{key}: version disappeared after the save"
        for metric in ("sent", "replies", "positives"):
            if int(a.get(metric) or 0) < int(b.get(metric) or 0):
                return (f"{key}: {metric} {b.get(metric)} -> {a.get(metric)}")
    return ""


def _am_candidates() -> list:
    """Campaign ids carrying a LIVE 'move traffic to the winner' recommendation:
    the union of open scale_winner notification rows and live scale-winner
    cards. Candidates ONLY — the fresh engine call is the verdict (R7)."""
    out: dict = {}
    try:
        rows = sb("GET", "optimiser_notifications?action_type=eq.scale_winner"
                         "&status=in.(new,acknowledged,approved)"
                         "&select=id,campaign_id,status,created_at"
                         "&order=created_at.desc&limit=400") or []
    except Exception:  # noqa: BLE001
        rows = []
    for r in (rows if isinstance(rows, list) else []):
        cid = str(r.get("campaign_id") or "")
        if cid and cid not in out:
            out[cid] = {"campaign_id": cid, "notification_id": str(r.get("id") or ""),
                        "source": "notification"}
    try:
        cards = sb("GET", "campaign_insights?insight_key=eq.scale-winner"
                          "&status=eq.live&select=scope&limit=400") or []
    except Exception:  # noqa: BLE001
        cards = []
    for r in (cards if isinstance(cards, list) else []):
        cid = str(r.get("scope") or "")
        if cid and cid not in out:
            out[cid] = {"campaign_id": cid, "notification_id": "", "source": "card"}
    return list(out.values())


def _am_dismissed(cid: str) -> bool:
    """R5: a dismissed notification row, or a `dismiss` assignment on the
    campaign's scale-winner key, bars the mover for the life of that key."""
    from urllib.parse import quote
    try:
        rows = sb("GET", "optimiser_notifications?action_type=eq.scale_winner"
                         f"&campaign_id=eq.{quote(str(cid), safe='')}"
                         "&status=eq.dismissed&select=id&limit=1") or []
        if rows:
            return True
    except Exception:  # noqa: BLE001
        pass
    key = f"{cid}::scale-winner"
    try:
        rows = sb("GET", "cockpit_action_assignments?action_key=eq."
                  + quote(key, safe="") + "&select=state&limit=1") or []
    except Exception:  # noqa: BLE001
        return False
    return bool(rows) and str(rows[0].get("state") or "").lower() == "dismiss"


def _am_is_active(cid: str) -> bool:
    """R6: fresh Smartlead status must read ACTIVE. Same live-status helper
    /api/cockpit/live-status serves from."""
    try:
        payload = _COCKPIT_LIVE_STATUS_SWR.get(str(cid))
    except Exception:  # noqa: BLE001 — unknown status is never ACTIVE
        return False
    rec = ((payload or {}).get("campaigns") or {}).get(str(cid)) or {}
    return str(rec.get("status") or "").upper() == "ACTIVE"


def _am_moves_today() -> int:
    """R8 daily cap — today's ledger rows that actually moved traffic."""
    day = _dtmod.datetime.now(_dtmod.timezone.utc).date().isoformat()
    try:
        rows = sb("GET", "auto_mover_moves?outcome=eq.moved"
                         f"&created_at=gte.{day}T00:00:00&select=id&limit=200") or []
    except Exception:  # noqa: BLE001 — an unreadable ledger is treated as full
        return _AM_MAX_MOVES_DAY
    if not isinstance(rows, list):   # PostgREST error dict — unreadable, so full
        return _AM_MAX_MOVES_DAY
    return len(rows)


def _am_recent_ledger(cid: str, step: int, hours: float) -> dict:
    """The newest ledger row for this campaign+step inside `hours`, or {}."""
    from urllib.parse import quote
    # The offset in an aware isoformat() is "+00:00"; a bare "+" in a query
    # string decodes to a SPACE, so PostgREST hands Postgres "…T15:06:09 00:00"
    # and it answers 22007 "invalid input syntax for timestamp". quote() it.
    since = quote((_dtmod.datetime.now(_dtmod.timezone.utc)
                   - _dtmod.timedelta(hours=hours)).isoformat(), safe="")
    try:
        rows = sb("GET", "auto_mover_moves?campaign_id=eq." + quote(str(cid), safe="")
                  + f"&step=eq.{int(step)}&outcome=eq.moved&created_at=gte.{since}"
                    "&select=id,winner,mode,pcts_after,created_at"
                    "&order=created_at.desc&limit=1") or []
    except Exception:  # noqa: BLE001
        rows = []
    # A PostgREST error comes back as a truthy DICT, not a list. Indexing it
    # raises KeyError(0) — which used to kill the whole run on candidate #1,
    # because this call site is not inside a try. Shape-check, never assume.
    return rows[0] if isinstance(rows, list) and rows else {}


def _am_human_owned(cid: str, step: int, splits: dict) -> dict:
    """R4 "last human writer wins": if the step's CURRENT distribution differs
    from what the mover itself last wrote (and it wrote inside the 14-day
    window), a human has taken the wheel — skip and raise it once."""
    row = _am_recent_ledger(cid, step, _AM_HUMAN_OWNED_DAYS * 24)
    if not row:
        return {}
    ours = row.get("pcts_after")
    if not isinstance(ours, dict) or not ours:
        return {}
    now = {str(k): int(v or 0) for k, v in (splits or {}).items()}
    mine = {str(k): int(v or 0) for k, v in ours.items()}
    if now == mine:
        return {}
    return {"since": row.get("created_at"), "ours": mine, "theirs": now}


def _am_ledger(row: dict) -> None:
    try:
        sb("POST", "auto_mover_moves", row, prefer="return=minimal")
    except Exception as e:  # noqa: BLE001 — a ledger miss must be loud, not fatal
        print(f"[auto-mover] ledger write failed: {e}", file=sys.stderr)


def _am_notion(cid: str, kind: str, title: str, client: str, body: str,
               priority: str) -> str:
    """File ONE Notion Client Task per (campaign, kind) while one is open."""
    marker = f"[auto-mover:{cid}:{kind}]"
    try:
        res = notion_create_task(title=title, client=client or "MISC.", body=body,
                                 priority=priority, due_days=2, marker=marker)
        return str(res.get("url") or "")
    except Exception as e:  # noqa: BLE001 — Notion must never sink a run
        print(f"[auto-mover] notion task failed ({marker}): {e}", file=sys.stderr)
        return ""


def _am_issue_body(cid: str, name: str, what: str, why: str, how: str) -> str:
    return ("## What\n" + what
            + "\n\n## Why\n" + why
            + "\n\n## Where\n"
            + f"- Campaign: {name or cid} (Smartlead id {cid})\n"
            + f"- Smartlead: https://app.smartlead.ai/app/email-campaign/{cid}/analytics\n"
            + f"- Tool task page: {_am_base_url()}/app/optimise.html?c={cid}\n"
            + f"- Auto-mover log: {_am_base_url()}/app/general.html\n"
            + "\n## How\n" + how)


def _am_base_url() -> str:
    return os.environ.get("SIGNALS_BASE_URL", "https://app.navreo.ai").rstrip("/")


def _am_poll(job_id: str) -> tuple:
    """Block until the queued door write resolves. (ok, status, body)."""
    deadline = time.time() + _AM_POLL_TIMEOUT_S
    body: dict = {}
    while time.time() < deadline:
        code, out = api_campaign_variant_action_status(job_id)
        if code == 404:
            return False, "unknown", {"message": "job expired before it was read"}
        if str(out.get("status")) != "running":
            body = out.get("body") if isinstance(out.get("body"), dict) else {}
            sc = out.get("status_code")
            ok = bool(body.get("ok")) and isinstance(sc, int) and sc // 100 == 2
            return ok, str(out.get("status")), body
        time.sleep(2.0)
    return False, "timeout", {"message": "the queued write did not resolve in time"}


def auto_move_run(campaign_id=None, max_moves=None,
                  actor: str = AUTO_MOVER_ACTOR) -> dict:
    """One auto-mover tick. Returns
    {ok, started, disposition: [{campaign_id, client, action, before, after,
                                 outcome, reason}], …}.

    Order of gates, all of them cheap-before-expensive:
      lock (R9) -> global switch + breaker (R11/R1) -> candidates ->
      per-campaign switch (R11) -> dismissed (R5) -> ACTIVE (R6) ->
      fresh engine verdict (R2/R7) -> human-owned (R4) -> fresh re-verdict
      right before the enqueue (R9) -> door -> counters (R1) -> ledger +
      task states + surfaces (R13) -> issues (R14) -> caps (R8).
    """
    if not _AUTO_MOVE_LOCK.acquire(blocking=False):
        return {"ok": True, "started": False, "busy": True, "reason": "already_running",
                "disposition": []}
    try:
        if _CRON_LOCK.locked():          # R9: never race the batch pull
            return {"ok": True, "started": False, "busy": True,
                    "reason": "cron_running", "disposition": []}
        one = str(campaign_id).strip() if campaign_id not in (None, "") else ""
        if not auto_mover_enabled(force=True):     # R11: fresh, every run
            # Nothing can move while the global switch is off — that is the
            # hard kill and it always wins. A single-campaign PROBE still gets
            # the precise reason it would have been skipped for, because
            # "global_off" alone hides an explicit per-campaign Off. Reporting
            # only: no candidate is read, no Smartlead call is made either way.
            reason = "global_off"
            mode_probe = None
            if one:
                mode_probe = auto_mover_campaign_mode(one)
                if mode_probe == "off":
                    reason = "per_campaign_off"
            return {"ok": True, "started": False, "reason": reason,
                    "global_off": True, "campaign_id": one or None,
                    "campaign_mode": mode_probe, "disposition": []}
        breaker = _am_breaker_tripped()
        if breaker:
            return {"ok": True, "started": False, "reason": "breaker_tripped",
                    "breaker": breaker, "disposition": []}

        cands = ([{"campaign_id": one, "notification_id": "", "source": "explicit"}]
                 if one else _am_candidates())
        try:
            cap_run = int(max_moves) if max_moves not in (None, "") else _AM_MAX_MOVES_RUN
        except (TypeError, ValueError):
            cap_run = _AM_MAX_MOVES_RUN
        cap_run = max(0, cap_run)

        run_job = None
        try:
            run_job = _new_job("auto_mover", f"Checking {len(cands)} campaigns for the best email",
                               None, auto_remove=True)
            _job_started(run_job)
        except Exception:  # noqa: BLE001 — the panel mirror never blocks the run
            run_job = None

        disposition: list = []
        moved = consec_fail = save_fail = 0
        day_used = _am_moves_today()
        stop_reason = ""

        for cand in cands:
            cid = str(cand["campaign_id"])
            meta = _am_meta(cid)
            client = meta.get("client") or ""
            name = meta.get("name") or f"Campaign {cid}"

            def _say(outcome, reason, **extra):
                disposition.append({"campaign_id": cid, "client": client,
                                    "campaign": name, "action": extra.pop("action", None),
                                    "before": extra.pop("before", None),
                                    "after": extra.pop("after", None),
                                    "outcome": outcome, "reason": reason, **extra})

            if moved >= cap_run:
                stop_reason = "run_cap"
                _say("skipped", "run_cap")
                continue
            if day_used + moved >= _AM_MAX_MOVES_DAY:
                stop_reason = "daily_cap"
                _say("skipped", "daily_cap")
                continue

            mode_pref = auto_mover_campaign_mode(cid)      # R11 — off beats on
            if mode_pref == "off":
                _say("skipped", "per_campaign_off")
                continue
            if mode_pref != "on" and not auto_mover_enabled(force=True):
                _say("skipped", "global_off")
                continue
            if _am_dismissed(cid):                          # R5
                _say("skipped", "dismissed")
                continue
            if not _am_is_active(cid):                      # R6
                _say("skipped", "not_active")
                continue

            # ── THE ALGORITHM. Imported lazily: build_notifications imports us.
            import build_notifications as _bn
            # One sick campaign must never take the sweep down with it: read
            # the payload and the verdict defensively and skip just this one.
            try:
                m = _cockpit_messaging(cid)
                lab, has_scale, ev = _bn.pill_best_opener(m) if (
                    isinstance(m, dict) and not m.get("degraded")) else (None, False, None)
            except Exception as e:  # noqa: BLE001
                _say("skipped", f"verdict_unavailable:{str(e)[:120]}")
                continue
            if not isinstance(m, dict) or m.get("degraded"):
                _say("skipped", "messaging_unavailable")
                continue
            if not has_scale or ev is None:                 # R2/R7
                _say("skipped", "no_move")
                continue
            verdict = str(ev.get("mode") or "")
            if verdict not in _AM_ACTION_BY_MODE:           # R12
                _say("skipped", f"unsupported_mode:{verdict}")
                continue
            if verdict != "tie" and not lab:                # input validation
                _say("skipped", "winner_label_missing")
                continue

            try:
                before = _am_splits(cid)
            except Exception as e:  # noqa: BLE001
                _say("skipped", f"splits_unreadable:{str(e)[:120]}")
                continue

            owned = _am_human_owned(cid, _AM_STEP, before)  # R4
            if owned:
                url = _am_notion(
                    cid, "human_owned",
                    f"Auto-mover paused on {name}: someone set the split by hand",
                    client,
                    _am_issue_body(
                        cid, name,
                        "Decide whether the auto-mover should keep managing Email 1 on "
                        "this campaign, then either leave it (it stays paused for 14 "
                        "days) or set the campaign switch back to inherit.",
                        f"The mover last wrote {owned['ours']} on {owned['since']}. "
                        f"The step now reads {owned['theirs']}, so a human changed it "
                        "afterwards. Last human writer wins: the mover has stood down "
                        "on this step rather than overwrite that decision.",
                        "- Look at the campaign's Messaging tab and decide the intended split.\n"
                        "- If the hand-set split should stand, leave it - the mover stays off "
                        "this step for 14 days.\n"
                        "- If the mover should take over again, set the split back or flip the "
                        "campaign switch on the campaign page."),
                    "Medium")
                _am_ledger({"campaign_id": cid, "step": _AM_STEP, "action": None,
                            "winner": lab, "mode": verdict, "via": ev.get("via"),
                            "pcts_before": before, "evidence": ev, "actor": actor,
                            "outcome": "skipped", "issue_kind": "human_owned",
                            "notion_task_url": url or None})
                _say("skipped", "human_owned", notion_task_url=url or None, before=before)
                continue

            # R9: the freshest possible verdict, right before the enqueue. If
            # the traffic already sits where the engine wants it, has_scale has
            # gone False on its own - that IS "already at target", derived from
            # the engine, never from arithmetic in here.
            try:
                m2 = _cockpit_messaging(cid)
                lab, has_scale, ev = _bn.pill_best_opener(m2) if (
                    isinstance(m2, dict) and not m2.get("degraded")) else (None, False, None)
            except Exception as e:  # noqa: BLE001 — skip this one, not the sweep
                _say("skipped", f"verdict_unavailable:{str(e)[:120]}", before=before)
                continue
            if not isinstance(m2, dict) or m2.get("degraded"):
                _say("skipped", "messaging_unavailable")
                continue
            if not has_scale or ev is None:
                if cand.get("notification_id"):
                    try:
                        update_notification_status(cand["notification_id"], "actioned")
                    except Exception:  # noqa: BLE001
                        pass
                try:
                    cockpit_set_assignment({"action_key": f"{cid}::scale-winner",
                                            "campaign_id": cid,
                                            "insight_key": "scale-winner",
                                            "state": "done"}, actor)
                except Exception:  # noqa: BLE001
                    pass
                _say("noop", "already_at_target", before=before, after=before)
                continue
            verdict = str(ev.get("mode") or "")
            if verdict not in _AM_ACTION_BY_MODE:
                _say("skipped", f"unsupported_mode:{verdict}")
                continue
            if verdict != "tie" and not lab:
                _say("skipped", "winner_label_missing")
                continue
            if not auto_mover_enabled(force=True) and mode_pref != "on":  # R11
                _say("skipped", "global_off")
                continue
            if _am_breaker_tripped():
                stop_reason = "breaker_tripped"
                _say("skipped", "breaker_tripped")
                break

            action, confirm = _AM_ACTION_BY_MODE[verdict]
            payload = {"action": action, "email": _AM_STEP, "confirm": confirm}
            if verdict == "full":
                payload["variant_label"] = lab
            elif verdict == "partial":
                payload["variant_label"] = lab
                payload["laggards"] = list(ev.get("laggards") or [])
            else:
                payload["leaders"] = list(ev.get("leaders") or [])
                payload["laggards"] = list(ev.get("laggards") or [])

            # R2: a reversal on the same step inside 48h still runs — it is
            # flagged, not blocked ("react to the latest data all the time").
            prev = _am_recent_ledger(cid, _AM_STEP, _AM_FLAP_HOURS)
            flap = bool(prev and (prev.get("winner") or None) != (lab or None))

            move_job = None
            try:
                _am_mode = str(ev.get("mode") or "")
                if not lab:
                    move_label = f"Two versions tied - split Email {_AM_STEP} evenly - {name}"
                elif _am_mode == "partial":
                    move_label = f"Sent most of Email {_AM_STEP} to the best version ({lab}) - {name}"
                else:
                    move_label = f"Sent all of Email {_AM_STEP} to the best version ({lab}) - {name}"
                move_job = _new_job("auto_mover_move", move_label, cid)
                _job_started(move_job)
            except Exception:  # noqa: BLE001
                move_job = None

            try:
                counters_before = _am_counters(cid)
            except Exception:  # noqa: BLE001 — no baseline means no R1 proof
                if move_job:
                    _job_finished(move_job, "failed", "counter snapshot failed")
                _say("skipped", "counters_unreadable", before=before)
                continue

            code, resp = api_campaign_variant_action_async(cid, payload)
            if code != 202 or not resp.get("job"):
                save_fail += 1
                consec_fail += 1
                if move_job:
                    _job_finished(move_job, "failed", str(resp.get("message") or "")[:200])
                _am_ledger({"campaign_id": cid, "step": _AM_STEP, "action": action,
                            "winner": lab, "mode": verdict, "via": ev.get("via"),
                            "laggards": list(ev.get("laggards") or []),
                            "leaders": list(ev.get("leaders") or []),
                            "dropped": list(ev.get("dropped") or []),
                            "pcts_before": before, "counters_before": counters_before,
                            "evidence": ev, "actor": actor, "outcome": "failed",
                            "issue_kind": "enqueue_rejected"})
                _say("failed", str(resp.get("message") or "enqueue rejected")[:200],
                     action=action, before=before)
            else:
                ok, jstatus, jbody = _am_poll(resp["job"])
                if not ok:
                    save_fail += 1
                    consec_fail += 1
                    why = str(jbody.get("message") or jstatus)[:200]
                    if move_job:
                        _job_finished(move_job, "failed", why)
                    url = _am_notion(
                        cid, "save_failed",
                        f"Auto-mover could not move Email {_AM_STEP} on {name}",
                        client,
                        _am_issue_body(cid, name,
                                       "Apply the recommended split by hand on the "
                                       "campaign's Messaging tab, or say why it should "
                                       "not be applied.",
                                       f"The mover asked for {action} and the save did "
                                       f"not land: {why}",
                                       "- Open the campaign's Messaging tab and use the "
                                       "1-click button there.\n- If it fails again, the "
                                       "problem is upstream at Smartlead, not the split."),
                        "High")
                    _am_ledger({"campaign_id": cid, "step": _AM_STEP, "action": action,
                                "winner": lab, "mode": verdict, "via": ev.get("via"),
                                "laggards": list(ev.get("laggards") or []),
                                "leaders": list(ev.get("leaders") or []),
                                "dropped": list(ev.get("dropped") or []),
                                "pcts_before": before, "counters_before": counters_before,
                                "evidence": ev, "actor": actor, "outcome": "failed",
                                "issue_kind": "save_failed", "notion_task_url": url or None})
                    _say("failed", why, action=action, before=before,
                         notion_task_url=url or None)
                else:
                    consec_fail = 0
                    moved += 1
                    try:
                        after = _am_splits(cid)
                    except Exception:  # noqa: BLE001
                        after = {}
                    try:
                        counters_after = _am_counters(cid)
                    except Exception:  # noqa: BLE001
                        counters_after = {}
                    drop = _am_counter_drop(counters_before, counters_after) \
                        if counters_after else ""
                    thin = int(ev.get("positives") or 0) < _AM_THIN_EVIDENCE_MIN
                    issue_kind = ("counter_drop" if drop else
                                  "flap" if flap else
                                  "thin_evidence" if thin else None)
                    notion_url = ""
                    if drop:
                        b = _am_trip_breaker(f"counter drop on campaign {cid} - {drop}")
                        notion_url = _am_notion(
                            cid, "counter_drop",
                            f"Auto-mover STOPPED: a counter dropped on {name}",
                            client,
                            _am_issue_body(cid, name,
                                           "Check the version counters on this campaign, "
                                           "then decide whether the auto-mover can be "
                                           "switched back on.",
                                           f"After the mover's {action} save, {drop}. The "
                                           "whole feedback loop depends on those counters "
                                           "surviving our own writes, so the breaker has "
                                           "tripped and the global switch is OFF.",
                                           "- Compare the version table against Smartlead.\n"
                                           "- The breaker clears only by hand on Settings "
                                           "-> General."),
                            "High")
                    elif flap:
                        notion_url = _am_notion(
                            cid, "flap",
                            f"Auto-mover reversed itself on {name}",
                            client,
                            _am_issue_body(cid, name,
                                           "Sanity-check the version data on this campaign - "
                                           "the winner keeps changing.",
                                           f"The mover last crowned {prev.get('winner')} on "
                                           f"{prev.get('created_at')} and has now moved to "
                                           f"{lab or 'an even split'} within "
                                           f"{_AM_FLAP_HOURS} hours. That is allowed (the "
                                           "mover always follows the latest data) but a "
                                           "rapid reversal usually means the versions are "
                                           "too close to separate.",
                                           "- Look at the Messaging tab: are the versions "
                                           "genuinely neck and neck?\n- If so, consider "
                                           "leaving the split alone until more data lands."),
                            "Medium")
                    if move_job:
                        _job_finished(move_job, "done")
                    _am_ledger({"campaign_id": cid, "step": _AM_STEP, "action": action,
                                "winner": lab, "mode": verdict, "via": ev.get("via"),
                                "laggards": list(ev.get("laggards") or []),
                                "leaders": list(ev.get("leaders") or []),
                                "dropped": list(ev.get("dropped") or []),
                                "pcts_before": before, "pcts_after": after,
                                "counters_before": counters_before,
                                "counters_after": counters_after,
                                "notification_id": cand.get("notification_id") or None,
                                "evidence": ev, "actor": actor, "outcome": "moved",
                                "issue_kind": issue_kind,
                                "notion_task_url": notion_url or None})
                    try:
                        log_activity("/api/cron/auto-move",
                                     payload={"campaign_id": cid, "action": action,
                                              "winner": lab, "mode": verdict,
                                              "before": before, "after": after,
                                              "issue_kind": issue_kind},
                                     actor=actor, action="auto_move", entity="campaigns")
                    except Exception:  # noqa: BLE001
                        pass
                    if cand.get("notification_id"):          # R13
                        try:
                            update_notification_status(cand["notification_id"], "actioned")
                        except Exception:  # noqa: BLE001
                            pass
                    try:
                        cockpit_set_assignment({"action_key": f"{cid}::scale-winner",
                                                "campaign_id": cid,
                                                "insight_key": "scale-winner",
                                                "state": "done"}, actor)
                    except Exception:  # noqa: BLE001
                        pass
                    _say("moved", issue_kind or "ok", action=action,
                         before=before, after=after, flap=flap,
                         thin_evidence=thin,
                         notion_task_url=notion_url or None)
                    if drop:
                        stop_reason = "breaker_tripped"
                        break

            if save_fail >= _AM_BREAKER_FAILS:               # R8
                _am_trip_breaker(f"{save_fail} failed saves in one run")
                stop_reason = "breaker_tripped"
                break
            if consec_fail >= _AM_MAX_CONSEC_FAILS:          # R8
                stop_reason = "consecutive_failures"
                break
            if moved < cap_run and moved:
                time.sleep(_AM_SPACING_S)                    # R8 spacing

        if run_job:
            try:
                with JOBS_LOCK:
                    run_job["counts"] = {"reviewed": len(cands), "moved": moved}
                _job_finished(run_job, "done")
            except Exception:  # noqa: BLE001
                pass
        return {"ok": True, "started": True, "reviewed": len(cands), "moved": moved,
                "stopped": stop_reason or None, "disposition": disposition}
    finally:
        _AUTO_MOVE_LOCK.release()


# R14 backstop: every failed/issue move must reach Notion. `_am_notion` swallows
# its own errors so a Notion outage can never sink a traffic move — which means
# a run during an outage (or before the key was linked to this service, as on
# 2 Sep 2026) leaves ledger rows with `notion_task_url` null and NOBODY told.
# This sweep re-files exactly those rows. It is idempotent by construction: the
# `[auto-mover:<cid>:<kind>]` marker in the title means a task that is already
# open is reused, never duplicated.
_AM_ISSUE_PRIORITY = {"save_failed": "High", "counter_drop": "High",
                      "enqueue_rejected": "High"}
_AM_ISSUE_WHAT = {
    "save_failed": "Apply the recommended split by hand on the campaign's Messaging "
                   "tab, or say why it should not be applied.",
    "enqueue_rejected": "Apply the recommended split by hand on the campaign's "
                        "Messaging tab, or say why it should not be applied.",
    "counter_drop": "Check the version counters on this campaign, then decide "
                    "whether the auto-mover can be switched back on.",
    "flap": "Sanity-check the version data on this campaign - the winner keeps "
            "changing.",
    "human_owned": "Decide whether the auto-mover should keep managing Email 1 on "
                   "this campaign, then either leave it (it stays paused for 14 "
                   "days) or set the campaign switch back to inherit.",
}
_AM_ISSUE_HOW = {
    "save_failed": "- Open the campaign's Messaging tab and use the 1-click button "
                   "there.\n- If it fails again, the problem is upstream at "
                   "Smartlead, not the split.",
    "enqueue_rejected": "- Open the campaign's Messaging tab and use the 1-click "
                        "button there.\n- If it is refused again, read the reason on "
                        "Settings -> General; it is a rule, not an outage.",
    "counter_drop": "- Compare the version table against Smartlead.\n- The breaker "
                    "clears only by hand on Settings -> General.",
    "flap": "- Look at the Messaging tab: are the versions genuinely neck and neck?\n"
            "- If so, consider leaving the split alone until more data lands.",
    "human_owned": "- Look at the campaign's Messaging tab and decide the intended "
                   "split.\n- If the hand-set split should stand, leave it.\n- If the "
                   "mover should take over again, flip the campaign switch.",
}


def _am_issue_title(kind: str, name: str, step: int) -> str:
    if kind == "counter_drop":
        return f"Auto-mover STOPPED: a counter dropped on {name}"
    if kind == "flap":
        return f"Auto-mover reversed itself on {name}"
    if kind == "human_owned":
        return f"Auto-mover paused on {name}: someone set the split by hand"
    return f"Auto-mover could not move Email {step} on {name}"


def _auto_mover_run_route(one: str, max_moves, actor: str) -> tuple:
    """The Settings -> General "Run now" contract, extracted so it is testable.

    A ?campaign=<id> probe stays INLINE — it is one campaign, it is short, and
    its whole point is to answer with the exact skip/disposition. A full sweep
    is different: 10 moves at 20s spacing, each a Smartlead round trip, is
    minutes of work, and Render kills the request at ~9s. The old inline sweep
    therefore 502'd the page while the run carried on in the dead request's
    thread — an orphan job on the Tasks panel and no answer. So a sweep now
    behaves EXACTLY like the cron route: busy -> {busy:true}; otherwise start
    the SAME background runner and ack 202 {started:true} at once. The ledger,
    the General tables and the Tasks panel fill in as it works.

    Returns (http_status, body). For a sweep it returns BEFORE the runner does
    any work — the whole point of the fix."""
    one = str(one or "").strip()
    if one:
        return 200, auto_move_run(campaign_id=one, max_moves=max_moves or None)
    if _AUTO_MOVE_LOCK.locked():
        return 200, {"ok": True, "started": False, "busy": True,
                     "reason": "already_running", "disposition": []}

    def _bg(_m=max_moves or None, _actor=actor):
        try:
            r = auto_move_run(max_moves=_m)
            log_activity("/api/auto-mover/run",
                         payload={"reviewed": r.get("reviewed"),
                                  "moved": r.get("moved"),
                                  "stopped": r.get("stopped")},
                         actor=_actor, action="auto_move_done", entity="campaigns")
        except Exception as e:  # noqa: BLE001 — a failed run must be visible
            log_activity("/api/auto-mover/run", payload={"error": str(e)[:200]},
                         actor=_actor, action="auto_move_failed", entity="campaigns")
    threading.Thread(target=_bg, daemon=True).start()
    return 202, {"ok": True, "started": True, "disposition": []}


def auto_mover_refile_issues(limit: int = 100) -> dict:
    """Re-file the Notion Client Task for every auto_mover_moves row that failed
    and never got one. Returns {ok, filed: [...], skipped: [...]}.

    Judging-free: it reads what the runner already decided and files the task
    the runner would have filed. It never touches Smartlead and never moves
    traffic. `thin_evidence` rows are deliberately NOT filed — R14 sends those
    to the General digest, not to Notion."""
    try:
        n = max(1, min(500, int(limit or 100)))
    except (TypeError, ValueError):
        n = 100
    try:
        rows = sb("GET", "auto_mover_moves?select=id,campaign_id,step,action,winner,"
                  "mode,outcome,issue_kind,notion_task_url,created_at"
                  "&outcome=in.(failed,issue)&notion_task_url=is.null"
                  f"&order=created_at.asc&limit={n}")
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "message": f"ledger read failed: {str(e)[:200]}",
                "filed": [], "skipped": []}
    if not isinstance(rows, list):
        return {"ok": False, "message": "ledger unreadable", "filed": [], "skipped": []}

    filed: list = []
    skipped: list = []
    for r in rows:
        rid = r.get("id")
        cid = str(r.get("campaign_id") or "").strip()
        kind = str(r.get("issue_kind") or "").strip() or "save_failed"
        if not cid:
            skipped.append({"id": rid, "reason": "no campaign id"})
            continue
        if kind == "thin_evidence":
            skipped.append({"id": rid, "campaign_id": cid,
                            "reason": "thin_evidence goes to the General digest, not Notion"})
            continue
        meta = _am_meta(cid)
        name = meta.get("name") or f"Campaign {cid}"
        client = meta.get("client") or ""
        step = r.get("step") if r.get("step") is not None else _AM_STEP
        action = str(r.get("action") or "a move")
        why = (f"The mover asked for {action} on {r.get('created_at')} and it did not "
               f"land ({kind}). Nothing has moved on Email {step} since, and the issue "
               "was never raised because the Notion channel was unavailable at the time.")
        if kind == "counter_drop":
            why = (f"After the mover's {action} save on {r.get('created_at')} a version "
                   "counter dropped. The whole feedback loop depends on those counters "
                   "surviving our own writes.")
        elif kind == "flap":
            why = (f"The mover reversed itself on {r.get('created_at')} (now backing "
                   f"{r.get('winner') or 'an even split'}) inside {_AM_FLAP_HOURS} hours. "
                   "That is allowed - the mover always follows the latest data - but a "
                   "rapid reversal usually means the versions are too close to separate.")
        url = _am_notion(
            cid, kind, _am_issue_title(kind, name, step), client,
            _am_issue_body(cid, name,
                           _AM_ISSUE_WHAT.get(kind, _AM_ISSUE_WHAT["save_failed"]),
                           why,
                           _AM_ISSUE_HOW.get(kind, _AM_ISSUE_HOW["save_failed"])),
            _AM_ISSUE_PRIORITY.get(kind, "Medium"))
        if not url:
            skipped.append({"id": rid, "campaign_id": cid, "issue_kind": kind,
                            "reason": "Notion did not return a task url"})
            continue
        stored = True
        try:
            sb("PATCH", f"auto_mover_moves?id=eq.{int(rid)}", {"notion_task_url": url})
        except Exception as e:  # noqa: BLE001 — the task exists; say so honestly
            stored = False
            print(f"[auto-mover] refile: ledger write-back failed for {rid}: {e}",
                  file=sys.stderr)
        filed.append({"id": rid, "campaign_id": cid, "campaign": name,
                      "client": client, "issue_kind": kind,
                      "priority": _AM_ISSUE_PRIORITY.get(kind, "Medium"),
                      "notion_task_url": url, "stored_on_row": stored})
    return {"ok": True, "checked": len(rows), "filed": filed, "skipped": skipped}


# ── Optimisation Queue (morning task routine) — config + daily run log ───────
# Single source of truth for the team's morning optimisation routine (Settings →
# Task Queue). Each person's Claude routine READS its kinds + client exclusions
# from /api/optiqueue/config at every run (nothing is hardcoded in a prompt),
# and POSTS its run summary to /api/optiqueue/report so the panel can show, per
# day: created / completed / reassigned / dismissed / unattended. Storage rides
# the deliverability_audit_cache KV rows (same pattern as ui_prefs — no new
# table, no migration): "optiqueue_config" + one "optiqueue_log_<date>" per day.
_OPTIQ_KINDS = ("offer", "scale-winner", "copy-solo", "new-versions", "pattern", "list-audit")
_OPTIQ_DEFAULT_CONFIG = {
    "labels": {"offer": "Add new offers", "scale-winner": "Scale the winner",
               "copy-solo": "Drop dead-weight variants", "new-versions": "Add new versions",
               "pattern": "Add more of who replies", "list-audit": "Audit the list"},
    # role defaults (Bjion, 31 Aug 2026) — people may edit their own kinds/exclusions
    "people": {
        "Asad":  {"kinds": ["list-audit", "scale-winner", "copy-solo", "pattern"],
                  "exclude_clients": [], "notion_email": "asad.rafique@navreo.ai"},
        "Yasir": {"kinds": ["offer", "new-versions"],
                  "exclude_clients": [], "notion_email": "yasir@navreo.ai"},
    },
    "due": {"same_day": ["scale-winner", "copy-solo"], "working_days": 3},
}


def _optiq_kv(kv_id: str):
    rows = sb("GET", f"deliverability_audit_cache?id=eq.{kv_id}&select=blob") or []
    return rows[0].get("blob") if rows and isinstance(rows[0].get("blob"), dict) else None


def _optiq_kv_put(kv_id: str, blob: dict) -> None:
    sb("POST", "deliverability_audit_cache?on_conflict=id",
       {"id": kv_id, "blob": blob, "ts": _dtmod.datetime.utcnow().isoformat() + "Z"},
       prefer="resolution=merge-duplicates,return=minimal")


def optiq_config_get() -> dict:
    stored = _optiq_kv("optiqueue_config") or {}
    cfg = json.loads(json.dumps(_OPTIQ_DEFAULT_CONFIG))  # deep copy
    for name, p in (stored.get("people") or {}).items():
        mine = cfg["people"].setdefault(name, {"kinds": [], "exclude_clients": []})
        if isinstance(p.get("kinds"), list):
            mine["kinds"] = [k for k in p["kinds"] if k in _OPTIQ_KINDS]
        if isinstance(p.get("exclude_clients"), list):
            mine["exclude_clients"] = [str(c).strip() for c in p["exclude_clients"] if str(c).strip()]
        if p.get("notion_email"):
            mine["notion_email"] = str(p["notion_email"])
    for k in ("updated_at", "updated_by"):
        if stored.get(k):
            cfg[k] = stored[k]
    # coverage guard: a kind nobody receives means cards nobody is assigned
    owned = {k for p in cfg["people"].values() for k in p.get("kinds", [])}
    cfg["unowned_kinds"] = sorted(set(_OPTIQ_KINDS) - owned)
    return cfg


def optiq_config_set(patch: dict, who: str) -> dict:
    """Deep-merge a {people: {name: {kinds/exclude_clients}}} patch onto the
    stored config. Only those two per-person fields are writable — labels, due
    rules and the kind list itself stay code-owned."""
    stored = _optiq_kv("optiqueue_config") or {"people": {}}
    people = stored.setdefault("people", {})
    for name, p in (patch.get("people") or {}).items():
        if not isinstance(p, dict):
            continue
        mine = people.setdefault(str(name), {})
        if isinstance(p.get("kinds"), list):
            mine["kinds"] = [k for k in p["kinds"] if k in _OPTIQ_KINDS]
        if isinstance(p.get("exclude_clients"), list):
            mine["exclude_clients"] = [str(c).strip() for c in p["exclude_clients"] if str(c).strip()][:40]
    stored["updated_at"] = _dtmod.datetime.utcnow().isoformat() + "Z"
    stored["updated_by"] = who or "unknown"
    _optiq_kv_put("optiqueue_config", stored)
    return optiq_config_get()


_OPTIQ_COUNT_FIELDS = ("created", "completed", "reassigned", "dismissed", "unattended")


def optiq_report_set(report: dict, who: str) -> dict:
    """Idempotent per person+date: a routine re-run the same day replaces its
    own entry, never appends a duplicate. Counts are clamped ints; the title
    lists (what exactly was completed / reassigned / …) are capped so a runaway
    payload can't bloat the day's KV row."""
    person = str(report.get("person") or "").strip() or "unknown"
    date = str(report.get("date") or "").strip()[:10] or _dtmod.date.today().isoformat()
    entry = {"at": _dtmod.datetime.utcnow().isoformat() + "Z", "by": who or person}
    for f in _OPTIQ_COUNT_FIELDS:
        try:
            entry[f] = max(0, min(int(report.get(f) or 0), 999))
        except (TypeError, ValueError):
            entry[f] = 0
        titles = report.get(f + "_titles")
        if isinstance(titles, list):
            entry[f + "_titles"] = [str(t)[:160] for t in titles[:60]]
    kv_id = "optiqueue_log_" + date
    day = _optiq_kv(kv_id) or {"date": date, "runs": {}}
    day["runs"][person] = entry
    _optiq_kv_put(kv_id, day)
    return {"date": date, "person": person, **{f: entry[f] for f in _OPTIQ_COUNT_FIELDS}}


def optiq_summary(days: int = 14) -> dict:
    days = max(1, min(days, 31))
    today = _dtmod.date.today()
    ids = ["optiqueue_log_" + (today - _dtmod.timedelta(days=i)).isoformat() for i in range(days)]
    rows = sb("GET", "deliverability_audit_cache?id=in.(" + ",".join(ids) + ")&select=id,blob") or []
    by_id = {r["id"]: r.get("blob") for r in rows if isinstance(r.get("blob"), dict)}
    out = []
    for kv_id in ids:
        blob = by_id.get(kv_id)
        if blob and blob.get("runs"):
            out.append(blob)
    totals = {f: 0 for f in _OPTIQ_COUNT_FIELDS}
    for day in out:
        for entry in day["runs"].values():
            for f in _OPTIQ_COUNT_FIELDS:
                totals[f] += int(entry.get(f) or 0)
    return {"days": out, "totals": totals, "window_days": days}


def _client_hidden(label) -> bool:
    """A demo client is hidden from day-to-day surfaces unless the toggle is ON.
    The single test every display builder calls so demo data never leaks in by default."""
    return is_demo_client(label) and not show_demo_clients()


